window.ENAMED_LOCAL_QUESTION_BANK=window.ENAMED_LOCAL_QUESTION_BANK||{};window.ENAMED_LOCAL_QUESTION_BANK["medcurso:medcurso-hemato-hem-2"]={"block":"medcurso:medcurso-hemato-hem-2","label":"Medcurso · HEM 2","count":453,"questions":[{"id":"medcurso-hemato-hem-2-281095","number":"281095","sourceNumber":"281095","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Paciente de 65 anos com diagnóstico de Mieloma Múltiplo. Sobre a Doença, é\nINCORRETO afirmar:","options":{"A":"Uma das manifestações mais comuns é dor óssea.","B":"O indivíduo com mieloma múltiplo pode desenvolver insuficiência renal.","C":"A pseudo-hiponatremia pode ser encontrada no mieloma.","D":"O nível de creatina plasmática está associada ao prognóstico.","E":"O depósito de amiloide constitui o fator essencial para o aparecimento da lesão renal associada\nà doença."},"answer":"E","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-281143","number":"281143","sourceNumber":"281143","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Em relação aos exames laboratoriais em paciente pediátrico com história de\nsangramento é CORRETO afirmar que:","options":{"A":"Na insuficiência hepática, a contagem de plaquetas está diminuída, o tempo de atividade de\nprotrombina está alterado e o tempo de tromboplastina tecidual ativado está normal.","B":"Na deficiência de vitamina K, a contagem de plaquetas está diminuída, o tempo de atividade de\nprotrombina está alterado e o tempo de tromboplastina tecidual ativado está normal.","C":"Nas hemofilias A e B, a contagem de plaquetas está normal e o tempo de atividade de\nprotrombina e o tempo de tromboplastina tecidual ativado estão alterados.","D":"Na aplasia medular, a contagem de plaquetas está diminuída e o tempo de atividade de\nprotrombina e o tempo de tromboplastina tecidual ativado estão normais.","E":"Na coagulação intravascular disseminada, a contagem de plaquetas está diminuída, o tempo de\natividade de protrombina está normal e o tempo de tromboplastina tecidual ativado está alterado."},"answer":"D","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-281150","number":"281150","sourceNumber":"281150","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Menino de três anos de idade é admitido no Pronto-Atendimento com queixa de\nepistaxe espontânea há algumas horas, de volume\npequeno. A mãe do paciente relata história de\ninfecção viral do trato gastrointestinal (diarreia aguda) há 2 semanas, com resolução completa. Ao\nexame: bom estado geral, corado, hidratado. Ausculta cardíaca e pulmonar sem alterações. Baço,\nfígado e linfonodos não palpáveis. Equimoses e petéquias evidentes em membros inferiores, sem\noutras alterações. Hemograma evidenciando: hemoglobina 13,0 g/dL; VCM 80 fL; leucócitos\n9.700/mm3, com contagem diferencial normal; plaquetas 15.000/mm3 ; 1% de reticulócitos. O\ndiagnóstico mais provável é:","options":{"A":"doença de Gaucher.","B":"púrpura trombocitopênica trombótica.","C":"púrpura trombocitopênica idiopática.","D":"síndrome hemolítico-urêmica.","E":"leucemia aguda."},"answer":"C","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-247140","number":"247140","sourceNumber":"247140","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Qual das doenças relacionadas é caracterizada como causadora de trombofilia\nsecundária?","options":{"A":"Síndrome antifosfolípede.","B":"Deficiência de proteína C e S.","C":"Deficiência de antitrombina III.","D":"Resistência à proteína C ativada causada ela presença de molécula anormal do fator V Leiden.","E":"Mutação 20210 de protrombina."},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-247157","number":"247157","sourceNumber":"247157","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Mulher de 42 anos deverá ser submetida a cirurgia eletiva de colecistectomia. Nega\nhistória pessoal e familiar de sangramento. Os exames pré-operatórios mostram: RNI = 1,02\n(normal até 1,2); TTPA = 2,59 (normal até 1,25); TTPA com adição de plasma normal = 1,05.\n\nAssinale o teste que permite prosseguir de forma correta a investigação.","options":{"A":"Dosagem de fator II da coagulação.","B":"Dosagem de fator XII da coagulação.","C":"Dosagem de fator XIII da coagulação.","D":"Pesquisa de inibidor da coagulação dependente de fosfolipede.","E":"Dosagem de fator V da coagulação."},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-247183","number":"247183","sourceNumber":"247183","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Adolescente Masculino, 16 anos de idade, apresenta história de adenomegalia cervical\nunilateral há seis meses de crescimento progressivo e, nos últimos dois meses, apresenta febre\ndiária, emagrecimento e sudorese. O diagnóstico mais provável é","options":{"A":"Linfoma de Hodgkin.","B":"Linfoma de Burkitt.","C":"Neuroblastoma.","D":"Adenocarcinoma de parótida.","E":"Carcinoma de tireoide."},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-217658","number":"217658","sourceNumber":"217658","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Assinale a alternativa que NÃO apresenta um aspecto prognóstico relevante nas\nLeucemias Linfocíticas Agudas (LLAs).","options":{"A":"Leucometria inicial.","B":"Número de cromossomos no cariótipo.","C":"Febre.","D":"Idade avançada."},"answer":"C","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-182619","number":"182619","sourceNumber":"182619","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Paciente com proteína monoclonal sérica ? 3 g/dl e/ou células plasmáticas na medula\nóssea maior ou igual a 10% e ausência de anemia, insuficiência renal, hipercalcemia e lesões\nósseas líticas. O diagnóstico mais provável dessa condição é:","options":{"A":"Gamopatia monoclonal de significado indeterminado.","B":"Mieloma múltiplo indolente.","C":"Mieloma múltiplo.","D":"Leucemia de células plasmáticas."},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-183158","number":"183158","sourceNumber":"183158","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Sabe-se, hoje, que em cerca de 20% a 60% dos casos de TEV, uma mutação no fator\nV devido à substituição de aminoácidos\n(arginina por glutamina), leva a que esse fator, torne-se\nresistente a que proteína:","options":{"A":"Proteína S ativada.","B":"Proteína C ativada.","C":"Antitrombina,","D":"Plasminogênio.","E":"Heparina. Clínica Médica Página 5"},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-37089","number":"37089","sourceNumber":"37089","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"A causa mais comum de insuficiência renal no Mieloma Múltiplo é:","options":{"A":"Síndrome de Fanconi do adulto.","B":"Amiloidose.","C":"Hiperuricemia.","D":"Infiltração por células neoplásicas.","E":"Hipercalcemia."},"answer":"E","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-29415","number":"29415","sourceNumber":"29415","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"A presença de manifestação hemorrágica nos pacientes com leucemia aguda está\nrelacionada a:","options":{"A":"Hepatoesplenomegalia.","B":"Infecções oportunistas.","C":"Recidiva pós-tratamento.","D":"Lise tumoral.","E":"Trombocitopenia."},"answer":"E","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-29368","number":"29368","sourceNumber":"29368","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Paciente de 58 anos, sexo masculino, com quadro de fadiga, perda de peso, sudorese\ne febrícula. No exame físico apresenta palidez,\nesplenomegalia volumosa e manifestações\nhemorrágicas. O hemograma revela leucocitose de 50.000/ul com predomínio dos mielócitos. Tem\ncomo característica a presença do cromossomo Philadelphia:","options":{"A":"Síndrome mielodisplásica","B":"Leucemia Linfocítica aguda","C":"Leucemia Mielocítica Crônica","D":"Reação leucemoide","E":"Leucemia Mielocítica Aguda"},"answer":"C","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-369524","number":"369524","sourceNumber":"369524","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Mulher, 32 anos de idade, procura atendimento na Unidade Básica de Saúde (UBS)\ndevido a equimoses espontâneas em\ndiferentes regiões do corpo, incluindo membros inferiores e\nsuperiores, com duração de, aproximadamente, 2 semanas. Não há relato de trauma recente. No\nexame físico observam-se petéquias disseminadas e contusões de diferentes estágios de evolução.\nA paciente nega história anterior de sangramentos anormais. Solicitados exames complementares\nque evidenciam Hb: 12,5g/dL, leucócitos 7500cels/ mm³, plaquetas: 18.000/mm³, Cr: 0,5mg/dL, Ur\n17mg/dL. Esfregaço de sangue periférico com presença de macroplaquetas e ausência de\nfragmentação eritrocitária. Considerando o caso, indique o diagnóstico mais provável, dentre os\napresentados a seguir:","options":{"A":"Púrpura de Henoch-Schönlein.","B":"Síndrome de Evans.","C":"Púrpura trombocitopênica idiopática.","D":"Púrpura trombótica trombocitopênica."},"answer":"C","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-343156","number":"343156","sourceNumber":"343156","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"A leucemia-linfoma de células T do adulto (ATLL) na forma crônica pode ter sua\nevolução clínica classificada em tipo desfavorável ou favorável. Sendo correto o item:","options":{"A":"O tipo favorável tem curso rápido, com sobrevida de 15 meses. Laboratorialmente, são\nfrequentes as elevações da ureia, creatinina e DHL.","B":"O tipo desfavorável tem curso rápido, com sobrevida de 15 meses. Laboratorialmente, são\nfrequentes as elevações da ureia, creatinina e DHL.","C":"O tipo desfavorável tem curso lento, com sobrevida de 15 meses. Laboratorialmente, são\nfrequentes as elevações da ureia, creatinina e DHL.","D":"O tipo desfavorável tem curso rápido, com sobrevida de 50 meses. Laboratorialmente, são\nfrequentes as elevações da ureia, creatinina e não DHL."},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-343160","number":"343160","sourceNumber":"343160","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"A forma linfomatosa da leucemia-linfoma de células T do adulto (ATLL) é:","options":{"A":"Caracterizada por linfonodomegalia, com comprometimento do sangue periférico; representa\n20% dos casos, sendo na maior parte das vezes\numa doença avançada. A hipercalcemia pode\nestar presente, assim como lesões cutâneas, incluindo rash eritematoso, pápulas e nódulos, por\nvezes com ulceração.","B":"Caracterizada por linfonodomegalia, mas sem comprometimento do sangue periférico;\nrepresenta 20% dos casos, sendo na maior parte das\nvezes uma doença avançada. A\nhipercalcemia pode estar presente, assim como lesões cutâneas, incluindo rash eritematoso,\npápulas e nódulos, por vezes com ulceração.","C":"Caracterizada por linfonodomegalia, mas sem comprometimento do sangue periférico;\nrepresenta 20% dos casos, sendo na maior\nparte das vezes uma doença avançada. A\nhipercalcemia nunca pode estar presente, assim como lesões cutâneas, incluindo rash eritematoso,\npápulas e nódulos, por vezes com ulceração.","D":"Caracterizada por linfonodomegalia, mas sem comprometimento do sangue periférico;\nrepresenta 20% dos casos, sendo na maior parte das\nvezes uma doença avançada. A\nhipercalcemia pode estar presente, assim como lesões cutâneas, incluindo rash eritematoso,\npápulas e nódulos, mas não com ulceração."},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-343170","number":"343170","sourceNumber":"343170","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"A leucemia-linfoma de células T do adulto (ATLL), está de acordo com o seguinte item:","options":{"A":"é uma doença não linfoproliferativa agressiva de células T maduras, com diversas características\nclínicas, etiologicamente associada ao HTLV-1.","B":"é uma doença linfoproliferativa agressiva de células T maduras, com diversas características\nclínicas, etiologicamente não associada ao HTLV-1.","C":"é uma doença linfoproliferativa indolente de células T maduras, com diversas características\nclínicas, etiologicamente associada ao HTLV-1.","D":"é uma doença linfoproliferativa agressiva de células T maduras, com diversas características\nclínicas, etiologicamente associada ao HTLV-1."},"answer":"D","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-314199","number":"314199","sourceNumber":"314199","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"O abciximab é um anticorpo monoclonal, sendo correto o item:","options":{"A":"Que atua como bloqueador competitivo e irreversível dos receptores de GP IIb/IIIa. Tem\n\nmeia-vida plasmática curta de 5 a 10min, e sua meia-vida biológica é de 6 a 12h após a injeção de\num bolus isolado.","B":"Que atua como bloqueador não competitivo e reversível dos receptores de GP IIb/IIIa. Tem\nmeia-vida plasmática curta de 5 a 10min, e sua meia-vida biológica é de 6 a 12h após a injeção de\num bolus isolado.","C":"Que atua como bloqueador não competitivo e irreversível dos receptores de GP IIb/IIIa. Tem\nmeia-vida plasmática curta de 5 a 10min, e sua meia-vida biológica é de 6 a 12h após a injeção de\num bolus isolado.","D":"Que não atua como bloqueador não competitivo e irreversível dos receptores de GP IIb/IIIa. Tem\nmeia-vida plasmática curta de 5 a 10min, e sua meia-vida biológica é de 6 a 12h após a injeção de\num bolus isolado."},"answer":"C","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-279045","number":"279045","sourceNumber":"279045","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Das alternativas apresentadas abaixo, assinale a correta considerando-se o diagnóstico\nde neutropenia febril.","options":{"A":"Tem a mesma conotação para os pacientes em tratamento oncológico e para os pacientes\nportadores de aplasia medular medicamentosa.","B":"Precisa ser tratada o mais precocemente possível para reduzir a morbidade e a mortalidade dos\npacientes em tratamento quimioterápico.","C":"Deve ser considerada também para pacientes febris que estão fora de tratamento\nantineoplásico.","D":"É considerada um diagnóstico de exclusão, motivo pelo qual deve-se buscar exaustivamente a\ncausa da febre antes de instituir o tratamento."},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-249190","number":"249190","sourceNumber":"249190","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Preferencialmente, recomenda-se que se usem novos anticoagulantes orais NOACs em\nvez da varfarina, devido à sua\nprevisibilidade de efeito. Sendo adequado que:","options":{"A":"NOAC deve ser escolhido de acordo com o conhecimento médico já estabelecido nesse\ncontexto e nas doses previamente estudadas.","B":"NOAC não deve ser escolhido de acordo com o conhecimento médico já estabelecido nesse\ncontexto e nas doses previamente estudadas.","C":"NOAC deve ser escolhido em desacordo com o conhecimento médico já estabelecido nesse\ncontexto e nas doses previamente estudadas.","D":"NOAC deve ser escolhido de acordo com o conhecimento médico já estabelecido nesse\ncontexto e nas doses empiricas."},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-212175","number":"212175","sourceNumber":"212175","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Dadas as afirmativas sobre as doenças hematológicas e cirurgia: I. A laparoscopia é\ncontraindicada no tratamento das PTI. II. A resposta completa à esplenectomia no tratamento das\nPTI pode chegar a 80%. III. O tratamento de primeira linha das Púrpuras Trombocitopênicas\nImunológicas (PTI) é a esplenectomia. Verifica-se que está(ão) CORRETA(S):","options":{"A":"I, apenas.","B":"II, apenas.","C":"III, apenas.","D":"I e II, apenas.","E":"I, II e III."},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-215488","number":"215488","sourceNumber":"215488","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Todas as alternativas a seguir estão associadas a risco aumentado de lise tumoral,\nEXCETO:","options":{"A":"Metástase extensa.","B":"Desidratação.","C":"Insuficiência hepática prévia ao diagnóstico de câncer.","D":"Leucócitos aumentados."},"answer":"C","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-219889","number":"219889","sourceNumber":"219889","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Homem de 32 anos com diagnóstico de diabetes mellitus tipo I encontra-se internado\nem Unidade de Terapia Intensiva por quadro\nséptico secundário a abscesso perianal e apresenta\nsangramento em sítios múltiplos associado a trombocitopenia. Neste contexto, qual das alterações\nabaixo NÃO é esperada?","options":{"A":"Aumento do tempo de tromboplastina parcial ativada.","B":"Diminuição dos níveis séricos de fibrinogênio.","C":"Esquizócitos no sangue periférico.","D":"Produtos de degradação da fibrina diminuídos."},"answer":"D","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-219870","number":"219870","sourceNumber":"219870","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Homem de 53 anos procura auxílio médico devido à massa cervical não dolorosa, que\nfoi notada há cerca de dois meses. Relata\nque, quando bebe um a dois copos de vinho, a massa\ncervical se torna dolorosa. Ele também se queixa de febre intermitente, sudorese noturna, prurido e\nperda de peso superior a 10% do peso corporal habitual, no último mês. Ao exame físico, palpa-se\nlinfonodo de aproximadamente 3 cm na região cervical, à esquerda, de consistência fibroelástica.\n\nVários outros linfonodos cervicais são também palpáveis à esquerda, assim como um linfonodo na\nregião axilar esquerda. O fígado está aumentado, mas não há esplenomegalia ao exame. Trouxe\nconsigo radiografia de tórax que estava normal. Considerando-se esses dados, qual é o diagnóstico\nMAIS PROVÁVEL?","options":{"A":"Linfoma de Hodgkin.","B":"Mononucleose infecciosa.","C":"Sarcoidose.","D":"Tricoleucemia."},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-181316","number":"181316","sourceNumber":"181316","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"As transfusões de hemocomponentes nunca foram tão seguras como na atualidade.\nEntretanto, como em qualquer procedimento\nmédico, em algumas situações podem ocorrer reações\nadversas. Qual a reação transfusional aguda imunológica mais comum?","options":{"A":"Anafilática.","B":"Hemolítica aguda.","C":"Não hemolítica febril.","D":"Contaminação bacteriana.","E":"TRALI (Transfusion Related Acute Lung Injury)."},"answer":"C","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-181419","number":"181419","sourceNumber":"181419","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"A síndrome de lise tumoral é uma emergência oncológica caracterizada por\ncomplicações metabólicas decorrentes da morte\ncelular de neoplasias malignas com alto índice\nproliferativo. Qual a alternativa que contempla os principais sinais e sintomas dessa síndrome?","options":{"A":"Hiperfosfatemia, hipercalemia, hipercalcemia falência renal, hiperuricemia.","B":"Hiperfosfatemia, hipercalemia, hipocalcemia, falência renal, arritmias.","C":"Hipofosfatemia, hipercalemia, hipocalcemia, câimbras, arritmias.","D":"Hipofosfatemia, hipercalemia, hipercalcemia, vômitos, arritmias.","E":"Hipocalemia, hiperfosfatemia, hipocalcemia, oligúria, acidose metabólica."},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-183048","number":"183048","sourceNumber":"183048","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Criança de 9 anos internada na UTI Pediátrica por Linfoma de Burkitt, terminou primeiro\nciclo de quimioterapia. Evolui com\nSíndrome de Lise Tumoral. Nas últimas 24 horas teve diurese de\n0,25ml/Kg/hora. Das alternativas abaixo, qual é o diagnóstico mais improvável para essa paciente?","options":{"A":"Hiperfosfatemia.","B":"Hiperuricemia.","C":"Hipopotassemia.","D":"Arritmia cardíaca."},"answer":"C","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-182821","number":"182821","sourceNumber":"182821","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Criopreciptido pode ser indicado nas seguintes situações, EXCETO","options":{"A":"coagulação vascular disseminada.","B":"pacientes com INR maior que 4.","C":"transfusão maciça.","D":"profilaxia para pacientes com hemofilia A."},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-187809","number":"187809","sourceNumber":"187809","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Homem de 50 anos procurou atendimento médico devido à gengivorragia, epistaxe e\nfebre há 2 dias. Ao exame, temperatura axilar = 39°C; pressão arterial = 120/70 mmHg; frequência\ncardíaca = 120 bpm e frequência respiratória = 22 irpm. Foram auscultadas crepitações\nteleinspiratórias na base do hemitórax direito. Diante desses achados, optou-se por interná-lo para\ninvestigação adicional. Radiografia de tórax mostrou opacidade com broncograma aéreo na base\ndo pulmão direito. Hemograma evidenciou anemia (hemoglobina = 10,2 g/dl); leucocitose\n(12.000/mm³) com numerosos mieloblastos e plaquetopenia (15.000/mm³). Mielograma revelou\nmedula hipercelular com 45% de mieloblastos. Bastonetes de Auer foram observados nos blastos\npresentes na medula óssea e sangue periférico. Dentre as opções abaixo, qual é o diagnóstico\nMAIS PROVÁVEL para o quadro hematológico?","options":{"A":"Leucemia linfoide aguda.","B":"Leucemia mieloide aguda.","C":"Reação leucemoide.","D":"Síndrome mielodisplásica."},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-187861","number":"187861","sourceNumber":"187861","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Paciente com 65 anos de idade, refere aumento de região cervical com duração maior\nque 60 dias. Ao exame físico foram\nevidenciados linfonodos palpáveis na região cervical posterior,\nindolores e não aderentes aos planos profundos. Após esgotada propedêutica de orofaringe e trato\ndigestivo superior foi realizada biopsia excisional de linfonodo comprometido que demonstrou a\npresença de células grandes, com citoplasma discretamente basofílico, núcleos bilobulados,\ncircundadas por linfócitos T. Assinale a alternativa CORRETA para o diagnóstico MAIS PROVÁVEL\ndesse caso:","options":{"A":"Linfoma de Burkitt","B":"Linfoma de Hodgkin","C":"Linfoma linfoplasmocitário","D":"Linfoma folicular"},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-161133","number":"161133","sourceNumber":"161133","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Em relação à função esplênica, é INCORRETO afirmar que:","options":{"A":"Durante o desenvolvimento fetal tem função hematopoiética.","B":"As opsoninas produzidas no baço, como properdina e tuftsina, encontram-se com níveis séricos\naumentados após esplenectomia.","C":"É a substância biológica removida pelo baço em indivíduos saudáveis: corpos de Howell-Jolly,\ncorpos de Heinz, acantócitos, hemácias\nsenescentes.","D":"O baço está envolvido na destruição de plaquetas na Púrpura Trombocitopênica Imune."},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-158804","number":"158804","sourceNumber":"158804","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Uma criança do sexo masculino de dez anos de idade com dor no quadrante inferior\ndireito, náusea, vômito e febre. Feita a\nhipótese de apendicite aguda, é indicado tratamento\ncirúrgico. Nesse instante, os pais informam que o filho é portador de hemofilia A. Nesse caso, o que\ndeve ser administrado ao paciente?","options":{"A":"Fator VII.","B":"Fator VIII.","C":"Vitamina k.","D":"Plasma fresco.","E":"Crioprecipitado."},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-158734","number":"158734","sourceNumber":"158734","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Paciente de 50 anos, sexo feminino, foi internada com quadro de anorexia, náuseas,\nvômitos, fraqueza muscular, poliúria e polidipsia. Durante a investigação, foram evidenciados os\nseguintes resultados de exames: glicosúria, aminoacidúria, bicarbonatúria, hiperfosfatúria e\nhiperuricosúria. Qual a principal etiologia dessa síndrome em adultos?","options":{"A":"Doença de Wilson.","B":"Mieloma múltiplo.","C":"Saturnismo.","D":"Amiloidose.","E":"Cistinose."},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-109736","number":"109736","sourceNumber":"109736","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Paciente do sexo feminino, 25 anos, com história de dor torácica associada a prurido há\n5 meses. Ao RX de tórax, nota-se alargamento\ndo mediastino. Assinale abaixo a alternativa\ndiagnóstica mais provável diante desse caso:","options":{"A":"Timoma.","B":"Bócio multinodular tóxico.","C":"Linfoma.","D":"Aneurisma de aorta."},"answer":"C","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-109743","number":"109743","sourceNumber":"109743","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Paciente do sexo feminino, 60 anos, com história de lombalgia, emagrecimento e\nadinamia há dois meses. Em tratamento com\nfluoxetina e paracetamol sem melhora efetiva. Traz os\nseguintes resultados de exames laboratoriais para sua avaliação: Hb = 8.0 mg/dl; leucócitos =\n9.500/mm³; plaquetas = 175.000/mm³; ureia = 95 mg/dl; creatinina = 2.8 mg/dl; cálcio iônico = 2.1\nmmol/l; TSH e T4 livre normais. Diante desse caso clínico, assinale a hipótese diagnóstica MAIS\nprovável.","options":{"A":"Adenoma de paratireoide.","B":"Insuficiência renal crônica.","C":"Transtorno depressivo.","D":"Mieloma múltiplo."},"answer":"D","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-158396","number":"158396","sourceNumber":"158396","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Masculino, 74 anos, refere quadro de sangramentos cutâneos espontâneos há cerca de\n2 meses, chega ao PS com hematomas extensos\nem membros inferiores e superiores e hematúria\nsignificativa. Colheu exames que revelaram alteração de TTPA (Tempo de Tromboplastina Parcial\nAtivada) com relação R de 6,5 (normal até 1,20), não apresentava alterações em outros exames de\ncoagulação como TP (Tempo de Protrombina) e TT (Tempo de Trombina), e a contagem de\nplaquetas era normal. Ao exame, evidenciavam-se hematomas extensos em membro superior\ndireito. Qual a principal hipótese diagnóstica para o caso acima?","options":{"A":"Doença de von Willebrand.","B":"Síndrome de Weil.","C":"Síndrome antifosfolípide.","D":"Leucemia mieloide aguda.","E":"Hemofilia adquirida."},"answer":"E","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-158403","number":"158403","sourceNumber":"158403","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Masculino, 74 anos, refere quadro de sangramentos cutâneos espontâneos há cerca de\n2 meses, chega ao PS com hematomas extensos\nem membros inferiores e superiores e hematúria\nsignificativa. Colheu exames que revelaram alteração de TTPA (tempo de tromboplastina parcial\nativada) com relação R de 6,5 (normal até 1,20), não apresentava alterações em outros exames de\ncoagulação como TP (tempo de protrombina) e TT (tempo de trombina), e a contagem de plaquetas\nera normal. Ao exame, evidenciava-se hematomas extensos em membro superior direito. Quais\nopções terapêuticas para o controle de urgência do sangrento?","options":{"A":"DDAVP e concentrado de fator VIII.","B":"Concentrado de Plaquetas.","C":"Pulsoterapia com metilprednisolona EV.","D":"Plasmaferese.","E":"Hidratação + Ceftriaxona EV."},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-108583","number":"108583","sourceNumber":"108583","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Em um paciente com quadro de perda ponderal, febre e sudorese noturna, associada à\nlinfadenopatia hilar, o mais provável diagnóstico é:","options":{"A":"Doença de Hodgkin.","B":"Salmonelose.","C":"Toxoplasmose.","D":"Doença de Whipple.","E":"Doença de Chagas."},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-49576","number":"49576","sourceNumber":"49576","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Os chamados sintomas B (febre \"maior que\" 38°C, sudorese noturna e perda ponderal\n\"maior que\" 10%) são característicos de que patologia?","options":{"A":"Salmonelose.","B":"Amiloidose.","C":"Linfoma.","D":"Carcinoma broncogênico.","E":"Brucelose."},"answer":"C","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-362489","number":"362489","sourceNumber":"362489","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Durante atividade na UBS, você se depara com dois pacientes com astenia há 2\nsemanas e anemia grave. Paciente 1: homem\nde 21 anos de idade, Hb = 8,6 g/dl, VCM = 106,\nleucócitos = 920 mm3, neutrófilos = 210 mm3 e plaquetas 24.000 mm3; Paciente 2: homem de 67\nanos de idade, Hb = 9,5 g/dl, VCM = 94, leucócitos = 220.000 mm3, neutrófilos = 4.500 mm3,\nlinfócitos = 215.000 mm3 e plaquetas = 64.000 mm3. Qual paciente deve ter prioridade no\nencaminhamento para a unidade de urgência e por qual motivo?","options":{"A":"Paciente 1, por apresentar pancitopenia com neutropenia grave, tendo alto risco de neutropenia\nfebril e sangramentos.","B":"Paciente 1, por apresentar anemia mais grave e risco de descompensação hemodinâmica e\nsangramentos.","C":"Paciente 2, por apresentar leucocitose intensa, risco de hiperviscosidade e insuficiência\nrespiratória.","D":"Paciente 2, por apresentar linfocitose intensa e alto risco de síndrome de lise tumoral\nespontânea."},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-327223","number":"327223","sourceNumber":"327223","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Mulher, 21 anos, em avaliação pré-operatória de otoplastia evidenciou-se tempo de\ntromboplastina parcial ativado (TTPa) prolongado. Refere epistaxes frequentes e equimoses\nespontâneas desde a infância, e sangramento uterino anormal (ciclos menstruais com duração de\nmais de 10 dias, com coágulos e necessidade de absorvente noturno contínuo). Mãe com sintomas\nmenstruais semelhantes. Nega outros familiares com história de sangramentos. Nega hemartroses.\nNega procedimentos cirúrgicos prévios. Exame físico sem alterações. Exames laboratoriais: Hb:\n11,7g/dL; VCM: 78fL; GB: 6.200/µL; plaquetas: 250.000/µL; TTPa: 53 segundos (VN < 44,6); TP\n(Tempo de protrombina): 13,5 segundos (VN < 17,3). Qual elemento do sistema hemostático da\npaciente mais provavelmente está envolvido?","options":{"A":"Fator de von Willebrand","B":"Plaquetas","C":"Fibrinogênio","D":"Fator VIII da coagulação"},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-327224","number":"327224","sourceNumber":"327224","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Homem, 46 anos, retorna à consulta ambulatorial para resultado de exames após\nacidente vascular cerebral isquêmico há 5 semanas, com boa evolução da fase aguda.\n\nAntecedente pessoal: cirurgia bariátrica há 6 anos, sem acompanhamento ou medicações\nregulares. Hemoglobina = 14g/dL, VCM = 63fL,\nhemácias = 7.000.000/µL; leucócitos = 18.000/µL\n(segmentados 76%, linfócitos 10%, monócitos 5%; eosinófilos 6%, basófilos 3%), plaquetas =\n1.450.000/µL. Ferritina: 4ng/mL. Exame físico: baço palpável a 2 cm do rebordo costal esquerdo.\nQual é o diagnóstico?","options":{"A":"Trombofilia hereditária","B":"Traço talassêmico","C":"Anemia ferropriva","D":"Policitemia Vera"},"answer":"D","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-327260","number":"327260","sourceNumber":"327260","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Paciente do sexo feminino, 28 anos, com história de sangramento oral durante a\nescovação dos dentes, equimoses pelo corpo\nsem causa aparente e hipermenorréia. Seu exame\nfísico da cabeça, tórax e abdome não apresenta alterações dignas de nota. Não há massas ou\nvisceromegalias abdominais palpáveis. Observam-se equimoses em joelhos e petéquias em\nmembros inferiores. No seu hemograma, o hematócrito, a hemoglobina e o leucograma são\nnormais, mas a contagem de plaquetas é de 22.000. Encaminhada para acompanhamento com o\nHematologista, foi submetido a mielograma que evidenciou presença normal de megacariócitos e\nnão foi observado sinal de malignidade. O Hematologista iniciou tratamento clínico com corticóides,\nporém obteve resposta não satisfatória, sendo encaminhado ao Cirurgião para avaliação da\npossibilidade de esplenectomia. Sobre o caso acima, assinale a alternativa CORRETA:","options":{"A":"A esplenectomia é bem indicada para o caso já que a esferocitose descrita acima não\nrespondeu adequadamente ao tratamento clínico.","B":"A plaquetopenia deve ser manejada com transfusão de concentrado de plaquetas 24 horas\nantes do procedimento cirúrgico.","C":"A esplenectomia deve ser postergada já que a patologia descrita evolui com sucessivos infartos\nesplênicos, evoluindo para progressiva perda de massa esplênica e asplenia.","D":"Esta paciente deverá ser vacinada contra Haemophilus influenza, Streptococcus pneumoniae e\nNeisseria meningitidis cerca de 2 semanas antes da esplenectomia."},"answer":"D","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-298191","number":"298191","sourceNumber":"298191","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Idoso de 75 anos, saudável, sem queixas pregressas, vai ao médico do Programa de\nSaúde da Família (PSF) fazer os exames\nanuais para acompanhamento do seu quadro de\nhipertensão arterial e diabetes. O exame físico não mostrou alterações. O médico solicita um\nhemograma cujo resultado mostra acentuada leucocitose com linfocitose associada (13.470/mm3),\nsem alterações no eritrograma ou contagem de plaquetas. Diante do exposto, o diagnóstico mais\nprovável é de:","options":{"A":"Linfoma.","B":"Infecção viral.","C":"Infecção bacteriana.","D":"Leucemia linfoide crônica."},"answer":"D","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-256582","number":"256582","sourceNumber":"256582","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Sobre as transfusões sanguíneas e suas reações adversas, são condutas apropriadas,\nEXCETO:","options":{"A":"As reações transfusionais imediatas são aquelas que ocorrem em até 48 horas da infusão do\nhemocomponente.","B":"Solicitar culturas de sangue do paciente e da unidade transfundida na suspeita de contaminação\nbacteriana e iniciar antibióticos de amplo espectro.","C":"Administrar epinefrina subcutânea na reação anafilática.","D":"Tratar a lesão pulmonar aguda relacionada à transfusão (TRALI) com medidas de suporte com\noxigênio, diuréticos e frequentemente com ventilação mecânica."},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-208401","number":"208401","sourceNumber":"208401","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Uma paciente de quarenta anos de idade, previamente hígida, relatou metrorragia de\ngrande intensidade, acompanhada do surgimento de petéquias e equimoses disseminadas pelo\ncorpo, com início há cerca de duas semanas, mas há um mês já apresentava fadiga e seus pais\nnotaram palidez cutâneo-mucosa. Na admissão, o exame físico mostrou, além dos sinais\npreviamente citados, hepatomegalia discreta, hemorragias conjuntivais e na mucosa oral. A\nradiografia de tórax não revelou sinais de alargamento mediastinal. O hemograma apresentou os\nseguintes resultados: hemoglobina = 7,0 g/dl; plaquetas = 50.000; leucócitos = 40.000 céls/mm³. A\nanálise citológica do esfregaço do sangue periférico indicou presença de cerca de 20% de\nleucócitos de tamanho aumentado e citoplasma com grânulos e bastonetes de Auer. A hipótese\ndiagnóstica mais provável para esse quadro clínico é a de:","options":{"A":"Leucemia linfoide aguda.","B":"Leucemia linfoide crônica.","C":"Síndrome mielodisplásica.","D":"Leucemia mieloide aguda."},"answer":"D","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-176055","number":"176055","sourceNumber":"176055","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"As bactérias Gram-negativas mais frequentemente isoladas em hemoculturas de\npacientes neutropênicos são:","options":{"A":"Escherichia coli, Klebsiella e Serratia.","B":"Morganella, Proteus e Pseudomonas aeruginosa.","C":"Pseudomonas aeruginosa, Klebsiella e Escherichia coli.","D":"Pseudomonas aeruginosa, Enterobacter e Proteus."},"answer":"C","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-176085","number":"176085","sourceNumber":"176085","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Paciente masculino, 45 anos, pardo, com queixas vagas de fadiga e indisposição,\nnáuseas e vômitos. Notou aumento do volume\nabdominal. Ao exame físico: discreta palidez e\nesplenomegalia acentuada e indolor. O estudo hematológico revelou: hemácias = 3,2 milhões/mm³;\nHb = 9,8 g/dl; Ht = 29%; VCM = 90; HCM = 30,6: CHCM = 29,5; leucócitos = 187.000/mm³; blastos\n\n= 2%; promielócitos = 3%; mielócitos = 13%; metamielócitos = 10%; bastonetes = 20%;\n\nsegmentados = 35%; eosinófilos = 3%; basófilos = 2%; linfócitos = 3%; monócitos = 4%; plaquetas\n\n= 1.065.000/mm³. Qual a hipótese diagnóstica mais provável?","options":{"A":"Reação leucemoide.","B":"Trombocitemia essencial.","C":"Leucemia mieloide aguda.","D":"Leucemia mieloide crônica."},"answer":"D","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-151930","number":"151930","sourceNumber":"151930","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"O paciente é um homem de 50 anos referindo plenitude pós-prandial mesmo após\ncomer pequenas quantidades. Encontra-se\nhipocorado, anictérico e baço palpável 8 cm abaixo da\nreborda costal. O resto do exame físico é normal. Ht = 37%; plaquetas = 377.000/mm³. Contagem\nde leucócitos com 50.0000/mm³, granulócitos = 43%; bastões = 13%; metamielócitos = 18%;\nmielócitos = 10%; promielócitos = 2%; blastos = 2%; monócitos = 11%; basófilos = 2%, eosinófilos =\n2%; linfócitos = 1%. Qual é o diagnóstico mais provável?","options":{"A":"Leucemia linfocítica crônica.","B":"Leucemia mieloide crônica.","C":"Leucemia mieloide aguda.","D":"Anemia megaloblástica."},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-151939","number":"151939","sourceNumber":"151939","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Quais são as manifestações hemorrágicas mais marcantes e peculiares da hemofilia?","options":{"A":"Hemartroses.","B":"Grandes equimoses.","C":"Hemorragia do SNC.","D":"Hematomas importantes."},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-129813","number":"129813","sourceNumber":"129813","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"O exame que mais fidedignamente auxilia na avaliação da fase plaquetária da\ncoagulação sanguínea é:","options":{"A":"Tempo de sangramento.","B":"Plaquetometria.","C":"Tempo de retração do coágulo.","D":"Tempo de atividade de protrombina."},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-129811","number":"129811","sourceNumber":"129811","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"A mãe leva o filho de 3 anos, portador de síndrome de Down, ao seu consultório porque\na gengiva dele está sangrando há uma semana.\nRelata que ele está menos ativo que o habitual. O\nexame físico revela que a criança apresenta uma temperatura oral de 37,8°C, palidez,\nesplenomegalia, sangramento gengival e equimoses nas extremidades inferiores. Qual das opções\na seguir é o diagnóstico mais provável?","options":{"A":"Leucemia.","B":"Anemia aplástica.","C":"Púrpura trombocitopênica idiopática.","D":"Reação leucemoide."},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-107976","number":"107976","sourceNumber":"107976","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Homem branco com 48 anos é atendido para esclarecimento de pancitopenia e\nvolumosa esplenomegalia. Ao suspeitar de\nhiperesplenismo, você, obrigatoriamente, deve solicitar:","options":{"A":"Avaliação da medula óssea.","B":"Endoscopia digestiva alta.","C":"Biópsia hepática per cutânea.","D":"Ultrassonografia de abdômen superior."},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-82004","number":"82004","sourceNumber":"82004","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Num paciente com pancitopenia febril, hepatoesplenomegalia e linfonodomegalia\ngeneralizada, associadas a dor óssea e perda ponderal importante, deve-se atentar para\nocorrência das seguintes emergências, EXCETO:","options":{"A":"Síndrome de hiperviscosidade.","B":"Choque séptico.","C":"Crise vaso-oclusiva dolorosa falciforme.","D":"Hemorragia grave.","E":"Dispneia por compressão mediastinal."},"answer":"C","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-60912","number":"60912","sourceNumber":"60912","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"O Transplante de Medula Óssea (TMO) consiste na infusão venosa de células\nprogenitoras hematopoiéticas, com o objetivo de\nrestabelecer a função medular nos pacientes com\nmedula óssea danificada ou defeituosa. Em relação ao TMO, é INCORRETO que:","options":{"A":"As 3 modalidades de TMO são: autogênico, alogênico e singênico.","B":"As células-tronco podem ser coletadas da crista ilíaca, do sangue periférico ou do sangue de\ncordão umbilical.","C":"Entre as complicações do pós-TMO não se incluem as diarreias, as infecções virais e a doença\ndo enxerto contra o hospedeiro.","D":"Entre os exames solicitados para o receptor no pré-TMO estão o mielograma, a biópsia de\nmedula óssea e as sorologias para diversas doenças infecciosas.","E":"Entre as indicações neoplásicas para o TMO estão as leucemias e linfomas, e entre as não\nneoplásicas estão a anemia aplástica grave e algumas hemoglobinopatias (como talassemia maior\ne anemia falciforme)."},"answer":"C","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-46708","number":"46708","sourceNumber":"46708","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Adolescente, quinze anos, sexo feminino, apresenta tosse, febre, perda de peso,\ndispneia, palidez, dor torácica, disfagia,\nderrame pleural, linfadenopatia cervical e axilar. RX de\ntórax: massa mediastinal estendendo-se para hemitórax superior direito e comprimindo a carina. A\nhipótese diagnóstica é:","options":{"A":"Bócio mergulhante.","B":"Linfoma não Hodgkin.","C":"Carcinoma pulmonar indeterminado.","D":"Tuberculose.","E":"Tumor de Wilms."},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-26617","number":"26617","sourceNumber":"26617","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Marque a alternativa com a hipótese diagnóstica mais provável para o caso descrito\nabaixo: O paciente é um homem de 58 anos que\nestá internado em um hospital geral para uma\ncirurgia de hérnia inguinal. Encontra-se em bom estado geral. O exame físico é normal, exceto por\nalguns nódulos em região cervical, 1 x 1 cm, indolores, não aderidos a planos profundos. O Ht:\n42%; plaquetas: 335.000/mm³; leucócitos: 50.000/mm³; granulócitos: 4%; monócitos: 1%; linfócitos:\n95%.","options":{"A":"Leucemia Linfocítica Crônica (LLC).","B":"Leucemia Mieloide Crônica (LMC).","C":"Leucemia Linfocítica Aguda (LLA).","D":"Leucemia Mieloide Aguda (LMA).","E":"Hairy cell leukemia."},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-26676","number":"26676","sourceNumber":"26676","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"A paciente é uma mulher de 28 anos, referindo evolução de doença há dois meses com\nastenia, dispneia aos médios esforços que evoluiu para pequenos esforços. O exame físico revela\npalidez cutâneo-mucosa e sopro pansistólico. Petéquias estão presentes nos membros inferiores.\n\nNão há presença de visceromegalias palpáveis. Uma tênue hemorragia é notada no exame\noftalmoscópico. Ht = 19% (esfregaço\nnormocrômico normocítico), Reticulócitos = 1%, Plaquetas =\n8.000/mm³, Leucócitos = 50.000/mm³, Blastos = 95%, Granulócitos = 1%, Linfócitos = 4%. Marque\na alternativa com a hipótese diagnóstica mais provável para o caso descrito acima:","options":{"A":"Leucemia Mieloide Crônica (LMC).","B":"Leucemia Mieloide Aguda (LMA).","C":"Leucemia Linfocítica Aguda (LLA).","D":"Leucemia Linfocítica Crônica (LLC).","E":"Púrpura Trombocitopênica Imunológica (PTI)."},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-7471","number":"7471","sourceNumber":"7471","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Um Patologista estava fazendo um estudo de revisão de 145 casos de linfomas\n\nnão-Hodgkin nodais e extra-nodais. Utilizou a técnica de imunofenotipagem. Tinha cinco frascos de\nanticorpos monoclonais que marcavam células específicas (entre parênteses): anti-CD45 (todos os\nlinfócitos); anti-CD-20 (expressos em células B); anti-CD2 (todas as células T tímicas e\nperiféricas e\nem células natural killer); anti-CD33 (todos os progenitores mieloides e nos monócitos); anti-CD4\n(células T auxiliares periféricas). Na bateria de exames, qual letra estaria mais correta para\nestar de\nacordo com a incidência mundial de linfomas?","options":{"A":"Positividade para CD45 e todos os outros em igual quantidade.","B":"Positividade para CD45 e para CD20 maior que nos outros.","C":"Positividade para CD45 e para CD2 maior que nos outros.","D":"Positividade para CD45 e para CD33 maior que nos outros.","E":"Positividade para CD45 e para CD4 maior que nos outros."},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-10010","number":"10010","sourceNumber":"10010","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Menino de 8 anos com adenopatia cervical acentuada, com estado geral. Hemograma:\nintensa atipia dos linfócitos; levantado\nsuspeita de leucemia. Reação de Paul-Bunnell negativa.\n\nReação de Sabin-Feldman 1:4.000. Qual o provável diagnóstico?","options":{"A":"Toxoplasmose adquirida.","B":"Mononucleose.","C":"Doença Gaucher-juvenil.","D":"Citomegalovírus.","E":"Calazar."},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-62850","number":"62850","sourceNumber":"62850","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Paciente, oito anos de idade, procedente da zona rural, com quadro de febre há 30\ndias, acompanhada de adinamia, palidez e aumento do volume abdominal. Ao exame físico,\napática, febril, pálida. Ausculta cardiopulmonar com murmúrio rude sem creptos, bulhas\ntaquicárdicas. Abdome volumoso, fígado a 5 cm do RCD, baço a 12 cm do RCE. Os exames\nlaboratoriais mostravam hemoglobina = 5,2 g/dl; leucócitos = 2.800 (2% eosinófilos; 1% bastões;\n34% segmentados; 1% linfócitos atípicos; 60% linfócitos); plaquetas = 98.000/mm³. O exame\nindispensável para o estudo desse caso é:","options":{"A":"Mielograma.","B":"Morfologia das hemácias.","C":"Eletroforese de hemoglobina.","D":"Prova do laço.","E":"Formogel."},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-49270","number":"49270","sourceNumber":"49270","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Paciente, quatro anos de idade, apresenta queixa de sangramento nasal em episódios\nagudos, sem febre ou dor. Fez uso de vacina tríplice viral há quatro semanas. Ao exame físico,\nnota-se bom estado geral, eutrófico, presença de petéquias em abdome e MMII. Ausculta\ncardiopulmonar normal. Abdome plano sem visceromegalias. Exames laboratoriais mostram\nhemograma com anemia, plaquetas = 50.000/mm³. Presença de macroplaquetas no sangue\nperiférico. Mielograma com o setor megacariocítico hiperplasiado. Sumário de urina com hemácias\n\n+. Em relação a esse diagnóstico, é INCORRETO afirmar que:","options":{"A":"É definido como trombocitopenia isolada com medula óssea normal na ausência de outras\ncausas.","B":"O uso de esteroides e imunossupressores e a esplenectomia podem ser indesejáveis pelas\ncomplicações associadas.","C":"A redução da vida das plaquetas na circulação resulta em aumento de megacariócitos na\nmedula óssea.","D":"O diagnóstico é feito pela clínica e pela exclusão de outras etiologias.","E":"É uma vasculite, frequente na infância, mas que só ocorre em crianças portadoras de doença\nimunológica primária."},"answer":"E","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-34988","number":"34988","sourceNumber":"34988","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Em relação à aférese terapêutica, é correto afirmar, exceto:","options":{"A":"Leucaférese é usada comumente em pacientes com Leucemia Mieloide Aguda (LMA),\napresentando sintomas de leucoestase\nintravascular, ocasião em que a contagem de blastos\nultrapassa 50000 células/ul.","B":"A prescrição de troca de hemácias pode se justificar quando pacientes portadores de doença\nfalciforme apresentam acidente vascular\n\ncerebral, síndrome torácica aguda, priapismo ou disfunção de múltiplos órgãos como complicação\nda doença.","C":"Plasmaférese encontra nível de evidência III na síndrome de Guillain-Barré, segundo critérios da\nSociedade Americana para Aférese\n\n(ASFA).","D":"Plasmaférese encontra nível de evidência I na Púrpura Trombocitopênica Trombótica (PTT),\nsegundo critérios da Sociedade Americana\n\npara Aférese (ASFA).","E":"Pacientes com Miastenia gravis podem ser tratados tanto com plasmaférese quanto com\nimunoglobulina intravenosa, pois os ensaios clínicos publicados até o momento não têm mostrado\ndiferenças importantes na variação do escore muscular miastênico no 15º dia"},"answer":"E","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-34962","number":"34962","sourceNumber":"34962","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Paciente, 7 anos de idade, apresenta quadro de fraqueza, dores articulares, perda de\npeso. Ao exame físico, apresentava-se em regular estado geral; descorado; febril; aumento dos\ngânglios periféricos da cadeia cervical e inguinal; fígado a 5 cm do RCD e baço palpável a 4,5 cm.\nO hemograma apresentava Hb = 6,1 g/dl; Htc = 18%; leucócitos = 68.000/mm³ (com 20% de\nblastos, 10% de bastonetes, 21% de segmentados, 46% de linfócitos); plaquetas = 58.000/mm³. O\ndiagnóstico mais provável é:","options":{"A":"Leucemia.","B":"Calazar.","C":"Lúpus.","D":"Salmonelose septicêmica.","E":"Anemia falciforme."},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-343344","number":"343344","sourceNumber":"343344","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"A leucemia-linfoma de células T do adulto (ATLL), está de acordo com o seguinte item:","options":{"A":"é uma doença não linfoproliferativa agressiva de células T maduras, com diversas características\nclínicas, etiologicamente associada ao HTLV-1.","B":"é uma doença linfoproliferativa agressiva de células T maduras, com diversas características\nclínicas, etiologicamente não associada ao HTLV-1.","C":"é uma doença linfoproliferativa indolente de células T maduras, com diversas características\nclínicas, etiologicamente associada ao HTLV-1.","D":"é uma doença linfoproliferativa agressiva de células T maduras, com diversas características\nclínicas, etiologicamente associada ao HTLV-1."},"answer":"D","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-343358","number":"343358","sourceNumber":"343358","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Sobre as heparinas, fórmulas utilizadas no tratamento das doenças vasculares,\nassinale a correta.","options":{"A":"A dose de heparina não fraciona normalmente deve ser ajustada pela medida do TTPa (Tempo\nde Tromboplastina Parcial Ativada). No caso de\ndoses muito elevadas, como as administradas em\ncircuitos extracorpóreos no momento de cirurgia cardíaca, cirurgia vascular ou transplante hepático,\nestas são determinadas pelo TCA (tempo de coagulação ativado).","B":"O efeito anticoagulante da heparina de baixo peso molecular pode ser neutralizado rapidamente\npela protamina intravenosa, uma proteína catiônica\nque se liga fortemente à heparina.","C":"O pico da concentração de antifator Xa e antifator IIa plasmático é alcançado 3 a 4 h depois da\nadministração da heparina não fracionada.","D":"Diferente como na heparina não fracionada, os pacientes podem apresentar resistência às\nheparinas de baixo peso molecular pois também se ligam às células do endotélio e aos\nmacrófagos, com mudanças na sua farmacocinética."},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-215588","number":"215588","sourceNumber":"215588","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Paciente de 9 anos, com diagnóstico de linfoma de Burkitt, encontra-se internada na\nUTI pediátrica. Realizou primeiro ciclo de\nquimioterapia. Evoluiu com síndrome de lise tumoral. Nas\núltimas 24 horas, teve diurese de 0,25 ml/kg/hora. Das alternativas abaixo, qual é o diagnóstico\nmais improvável para essa paciente?","options":{"A":"Hiperfosfatemia.","B":"Hiperuricemia.","C":"Hipopotassemia.","D":"Insuficiência renal."},"answer":"C","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-157666","number":"157666","sourceNumber":"157666","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Sobre os hemocomponentes, marque a opção INCORRETA:","options":{"A":"O crioprecipitado contém a maior parte composta por fator VIIIC e parte do fibrinogênio do\nplasma original. Está indicado em diversas\npatologias, como hemofilia A, doença de von Willebrand\nou hipofibrinogenemia, entre outras.","B":"O plasma fresco congelado é indicado para pacientes com processos hemorrágicos por\ndeficiências múltiplas de fatores de coagulação,\nsecundárias à disfunção hepática, anticoagulação\noral (antagonistas da vitamina K), coagulação vascular disseminada, coagulopatias dilucionais,\npacientes com deficiência de antitrombina, proteína C e S, púrpura trombocitopênica trombótica,\nsíndrome hemolítico-urêmica e pacientes submetidos à circulação mecânica.","C":"O sangue total restabelece a capacidade de transporte de oxigênio e promove a expansão de\nvolume, sendo indicado para pacientes com sangramentos profusos, que desenvolvam choque\nhemorrágico. Uma unidade de sangue total acarretará em um incremento aproximado de 3 g/dl na\nconcentração de hemoglobina ou 3 a 4% do hematócrito.","D":"As transfusões de concentrados de plaquetas podem ter indicações de caráter terapêutico ou\nprofilático. Uma unidade de plaqueta acarretará no aumento de 5 a 12 mil/mm³/m². Sabe-se que\ncinquenta mil/mm³ acarretam hemostasia adequada, desde que o sistema de coagulação,\nfibrinolítico e endotélio estejam em condições satisfatórias."},"answer":"C","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-139787","number":"139787","sourceNumber":"139787","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Sobre as Leucemias na infância, julgue os itens expostos a seguir. I. A dor óssea é\numa manifestação clínica frequente,ocorrendo em\ntorno de 20 a 30% dos casos.; II. A maioria dos\ncasos é de origem mieloide.; III. A doença é mais frequente no sexo feminino. Está CORRETO o\ncontido em:","options":{"A":"I, apenas.","B":"I e II, apenas.","C":"II e III, apenas.","D":"I, II e III."},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-134687","number":"134687","sourceNumber":"134687","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"A Linfadenomegalia é considerada, na presença de nódulos linfáticos cervicais, com\nmais de:","options":{"A":"3 cm.","B":"2 cm.","C":"1 cm.","D":"0,1 cm."},"answer":"C","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-321307","number":"321307","sourceNumber":"321307","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Paciente, 32 anos, portador de anemia falciforme. Encontra-se no 3o dia de internação\nhospitalar, em enfermaria, por crise álgica, sob uso de morfina, cetoprofeno e dipirona, para\ncontrole do quadro. Está hemodinamicamente estável, com bom controle álgico, diurese presente,\nafebril, eupneico, sem suporte de oxigênio. Apresenta hemograma do dia com Hb 5,9g/dL Ht 17%,\nsendo indicada transfusão de concentrado de hemácias desleucocitado e fenotipado. Após 12\nminutos do início da administração do hemocomponente, pela enfermeira da unidade, o paciente\npassa a apresentar febre (T: 38,3oC), calafrios, dor no local do acesso periférico, dor em flancos e\nepistaxe. Você, como médico plantonista da unidade, é imediatamente chamado para prestar\nassistência ao paciente. Ao chegar, você solicita imediata interrupção da transfusão, prescreve\nsintomáticos, notifica a suspeita de reação transfusional e solicita coleta de amostras para análise\nda reação pelo serviço de hemoterapia. Além das ações citadas, qual a melhor conduta a ser\nrealizada?","options":{"A":"Devolver hemocomponente à agência transfusional, solicitar provas de hemólise, função renal,\ncoagulograma e hemoculturas do paciente e prescrever hidratação vigorosa.","B":"Coletar hemocultura do paciente, retornar a transfusão com o mesmo hemocomponente, após\nresolução dos sintomas, e administrá-lo em 4 horas.","C":"Coletar novo hemograma, devolver hemocomponente à agência transfusional e só prescrever\nhemocomponentes lavados para transfusões futuras.","D":"Descartar concentrado de hemácias, solicitar que enviem novo concentrado para transfusão\nimediata e administrá-lo em 4 horas."},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-321318","number":"321318","sourceNumber":"321318","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Escolar, 6 anos, sexo masculino, iniciou há 2 meses quadro de dor em joelho esquerdo,\npersistente, predominando no período noturno e chegando a despertá-lo. Nega febre. Nega trauma.\nRelata uso de corticoide por 7 dias no início do quadro. Ao exame físico: Leve palidez. Ausculta\ncárdio-pulmonar sem alterações. Abdome indolor com fígado palpável a 3 cm do rebordo costal\ndireito. Marcha antálgica, dor à mobilização do joelho, ausência de sinais flogísticos. Traz exames\nque realizou na semana anterior: hemoglobina - 9,4 g/dL, hematócrito - 29%; 3.900 leucócitos/mm³\n(0% mielócitos, 1% bastões, 10 % segmentados, 80% linfócitos, 7% monócitos, 1% eosinófilos, 1%\nbasófilos), 152.000 plaquetas. VHS=60mm. Qual é a conduta diagnóstica mais indicada neste\nmomento?","options":{"A":"Solicitar RNM do joelho esquerdo.","B":"Solicitar aspirado de medula óssea.","C":"Solicitar sorologias virais, FAN e fator reumatoide.","D":"Solicitar ultrassonografia de joelhos com power doppler."},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-292843","number":"292843","sourceNumber":"292843","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Uma criança de cinco anos de idade chega ao ambulatório por apresentar dor óssea\nem membros inferiores, dificultando a\ndeambulação e sem ceder facilmente aos analgésicos\nhabituais. Também apresenta dor toracolombar e astenia. Ao exame físico, é identificado febre e\nhepatomegalia, esplenomegalia e linfonodomegalias generalizadas. Qual a principal hipótese\ndiagnóstica?","options":{"A":"Leucemia linfoide aguda.","B":"Leucemia mieloide aguda.","C":"Mononucleose infecciosa.","D":"Artrite reumatoide juvenil."},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-259725","number":"259725","sourceNumber":"259725","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Homem de 68 anos é admitido na sala de urgência com quadro de pico febril isolado,\nastenia, mialgias, vômitos e diarreia aquosa com uma semana de evolução. Diagnóstico há 3\nmeses de leucemia mieloide crônica, em fase blástica, com necessidade de esplenectomia e\nposterior citoredução eficaz. Medicado com imatinib 800mg ao dia. Ao exame físico,\n\napresentava-se colaborativo, frequência respiratória 22 incursões/minuto, anictérico, temperatura\n37ºC, frequência cardíaca 112 batimentos/minuto e\npressão arterial 130 x 80mmHg. Sem outras\nalterações relevantes. Exames complementares mostrando leucocitose (32.5000/mm³), anemia\nmicrocítica hipocrômica (hemoglobina 11,0 g/dL) com pesquisa de esquizócitos negativa,\ntrombocitopenia (130.000 /mm3), creatinina de 1,5 mg/dL (basal de 0.69 mg/dL), potássio 6,5 mg/dl\n(VR: 3,5-5,0); eletrocardiograma sem alterações, cálcio 7,7 mg/dL (VR: 8,5-10,2), elevação de LDH\nsérica de 7130 U/L, proteína C reactiva de 0,5 mg/dL (VR < 0,5), (VR Qual o diagnóstico mais\nprovável e tratamento inicial recomendado para o paciente?","options":{"A":"Síndrome de lise tumoral ? iniciar hidratação venosa e rasburicase ou alopurinol.","B":"Síndrome hemolítico-urêmica ? iniciar plasmaférese imediatamente.","C":"Sepse por infecção bacteriana ? iniciar ciprofloxacina endovenoso.","D":"Púrpura trombocitopênica trombótica ? iniciar rituximab."},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-259730","number":"259730","sourceNumber":"259730","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Gabriel, 5 anos de idade, há 2 meses vem apresentando palidez cutâneo-mucosa\nprogressiva e febre moderada. Há 15 dias, mãe\nnotou o aparecimento de petéquias e equimoses e\nrefere que seu filho acorda com dor óssea de forte intensidade em membros inferiores que pouco\ncede com analgésicos comuns. Ao exame físico, apresenta palidez cutâneo-mucosa (++/4+),\nhepatoesplenomegalia e petéquias e equimoses em membros inferiores e região torácica.\n\nRealizado hemograma que evidenciou anemia, leucocitose e plaquetopenia. O diagnóstico mais\nprovável de Gabriel é:","options":{"A":"Leucemia aguda.","B":"Anemia falciforme.","C":"Leishmaniose visceral.","D":"Artrite idiopática juvenil."},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-234037","number":"234037","sourceNumber":"234037","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Paciente, 72 anos, sexo masculino, comparece ao ambulatório de Clínica Médica com\nqueixa de dores ósseas difusas, particularmente na coluna. Ao exame físico, apresenta-se algo\nhipocorado e com fácies de dor. Traz alguns exames laboratoriais: hemoglobina 11,2 g/dl (VR:\n13?16 g/dl); cálcio iônico 1,5 mmol/L (VR: 1,15?1,32 mmol/L); creatinina 1,6 mg/dl (VR: 0,8?1,2\nmg/dl); fosfatase alcalina 64 U/L (VR: 50?200 U/L), além de radiografias da coluna evidenciando\nlesões osteolíticas difusas. LEGENDA: VR: Valor de Referência. Considerando a principal hipótese\ndiagnóstica, qual dos exames a seguir deve ser solicitado?","options":{"A":"PSA total.","B":"Cintilografia óssea.","C":"Densitometria mineral óssea.","D":"Eletroforese de proteínas séricas."},"answer":"D","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-173019","number":"173019","sourceNumber":"173019","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Paciente, feminina, 23 anos, comparece ao ambulatório de clínica médica com quadro\nde astenia, fadiga, artralgias leves difusas e\ndispneia aos moderados esforços, há duas semanas,\ncom piora progressiva. Relata também gengivorragia à escovação dentária, há uma semana. Ao\nexame físico, encontra-se com palidez cutâneo-mucosa moderada e petéquias em pernas e pés,\ncom equimoses esparsas em membros, sem outras alterações. Hemograma evidenciou Hb 6,4 g/l\n(VR: 11,5-16 g/dl), leucócitos 3.900/mm³ (VR: 4.000-11.000/mm³) e plaquetas de 13.000/mm³ (VR:\n150.000-450.000). Legenda: VR ? Valor de Referência. Qual a abordagem diagnóstica inicial?","options":{"A":"Mielograma com imunofenotipagem.","B":"Sorologia para dengue, Chikungunya e Zika.","C":"Biópsia de medula óssea, com avaliação de celularidade.","D":"Avaliação do sangue periférico, dos índices hematimétricos e reticulócitos."},"answer":"D","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-172973","number":"172973","sourceNumber":"172973","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Paciente masculino de 62 anos estava internado com quadro de sepse em ventilação\nmecânica. Foi indicada transfusão de uma\nunidade de concentrado de hemácias, pois apresentava\nHb de 6,4 g/dl (Valor de referência: 12?16,5 g/dl). Os testes pré-transfusionais obrigatórios para\ntransfusão de concentrados de hemácias são tipagem ABO/RhD, Pesquisa de Anticorpos\nIrregulares (PAI) e prova de compatibilidade. Qual o objetivo da pesquisa de anticorpos\nirregulares?","options":{"A":"Avaliação de autoanticorpos.","B":"Avaliação de anticorpos anti-HLA.","C":"Avaliação de incompatibilidade ABO.","D":"Avaliação de aloanticorpos antieritrocitários."},"answer":"D","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-173025","number":"173025","sourceNumber":"173025","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Uma criança de 11 anos de idade chega ao ambulatório por linfoadenopatias afebril,\nlocalizada na região cervical de início há\ncerca de dois meses; os pais relatam aumento progressivo\ndesses gânglios e perda de peso acentuada nos últimos meses. Não há outros sintomas. Qual a\nhipótese diagnóstica mais provável?","options":{"A":"Tuberculose ganglionar.","B":"Linfoma não-Hodgkin.","C":"Leucemia linfoide.","D":"Toxoplasmose."},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-150826","number":"150826","sourceNumber":"150826","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Você atende uma criança de oito anos de idade com adenopatia cervical, indolor, de\ninício há 4 semanas. Com a história clínica, você fica sabendo de outros sintomas clínicos tipo:\nsudorese noturna, perda de peso e febre ocasional. Ao exame físico, não há esplenomegalia. É\ndetectado assimetria de tonsilas palatinas. Qual a principal hipótese diagnóstica?","options":{"A":"Linfoma.","B":"Histiocitose.","C":"Neuroblastoma.","D":"Doença de arranhadura do gato."},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-126962","number":"126962","sourceNumber":"126962","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Menino de 9 anos é encaminhado ao ambulatório de pediatria por apresentar gânglio\ncervical anteroinferior unilateral palpável há 6\nsemanas, indolor, sem sinais inflamatórios, com 3 cm\nde diâmetro. Apresenta bom estado geral sem outras queixas. A conduta adequada nesse caso é:","options":{"A":"Solicitar sorologia para mononucleose, pois o quadro descrito é característico.","B":"Iniciar de imediato antibioticoterapia, pois o quadro clínico é clássico de adenite cervical\npiogênica.","C":"Aguardar e reavaliar em duas semanas, pois a hipótese mais provável é adenite cervical viral,\nde evolução benigna.","D":"Iniciar investigação imediata pelas características apresentadas no caso, que inclui as\nneoplasias como doença de Hodgkin, leucemias ou outra forma de linfoma."},"answer":"D","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-81306","number":"81306","sourceNumber":"81306","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Homem de 16 anos, na segunda semana de pós-operatório de apendicectomia, sem\ncomplicações, comparece à consulta com quadro de equimoses disseminadas e edema na\npanturrilha esquerda há dois dias. Não tem antecedentes mórbidos relevantes. Doppler de\nmembros inferiores mostrou apenas hematoma na panturrilha afetada. Exames mostram dosagem\nde plaquetas normal, Tempo de Protrombina (TP) normal e Tempo de Tromboplastina Parcial\nAtivada (TTPa) alargado. Foi solicitado o teste da mistura que não corrigiu o TTPa. Qual o\ndiagnóstico mais provável?","options":{"A":"Hemofilia A.","B":"Intoxicação por cumarínico.","C":"Doença de von Willebrand.","D":"Anticorpo adquirido contra fator VIII."},"answer":"D","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-65755","number":"65755","sourceNumber":"65755","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Uma jovem de 25 anos de idade há um mês apresentou quadro de massa cervical à\nesquerda, medindo 4,5 x 4,5 cm. Na avaliação, a radiografia de tórax mostrou presença de\nadenopatia hilar esquerda. Ao exame físico, a jovem apresentava-se com estado geral bom,\ncorada, normotensa, sem outras adenopatias ou visceromegalias palpáveis. Foi realizada biópsia\nda lesão cervical, cuja microscopia está reproduzida a seguir (hematoxilina-eosina, 400x). (VER\nIMAGEM) O diagnóstico mais provável é de:","options":{"A":"Linfoma de Burkitt.","B":"Linfoma de Hodgkin.","C":"Linfoma linfoplasmocítico.","D":"Linfoma de zona marginal nodal.","E":"Linfoma de grandes células B mediastinal."},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":["question_bank/media/medcurso/medcurso-hemato-hem-2/65755.png"],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-65787","number":"65787","sourceNumber":"65787","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Considere uma paciente feminina, 42 anos, que iniciará tratamento quimioterápico, por\nneoplasia pulmonar de pequenas células, com regime que inclui etoposide e tem história familiar de\nleucemia. Que alteração genética aumentará o risco de ela desenvolver leucemia mieloide aguda?","options":{"A":"Inversão do cromossomo 16.","B":"Aberração do cromossomo 11q23.","C":"Translocação dos cromossomos 8; 21.","D":"Translocação dos cromossomos 15; 17.","E":"Translocação dos cromossomos q22; q12."},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-51173","number":"51173","sourceNumber":"51173","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Homem de 46 anos comparece para consulta com quadro de bolhas e erosões nos\nolhos e boca, junto com lesões eritematosas\nmultiformes em face e tronco. Exame físico: lesões de\npele descritas e adenomegalia cervical. Qual o diagnóstico mais provável?","options":{"A":"Lúpus bolhoso.","B":"Dermatite herpetiforme.","C":"Pênfigo paraneoplásico.","D":"Dermatose bolhosa com IgA linear."},"answer":"C","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-51203","number":"51203","sourceNumber":"51203","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Homem de 26 anos é internado por quadro de febre, palidez e equimoses há uma\nsemana. O hemograma revela pancitopenia com blastos no sangue periférico. O mielograma\nmostra 23% de blastos. Qual o melhor teste para avaliação citogenética desse paciente?","options":{"A":"Real time PCR.","B":"Imuno-histoquímica.","C":"Análise de cariótipo por Banda G.","D":"Hibridização in situ com fluorescência."},"answer":"D","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-51210","number":"51210","sourceNumber":"51210","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Os linfomas representam 1% a 4% das neoplasias gastrointestinais, sendo o aparelho\ndigestivo o local mais comum de ocorrência extranodal. No que diz respeito ao acometimento do\naparelho digestivo, qual o órgão mais comumente afetado?","options":{"A":"Cólon.","B":"Esôfago.","C":"Estômago.","D":"Intestino delgado."},"answer":"C","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-51218","number":"51218","sourceNumber":"51218","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Um paciente de 65 anos encontra-se internado por sepse grave em UTI. Além de\nantibióticos, foram prescritos enoxaparina subcutânea e ranitidina IV para profilaxia de trombose\nvenosa profunda e de úlcera de estresse, respectivamente. No 9ª dia de admissão, foram\nobservadas lesões necróticas na pele do abdome. A contagem de plaquetas em hemograma de\ncontrole é de 40.000/mm³ (na admissão era de 80.000/mm³). O restante do hemograma é normal,\ncompatível com a resolução clínica do seu quadro infeccioso. Não são observados sangramentos\nespontâneos. Que conduta é a mais recomendada dentre as descritas abaixo?","options":{"A":"Substituição da enoxaparina por heparina não fracionada.","B":"Substituição da enoxaparina por warfarin.","C":"Suspensão da enoxaparina.","D":"Suspensão da ranitidina."},"answer":"C","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":["question_bank/media/medcurso/medcurso-hemato-hem-2/51218.png"],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-30941","number":"30941","sourceNumber":"30941","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Paciente de 25 anos com queixas de cansaço fácil, adinamia e febre há 30 dias. Ao\nexame apresentava gânglios cervicais de 3 cm,\naderidos a planos profundos e indolores. Referia\ndor nos gânglios somente após ingestão de bebida alcoólica. Realizou RX tórax que apresentou\nalargamento de mediastino. O diagnóstico mais provável é de:","options":{"A":"Mononucleose infecciosa.","B":"Tuberculose.","C":"HIV.","D":"Linfoma de Hodgkin.","E":"Linfoma não Hodgkin."},"answer":"D","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-22825","number":"22825","sourceNumber":"22825","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Dentre as condições abaixo, o distúrbio mieloproliferativo mais comumente associado à\nleucopenia é:","options":{"A":"Mielofibrose.","B":"Leucemia mieloide crônica.","C":"Policitemia vera.","D":"Trombocitemia essencial.","E":"Hiperesplenismo."},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-hemato-hem-2-25356","number":"25356","sourceNumber":"25356","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"O tumor maligno que mais frequentemente afeta o baço é:","options":{"A":"Adenocarcinoma do estômago","B":"Adenocarcinoma do cólon","C":"Linfoma","D":"Angiossarcoma","E":"Melanoma"},"answer":"C","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-6947","number":"6947","sourceNumber":"6947","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Quanto à leucemia mieloide crônica (LMC) com cromossomo Philadelphia positivo,\nassinale a alternativa CORRETA:","options":{"A":"Trata-se de doença maligna, de natureza genética, na qual se observa a translocação t(9, 21),\nsendo assim, potencialmente transmissível para a prole dos pacientes afetados.","B":"A inibição farmacológica do gene de fusão bcr-abl pode induzir uma remissão clínica,\nhematológica, citogenética e molecular.","C":"O transplante de medula óssea está contraindicado, pois esta patologia acomete, em geral,\npacientes com idade superior a 55 anos.","D":"O quadro hematológico característico da fase crônica inclui leucocitose acentuada com desvio\nescalonado à esquerda e excesso de blastos, trombocitopenia e anemia.","E":"O cromossomo Philadelphia está presente em cerca de 95% dos pacientes acometidos e essa\nalteração citogenética é suficiente para o diagnóstico exclusivo LMC."},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-349700","number":"349700","sourceNumber":"349700","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"A respeito de doenças hematológicas em crianças, assinale a alternativa correta.","options":{"A":"A anemia falciforme é uma doença genética e adquirida que afeta os glóbulos vermelhos do\nsangue.","B":"A Leucemia Linfocítica Aguda (LLA) se origina nas células linfoides, que são um tipo de glóbulo\nbranco, e tem uma evolução rápida. A causa da maioria dos casos é desconhecida, mas envolve\nalterações no DNA das células da medula óssea.","C":"Na anemia falciforme, os glóbulos vermelhos são ovalados e muito flexíveis, podendo causar\nobstrução dos vasos, dor, inflamação e lesão de órgãos.","D":"Em crianças, as causas menos comuns de anemia macrocítica são a deficiência de vitamina\nB12 ou de ácido fólico.","E":"A anemia falciforme pode ser tratada com medicamentos, e a cura ocorre antes dos dez anos de\nidade."},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-322158","number":"322158","sourceNumber":"322158","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"São considerados anticoagulantes, por bloqueio do fator Xa, EXCETO","options":{"A":"rivaroxabana.","B":"edoxabana.","C":"enoxaparina.","D":"dabigatrana.","E":"apixabana."},"answer":"D","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-305283","number":"305283","sourceNumber":"305283","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Um paciente em tratamento oncológico quimioterápico, que terá programação de\ntratamento cirúrgico em breve, apresenta\nastenia importante, porém nega vômitos ou\nsangramentos. Foram realizados exames laboratoriais. Qual das alternativas a seguir representa\nindicação de transfusão de ambos os componentes - hemácias e plaquetas - para esse paciente?","options":{"A":"Hemoglobina = 9,1g/dL e plaquetas = 21000/mm³.","B":"Hemoglobina = 6,2g/dL e plaquetas = 18000/mm³.","C":"Hemoglobina = 6,8g/dL e plaquetas = 7000/mm³.","D":"Hemoglobina = 10,1g/dL e plaquetas = 11000/mm³.","E":"Hemoglobina = 7,5g/dL e plaquetas = 11000/mm³."},"answer":"C","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-305297","number":"305297","sourceNumber":"305297","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Sobre os Anticoagulantes Orais Diretos (DOAC), assinale a opção que NÃO age\natravés do fator Xa.","options":{"A":"Dabigatrana.","B":"Apixabana.","C":"Edoxabana.","D":"Rivaroxabana.","E":"Enoxaparina."},"answer":"D","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-305302","number":"305302","sourceNumber":"305302","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Sobre a injúria pulmonar aguda relacionada à transfusão (TRALI), é correto afirmar que","options":{"A":"só ocorre nas transfusões de concentrado de hemáceas.","B":"o uso de corticoides sistêmicos está indicado.","C":"nos casos em que a ventilação mecânica seja necessária, volume corrente >8mL/Kg e pressão\nmédia de via aérea acima de 30cm de H20 estão indicados.","D":"o início dos sintomas em até 06 (seis) horas da transfusão é um dos critérios diagnósticos.","E":"o uso de diurético de alça está indicado."},"answer":"D","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-305325","number":"305325","sourceNumber":"305325","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Distinguir um linfonodo inflamatório de um neoplásico pode ser um desafio para o\npediatra. Qual das situações a seguir sugere benignidade, sem necessidade de investigação?","options":{"A":"Ausência de linfonodos palpáveis em recém-nascidos.","B":"Nódulo linfático maior que 1 cm, em dois locais anatômicos.","C":"Linfonodo epitroclear com 0,7 cm.","D":"Linfonodo inguinal com 2 cm.","E":"Linfonodomegalia localizada, com febre por mais de 7 dias."},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-274398","number":"274398","sourceNumber":"274398","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Os exames laboratoriais são fundamentais no diagnóstico e no estadiamento dos\nlinfomas não Hodgkin. Em relação ao tema, assinale a alternativa CORRETA.","options":{"A":"O hemograma está sempre alterado.","B":"A velocidade de hemossedimentação, muito específica, costuma estar aumentada.","C":"A desidrogenase lática está tão mais elevada quanto a quantidade de células tumorais e a\nintensidade de apoptose e, quanto mais elevada, pior o prognóstico.","D":"Mielograma, para avaliar a infiltração medular, deve ser feito em um único ponto e deve ser\navaliado somente através do exame microscópico direto.","E":"A imunofenotipagem não está indicada para a maioria dos pacientes."},"answer":"C","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-239278","number":"239278","sourceNumber":"239278","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Um paciente de 75 anos de idade procurou atendimento por diminuição do volume\nurinário e intolerância aos esforços,\nassociada a dor torácica ventilatório-dependente e a dor lombar\nde forte intensidade. Realizou exames de laboratório, que evidenciaram: hemoglobina = 8,6 g/dl,\nhematócrito = 25%, leucócitos = 6.600/mm3, sem particularidades no diferencial, plaquetas = 190\nmil/mm3, creatinina = 4,51 mg/dl, potássio = 6,3 mEq/L, cálcio sérico corrigido = 13 mg/dl, ureia =\n109 mg/dl, reserva alcalina = 12 U/L. Ao exame físico, o paciente encontrava-se em regular estado\ngeral, hipocorado, com presença de sopro sistodiastólico 2+/4+, murmúrio vesicular reduzido em\n1/3 inferior direito, edema em membros inferiores 3+/4+, abdome sem particularidades e\n\npercussão-punho-lombar (PPL) negativo, PA = 180 mmHg X 90 mmHg, FC = 97 bpm, SatO2 = 92%\nem ar ambiente. Considerando esse caso\nclínico e os conhecimentos médicos correlatos, julgue o\nitem a seguir. A lombalgia, nesse paciente, provavelmente se deve a lesões ósseas de\ncaracterísticas líticas, associadas à hipótese diagnóstica principal.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-239347","number":"239347","sourceNumber":"239347","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Um paciente de 64 anos de idade, acamado, é recebido, junto a dois familiares, em seu\ndomicílio por equipe de Estratégia de Saúde da Família. Os familiares demonstram possuir diversas\ndúvidas quanto ao prognóstico da doença apresentada pelo paciente, diagnosticado com linfoma\nde Hodgkin há três meses, com metástases extranodais de acordo com investigação da equipe de\noncologia assistente, a qual instituiu manejo de conforto para cuidados paliativos na última\ninternação hospitalar há duas semanas, com prescrição de morfina para uso domiciliar. Um dos\nfamiliares acompanhantes afirma que está gravando o áudio do atendimento atual sem aviso prévio\ne alega que gostaria de pausá-lo, para mostrar a gravação realizada na referida internação\nhospitalar, com as orientações fornecidas pela equipe de oncologia assistente, questionando se a\nconduta dos profissionais não se trata de erro médico. Na gravação, escutam-se as explicações\ncompatíveis com planos de início de medidas que focassem no bem-estar do paciente, garantindo\num final de vida digno e com menor sofrimento, haja vista presença de estágio de terminalidade.\n\nCom base nesse caso clínico e nos conhecimentos médicos correlatos, julgue o item a seguir. A\ndoença de base do paciente (linfoma de\nHodgkin) possui prevalência maior na população com\ninfecção por HIV do que a média populacional geral.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-hemato-hem-2-196673","number":"196673","sourceNumber":"196673","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Certo paciente de 35 anos de idade compareceu a uma consulta, informando histórico\nde febre, emagrecimento e linfonodomegalias\nmediastinais, sendo que há linfonodos de 3 cm em\ncadeia paratraqueal esquerda e paratraqueal direita. Ele também apresenta linfonodomegalia em\ncadeias axilares e inguinais. Diante desse quadro, é levantada a hipótese de linfoma. A respeito\ndesse caso clínico, julgue o item a seguir. Deve-se indicar mediastinoscopia, pois a cadeia\nparatraqueal, além de ser bem abordada, oferece um linfonodo de melhor rendimento para o\ndiagnóstico de linfoma, se comparado ao inguinal.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-152106","number":"152106","sourceNumber":"152106","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Considere as três situações seguintes: Paciente 1 - O. S., 34 anos de idade, queixa-se\nde dispneia e desconforto respiratório leve, FR\n= 19 irpm, Sat O2 = 98% e PA de 130 x 80 mmHg;\nPaciente 2 - B. M. S., 65 anos de idade, trabalhador rural, vai à consulta para esclarecer dúvidas a\nrespeito de uma mancha escura na face, perda ponderal e massa palpável no abdome; Paciente 3 -\nAdolescente deu entrada na emergência, após acidente motociclístico, com sangramento ativo de\ndifícil controle em MSE, FC = 99 bpm, PA de 110 x 70 mmHg, consciente e manifestando sede.\n\nCom relação aos casos clínicos apresentados, julgue o item a seguir. A presença de fibrinogênio e\nde fator de von Willebrand (vWF) é\nimportante para o sucesso da aderência plaquetária e de\nhemostasia no caso do Paciente 3.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-88626","number":"88626","sourceNumber":"88626","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"No que se refere à leucemia, à osteoporose pós-menopáusica e à litíase renal, julgue o\nitem a seguir. A leucemia mieloide crônica é uma neoplasia mieloproliferativa associada a uma\ntranslocação gênica; esta provoca a formação de um oncogene de fusão, denominado cromossomo\nPhiladelphia, que codifica a oncoproteína BCR-ABL.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-hemato-hem-2-64660","number":"64660","sourceNumber":"64660","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Assinale a alternativa que apresenta a neoplasia em que, caracteristicamente, as\ncélulas de Reed-Sternberg estão presentes.","options":{"A":"Leucemia linfoide aguda.","B":"Leucemia mieloide crônica.","C":"Linfoma de Hodgkin.","D":"Leucemia linfoide crônica.","E":"Leucemia mieloide aguda."},"answer":"C","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-352381","number":"352381","sourceNumber":"352381","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Um homem de 57 anos de idade com histórico de Doença Pulmonar Obstrutiva Crônica\ne hipertensão arterial bem controlada com\nlosartana 100 mg por dia, e que deixou de fumar há 2\nanos após 50 anos de tabagismo (50 maços-ano), apresenta-se no ambulatório com uma queixa de\ndor lombar crônica persistente há 2 anos. Ele relata ter sofrido uma queda da própria altura durante\no banho, que resultou em uma dor intensa e súbita, acompanhada por uma limitação significativa\ndos movimentos. Isso o levou a se afastar do trabalho por um período de 7 dias. Embora tenha\nretomado suas atividades laborais, continua a experimentar dor lombar constante que, por vezes, o\nacorda durante a noite. O paciente menciona ter buscado assistência em múltiplos\n\nprontos-socorros, onde recebeu apenas tratamento sintomático. Ele faz uso de anti-inflamatórios,\nque proporcionam algum alívio, mas não resolvem o\nquadro. Além disso, recorre ao tramadol\nesporadicamente. Embora relate ocasional tosse, foi sua significativa piora na dor lombar na última\nsemana que o levou a procurar atendimento médico particular. Nesse atendimento particular, foram\nsolicitados exames complementares, um de imagem e um laboratorial, cujos resultados estão\napresentados abaixo. Considerando o quadro clínico exposto bem como os exames\ncomplementares e seus diagnósticos diferenciais, julgue o item a seguir. Um dos diagnósticos\ndiferenciais para o caso é câncer com metástase óssea.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":["question_bank/media/medcurso/medcurso-hemato-hem-2/352381.png"],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-352382","number":"352382","sourceNumber":"352382","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Um homem de 57 anos de idade com histórico de Doença Pulmonar Obstrutiva Crônica\ne hipertensão arterial bem controlada com\nlosartana 100 mg por dia, e que deixou de fumar há 2\nanos após 50 anos de tabagismo (50 maços-ano), apresenta-se no ambulatório com uma queixa de\ndor lombar crônica persistente há 2 anos. Ele relata ter sofrido uma queda da própria altura durante\no banho, que resultou em uma dor intensa e súbita, acompanhada por uma limitação significativa\ndos movimentos. Isso o levou a se afastar do trabalho por um período de 7 dias. Embora tenha\nretomado suas atividades laborais, continua a experimentar dor lombar constante que, por vezes, o\nacorda durante a noite. O paciente menciona ter buscado assistência em múltiplos\n\nprontos-socorros, onde recebeu apenas tratamento sintomático. Ele faz uso de anti-inflamatórios,\nque proporcionam algum alívio, mas não resolvem o\nquadro. Além disso, recorre ao tramadol\nesporadicamente. Embora relate ocasional tosse, foi sua significativa piora na dor lombar na última\nsemana que o levou a procurar atendimento médico particular. Nesse atendimento particular, foram\nsolicitados exames complementares, um de imagem e um laboratorial, cujos resultados estão\napresentados abaixo. Considerando o quadro clínico exposto bem como os exames\ncomplementares e seus diagnósticos diferenciais, julgue o item a seguir. O exame laboratorial\nclássico acima é eletroforese com típico componente monoclonal em região gama.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":["question_bank/media/medcurso/medcurso-hemato-hem-2/352382.png"],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-hemato-hem-2-352404","number":"352404","sourceNumber":"352404","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Um homem de 57 anos de idade com histórico de Doença Pulmonar Obstrutiva Crônica\ne hipertensão arterial bem controlada com\nlosartana 100 mg por dia, e que deixou de fumar há 2\nanos após 50 anos de tabagismo (50 maços-ano), apresenta-se no ambulatório com uma queixa de\ndor lombar crônica persistente há 2 anos. Ele relata ter sofrido uma queda da própria altura durante\no banho, que resultou em uma dor intensa e súbita, acompanhada por uma limitação significativa\ndos movimentos. Isso o levou a se afastar do trabalho por um período de 7 dias. Embora tenha\nretomado suas atividades laborais, continua a experimentar dor lombar constante que, por vezes, o\nacorda durante a noite. O paciente menciona ter buscado assistência em múltiplos\n\nprontos-socorros, onde recebeu apenas tratamento sintomático. Ele faz uso de anti-inflamatórios,\nque proporcionam algum alívio, mas não resolvem o\nquadro. Além disso, recorre ao tramadol\nesporadicamente. Embora relate ocasional tosse, foi sua significativa piora na dor lombar na última\nsemana que o levou a procurar atendimento médico particular. Nesse atendimento particular, foram\nsolicitados exames complementares, um de imagem e um laboratorial, cujos resultados estão\napresentados abaixo. Considerando o quadro clínico exposto bem como os exames\ncomplementares e seus diagnósticos diferenciais, julgue o item a seguir. O paciente em questão\npode apresentar uma emergência que curse como seguinte achado eletrocardiográfico (DII longo\nem 10mm/mV; 25mm/s):","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":["question_bank/media/medcurso/medcurso-hemato-hem-2/352404.png"],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-352403","number":"352403","sourceNumber":"352403","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Um homem de 57 anos de idade com histórico de Doença Pulmonar Obstrutiva Crônica\ne hipertensão arterial bem controlada com\nlosartana 100 mg por dia, e que deixou de fumar há 2\nanos após 50 anos de tabagismo (50 maços-ano), apresenta-se no ambulatório com uma queixa de\ndor lombar crônica persistente há 2 anos. Ele relata ter sofrido uma queda da própria altura durante\no banho, que resultou em uma dor intensa e súbita, acompanhada por uma limitação significativa\ndos movimentos. Isso o levou a se afastar do trabalho por um período de 7 dias. Embora tenha\nretomado suas atividades laborais, continua a experimentar dor lombar constante que, por vezes, o\nacorda durante a noite. O paciente menciona ter buscado assistência em múltiplos\n\nprontos-socorros, onde recebeu apenas tratamento sintomático. Ele faz uso de anti-inflamatórios,\nque proporcionam algum alívio, mas não resolvem o\nquadro. Além disso, recorre ao tramadol\nesporadicamente. Embora relate ocasional tosse, foi sua significativa piora na dor lombar na última\nsemana que o levou a procurar atendimento médico particular. Nesse atendimento particular, foram\nsolicitados exames complementares, um de imagem e um laboratorial, cujos resultados estão\napresentados abaixo. Considerando o quadro clínico exposto bem como os exames\ncomplementares e seus diagnósticos diferenciais, julgue o item a seguir. Exames como\nimunofixação de proteínas séricas e de urinas de 24 horas bem como dosagem de imunoglobulinas\npodem auxiliar no diagnóstico do quadro em tela.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":["question_bank/media/medcurso/medcurso-hemato-hem-2/352403.png"],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-366241","number":"366241","sourceNumber":"366241","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Uma criança de 8 anos foi conduzida pelo pai ao pronto-socorro devido a histórico de\nfebre súbita, registrando até 38,8 °C nas\núltimas duas semanas, que parcialmente cede ao uso de\nantipiréticos, mas retorna. Inicialmente, apresentou tosse, odinofagia, rinorreia e faringite\n(Figura I).\nApós atendimento inicial com prescrição de antitérmicos e observação, a criança desenvolveu\nfadiga intensa, prostração, aumento do volume abdominal e notou-se \"\"caroços no pescoço\"\"\n(Figura II). Diante desses novos sintomas, foi trazida para reavaliação. O hemograma solicitado\nrevelou uma anemia leve normocítica e normocrômica, enquanto o leucograma quantitativo estava\ndentro dos parâmetros normais, sem achados relevantes, exceto pela observação em lâmina\nperiférica de um linfócito (FIgura III). A partir do quadro clínico exposto, bem como achado de\nexame complementar e os assunto correlatos que ele suscita, julgue o item que se segue. Trata-se\nde vírus pertencente à família herpersviridae composto de DNA linear de fita dupla.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":["question_bank/media/medcurso/medcurso-hemato-hem-2/366241.png"],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-366240","number":"366240","sourceNumber":"366240","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Uma criança de 8 anos foi conduzida pelo pai ao pronto-socorro devido a histórico de\nfebre súbita, registrando até 38,8 °C nas\núltimas duas semanas, que parcialmente cede ao uso de\nantipiréticos, mas retorna. Inicialmente, apresentou tosse, odinofagia, rinorreia e faringite\n(Figura I).\nApós atendimento inicial com prescrição de antitérmicos e observação, a criança desenvolveu\nfadiga intensa, prostração, aumento do volume abdominal e notou-se \"\"caroços no pescoço\"\"\n(Figura II). Diante desses novos sintomas, foi trazida para reavaliação. O hemograma solicitado\nrevelou uma anemia leve normocítica e normocrômica, enquanto o leucograma quantitativo estava\ndentro dos parâmetros normais, sem achados relevantes, exceto pela observação em lâmina\nperiférica de um linfócito (FIgura III). A partir do quadro clínico exposto, bem como achado de\nexame complementar e os assunto correlatos que ele suscita, julgue o item que se segue. Durante\nou logo após a quadro, pode ocorrer uma complicação neurológica, na qual acontece o fenômeno\nde metamorfopsia que podem durar entre 4 e 6 semanas, também conhecida como \"Síndrome de\nAlice no País das Maravilhas\".","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":["question_bank/media/medcurso/medcurso-hemato-hem-2/366240.png"],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-366239","number":"366239","sourceNumber":"366239","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Uma criança de 8 anos foi conduzida pelo pai ao pronto-socorro devido a histórico de\nfebre súbita, registrando até 38,8 °C nas\núltimas duas semanas, que parcialmente cede ao uso de\nantipiréticos, mas retorna. Inicialmente, apresentou tosse, odinofagia, rinorreia e faringite\n(Figura I).\nApós atendimento inicial com prescrição de antitérmicos e observação, a criança desenvolveu\nfadiga intensa, prostração, aumento do volume abdominal e notou-se \"\"caroços no pescoço\"\"\n(Figura II). Diante desses novos sintomas, foi trazida para reavaliação. O hemograma solicitado\nrevelou uma anemia leve normocítica e normocrômica, enquanto o leucograma quantitativo estava\ndentro dos parâmetros normais, sem achados relevantes, exceto pela observação em lâmina\nperiférica de um linfócito (FIgura III). A partir do quadro clínico exposto, bem como achado de\nexame complementar e os assunto correlatos que ele suscita, julgue o item que se segue. Entre as\nneoplasias malignas associadas, incluem-se Linfoma de Burkitt Africano, Linfoma de Hodgkin bem\ncomo o carcinoma nasofaríngeo.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":["question_bank/media/medcurso/medcurso-hemato-hem-2/366239.png"],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-334882","number":"334882","sourceNumber":"334882","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Um paciente de 40 anos de idade, com diagnóstico de leucemia mieloide aguda e\nneutropenia, apresenta quadro de febre de 39 ºC, em uso de esquema antimicrobiano constituído\npor vancomicina e carbapenêmico há cinco dias. O exame físico não mostra evidência clínica que\njustifique a persistência da febre, e o hemograma realizado tem resultado semelhante ao feito\nquando do início do tratamento do paciente. Assinale a alternativa que indica a medida mais\nadequada nesse caso.","options":{"A":"Suspender o esquema antimicrobiano.","B":"Realizar uma punção liquórica.","C":"Acrescentar um fármaco antifúngico ao esquema prescrito.","D":"Solicitar uma transfusão de sangue.","E":"Indicar o transplante de medula."},"answer":"C","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-307105","number":"307105","sourceNumber":"307105","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Um paciente de 64 anos de idade vem apresentando dor dorsal, com cefaleia, turvação\nvisual, vertigem, zumbido e dispneia. Quando\nsolicitados exames, observaram-se uma anemia\nnormocrômica e normocítica, trombopenia e leucopenia. Na biópsia de medula óssea, realizada\npela hematologia, foram constatados mais de 10% de plasmócitos clonais; proteína M elevada no\nsoro, além de hipercalcemia. Na tomografia de crânio, há relato de lesões em saca-bocado em\nossos do crânio. Nesse caso, o diagnóstico mais provável é:","options":{"A":"Gamopatia monoclonal.","B":"Leucemia de células plasmáticas.","C":"Amiloidose primária.","D":"Plasmocitomas isolados medulares.","E":"Mieloma múltiplo."},"answer":"E","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-307113","number":"307113","sourceNumber":"307113","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"A causa mais comum de trombocitopenia na infância é Alternativas:","options":{"A":"anemia aplástica.","B":"síndrome de Wiskott-Aldrich.","C":"disfunção plaquetária por uso de medicamentos.","D":"trombocitopenia neonatal.","E":"púrpura trombocitopênica ou imunológica."},"answer":"E","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-263417","number":"263417","sourceNumber":"263417","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Uma paciente com 45 anos de idade apresenta queixa de astenia, mal-estar e tosse\nseca persistente. Ela procurou assistência médica\nem Unidade Básica de Saúde. Em seu exame\nfísico, notou-se adenomegalia cervical bilateral, sem outros achados. Foi realizada a radiografia de\ntórax, conforme exibido na imagem. No atendimento ambulatorial, foi realizada a biópsia de um dos\nnódulos que revelou células gigantes, multinucleadas em aspecto de \"olhos de coruja\" e do subtipo\nesclerose nodular. De acordo com os achados radiográficos e histopatológicos, a conduta indicada\né encaminhar a paciente para","options":{"A":"rede UNACON/CACON de assistência oncológica.","B":"hospital terciário para tratamento especializado em infectologia.","C":"hospital terciário para tratamento especializado em Cirurgia Torácica.","D":"hospital terciário para tratamento especializado em Cirurgia de Cabeça e Pescoço."},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":["question_bank/media/medcurso/medcurso-hemato-hem-2/263417.png"],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-263419","number":"263419","sourceNumber":"263419","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Um pré-escolar com 3 anos de idade, previamente hígido, é atendido no\n\npronto-socorro. A mãe relata que seu filho apresentou manchas no corpo há 2 dias. Além disso,\nrefere que a criança esteve resfriada no mês\nanterior e que melhorou após 5 dias. Durante o exame\nfísico, estava afebril, alerta, com múltiplas petéquias em membros e tronco, pequenos hematomas\nem joelhos, ausência de visceromegalias ou linfonodomegalia. O exame de esfregaço de sangue\nperiférico mostra plaquetas de 57.000/mm³ (valor de referência: 150.000 a 450.000/mm³), com\nmacroplaquetas; células vermelhas e brancas com morfologia e quantidade normais. Nesse caso, o\ndiagnóstico provável e a conduta adequada são, respectivamente:","options":{"A":"Leucemia; aspiração e biópsia de medula óssea.","B":"Púrpura trombocitopênica idiopática; seguimento clínico.","C":"Púrpura trombocitopênica idiopática; corticoide em altas doses.","D":"Leucemia; exames de citometria de fluxo e imuno-histoquímicos."},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-263428","number":"263428","sourceNumber":"263428","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Um homem com 64 anos de idade é encaminhado ao ambulatório para investigação de\nanemia, detectada nas últimas semanas durante investigação de quadro de fadiga, cansaço e\ndores ósseas. Ao exame físico, paciente apresenta-se em regular estado geral, hipocorado, não\nhavendo outras anormalidades. Os exames complementares realizados recentemente revelaram o\nseguinte: hemoglobina = 10g/dl (valor de referência: 13 a 17 g/dl); hematócrito = 28% (valor de\nreferência: 40 a 52%); volume corpuscular médio = 88 fl (valor de referência: 80 a 100 fl);\nleucometria e contagem plaquetária normais; ureia = 60 mg/dl (valor de referência: 20 a 40 mg/dl);\ncreatinina = 1,3 mg/dL (valor de referência: 0,7 a 1,2 mg/dl); e cálcio sérico = 11,8 mg/dl (valor\nde\nreferência: 8,0 a 10,5 mg/dl). Os exames laboratoriais realizados no dia do atendimento\napresentam: ureia = 88 mg/dl; creatinina = 2,4 mg/dL e cálcio sérico = 12,0 mg/dl; proteinograma\nsérico: albumina = 3,1 g/dl (valor de referência: 3,5 a 5,5 g/dl), e globulina = 8,2 g/dl (valor de\nreferência: 1,5 a 2,5 g/dl). Nesse caso, o diagnóstico, a partir dos dados clínicos e\nlaboratoriais, é\nde:","options":{"A":"Gamopatia monoclonal associada a mieloma múltiplo.","B":"Gamopatia policlonal associada a síndrome hemolítico-urêmica.","C":"Inversão albumina/globulina por cirrose hepática complicada com síndrome hepatorrenal.","D":"Hipoalbuminemia decorrente de síndrome nefrótica por nefropatia membranosa associada a\nsíndrome hiper-IgG."},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-244477","number":"244477","sourceNumber":"244477","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Um paciente de 19 anos de idade, estudante, foi atendido na emergência do hospital\nem decorrência de quadro de febre, dores\nmusculares, vômitos e tosse seca, associado a dispneia\nprogressiva e iniciado há seis horas. Há 10 dias, fez quimioterapia de consolidação para leucemia\nlinfoblástica aguda (LLA) de células B precursora. Seus medicamentos atuais são bactrim\nprofilático. Sinais vitais de admissão: temperatura = 38,6 ºC, FR = 26 irpm, FC = 104 bpm, PA = 98\nmmHg x 64 mmHg, SatO2 = 93% em ar ambiente. Exames laboratoriais: contagem de leucócitos =\n540 mm3 (VR = 4.000-12.000), contagem absoluta de neutrófilos (CAN) = 30 células/µ (VR =\n1.200-8.000); Hb = 7,1 g/d (VR = 12-15), hematócrito = 23,1% (VR = 35-50), contagem de\n\nplaquetas = 3.000 µL (VR = 140.000-450.00) e nível de glicose = 50 mg/dL (VR = 7-100). Com base\nnesse caso clínico e nos conhecimentos\nmédicos correlatos, assinale a alternativa correta.","options":{"A":"O paciente deverá iniciar, na admissão de urgência, com antifúngico parenteral do espectro de\nanfotericina ou voriconazol em razão do risco de germes filamentosos pelo quadro de neutropenia\nfebril.","B":"A transfusão de plaquetas nesse paciente deve ser indicada apenas nos casos de sangramento\ncutâneo mucoso, independentemente da contagem\nde plaquetas.","C":"O paciente necessita de exames complementares de imagem de urgência (tomografia de tórax)\nantes da definição da antibioticoterapia.","D":"A terapia precoce direcionada a esse paciente inclui ressuscitação hídrica, monitorização e\nadministração precoce de agentes antimicrobianos de amplo espectro. Essas intervenções\ncomprovadamente diminuem a taxa de mortalidade nesse perfil de paciente.","E":"O uso de G-CSF reduz a necessidade de uso de antibiótico de amplo espectro em decorrência\nda rápida recuperação imunológica, podendo ser\niniciado antibiótico betalactâmico oral para o\nreferido paciente."},"answer":"D","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-203008","number":"203008","sourceNumber":"203008","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Um paciente de 28 anos de idade, vítima de acidente de motocicleta, deu entrada no\npronto-socorro com quadro de dor abdominal, pressão arterial de 90 mmHg x 40 mmHg e\nfrequência cardíaca de 120 bpm. Ao exame físico, estava consciente e orientado e apresentava dor\nà palpação no abdome. O paciente foi submetido à laparotomia, com achado de lesão esplênica, e\nfoi realizada esplenectomia. Quais achados são possíveis no pós-operatório?","options":{"A":"Fístula colônica e plaquetopenia.","B":"Fístula pancreática e plaquetopenia.","C":"Fístula colônica e plaquetose.","D":"Fístula pancreática e plaquetose.","E":"Fístula gástrica e plaquetopenia."},"answer":"D","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-203101","number":"203101","sourceNumber":"203101","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Quanto à Leucemia Mieloide Crônica (LMC), assinale a alternativa correta.","options":{"A":"O esfregaço do sangue periférico mostra leucocitose com desvio escalonado, com neutrófilos\napresentando granulações tóxicas, associados a elevação do VHS e PCR.","B":"A presença de anemia, esplenomegalia e trombocitopenia (contagem de plaquetas inferior a\n90.000) são achados comuns ao diagnóstico e são critérios de doença crônica (considerada fase\nindolente da doença).","C":"É considerada doença indolente semelhante à Leucemia Linfocítica Crônica (LLC) e deve ser\nmonitorada sem tratamento até critérios clínicos de início de tratamento como: trombocitopenia,\npresença de blastos na periferia acima de 10% e basofilia.","D":"As translocações envolvendo os cromossomos 9 e 22 são presentes em 90% a 95% dos casos,\nsendo o respectivo gene de fusão o gene\nBCR-ABL.","E":"Os inibidores de tirosina quinase (TKI) não modificaram a sobrevida média desses pacientes,\nque continua sendo de quatro anos a partir da fase\nacelerada da doença."},"answer":"D","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-212057","number":"212057","sourceNumber":"212057","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Uma paciente de 28 anos de idade, percebendo uma massa indolor em crescimento\nlento no lado esquerdo do pescoço, procurou\num clínico geral. A paciente tinha sudorese noturna e\nepisódios de febre de 38°C, sem motivo aparente. Depois de ela negar existência de infecções no\ntrato respiratório superior e perda de peso, o médico constatou que não havia mais alterações\ndignas de nota. No exame físico, encontrava-se afebril, com sinais vitais dentro da normalidade,\nmas foi encontrada uma massa de 4 cm, móvel, firme, arredondada e indolor à palpação na metade\ndireita do pescoço. Não tinha outra linfadenopatia periférica. O fígado e o baço não estavam\naumentados. O médico levantou a hipótese diagnóstica de linfoma de Hodgkin. A partir do caso\nclínico descrito, julgue o item a seguir. O método mais adequado para a confirmação do diagnóstico\nem tela é a punção aspirativa da massa cervical com agulha fina, seguida pela realização de cortes\nde tecido, buscando-se o reconhecimento do Vírus do Epstein-Barr (VEB).","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-175131","number":"175131","sourceNumber":"175131","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"São considerados estados de Hipercoagulabilidade, EXCETO:","options":{"A":"Mutação do Fator V de Leiden","B":"Anticorpo anticardiolipina.","C":"Deficiência de Fator VIII.","D":"Deficiência de Proteína S."},"answer":"C","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-175132","number":"175132","sourceNumber":"175132","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"As coagulopatias estão invariavelmente presentes em pacientes com doença hepática\naguda ou crônica avançada. Sobre isso, é INCORRETO afirmar:","options":{"A":"Plaquetopenia é encontrada em cerca de 30 a 64% dos cirróticos.","B":"Os fatores dependentes de vitamina K precisam ser carboxidados no fígado, e podem estar\ncomprometidos na disfunção hepática.","C":"Sangramentos em pacientes com plaquetas maiores que 50.000/mm³ são raros.","D":"O volume de plasma a ser transfundido costuma ser de 50 ml/kg, o que reduz o prolongamento\ndo tempo de protrombina para menos de 3\nsegundos."},"answer":"D","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-168515","number":"168515","sourceNumber":"168515","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Uma mulher com 66 anos de idade foi encaminhada ao ambulatório de hematologia de\num hospital geral para investigação\ndiagnóstica de pancitopenia. Em consulta, a paciente refere\nastenia progressiva nos últimos 3 meses e relata também que passou a apresentar, há 2 semanas,\npetéquias e gengivorragia. Diante disso, procurou atendimento médico, quando foi realizado\nhemograma completo que revelou anemia normocítica normocrômica, com baixa contagem de\nreticulócitos, leucopenia com diferencial normal e plaquetopenia. Um exame hematoscópico revelou\na presença de elevada porcentagem de dacriócitos (\"hemácias em lágrima\"). Nessa situação, qual\né o diagnóstico mais provável da paciente e que exame complementar deve ser solicitado para sua\nconfirmação?","options":{"A":"Mielofibrose; biópsia de medula óssea.","B":"Leucemia mieloide aguda; aspirado de medula óssea.","C":"Mielodisplasia; citometria de fluxo de sangue periférico.","D":"Aplasia de medula óssea; sorologia para parvovírus B19."},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-154472","number":"154472","sourceNumber":"154472","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Paciente feminino, de 3 anos, comparece ao pronto atendimento acompanhada de sua\nmãe com queixa de tosse seca há 6 semanas,\ndor no corpo persistente, discreto edema de joelhos,\nhiporexia, adinamia e febre baixa há 10 dias. Ao exame físico apresenta palidez cutaneomucosa,\nausculta cardíaca com sopro sistólico suave 1+/6+ em mesocárdio, fígado palpável a 3 cm do RCD\ne baço a 2 cm do RCE. Hemograma mostrava Hb 8,7 g/dL; Ht 25% com normocitose e\nnormocromia; 3850 leucócitos e 56% de linfócitos. A principal hipótese diagnóstica ao atender a\ncriança deverá ser:","options":{"A":"Febre reumática.","B":"Síndrome mononucleose-like.","C":"Artrite Idiopática Juvenil.","D":"Lúpus Eritematoso Sistêmico.","E":"Leucemia Linfóide Aguda."},"answer":"E","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-159537","number":"159537","sourceNumber":"159537","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Um paciente de cinquenta anos de idade procurou atendimento médico queiando-se de\nfadiga, perda de peso, mal-estar e empachamento pós-prandial. Em seu exame clínico, o achado\nde destaque foi esplenomegalia. O hemograma apresentou os seguintes resultados: leucocitose =\n\n320.000 leucócitos/mL, com predominio de neutrotófilos e desvio à esquerda, estendendo-se até\nblastos; basofilia e eosinofilia presentes; plaquetas com contagem normal; e anemia normocrêmica\ne normocítica discreta. Ademais, constatou-se a presença do cromossomo Filadélfia (Ph) em\ncélulas da medula óssea. Com relação a esse caso clínico, julgue o próximo item. No caso em\napreço, o principal diagnóstico é leucemia mieloide crônica.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-158044","number":"158044","sourceNumber":"158044","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Determinado paciente, 72 anos de idade, comparece ao pronto-socorro queixando-se\nde que, há vários meses, evolui com cefaleia\nholocraniana, turvação visual, face e olhos\navermelhados e prurido generalizado após o banho. Começou também a apresentar pressão alta,\nsendo que realiza consultas médicas anuais sem detecção de nenhuma patologia. Ao exame físico,\nnotam-se hepatomegalia e PA = 180 mmHg x 100 mmHg, eritema conjuntival e face eritematosa.\n\nFoi realizado hemograma que revelou hemoglobina = 19 mg/dL, leucócitos = 15.700 e plaquetas =\n500 mil. Acerca desse caso clínico, assinale\na alternativa CORRETA.","options":{"A":"O tratamento envolve fludarabina e rituximab.","B":"O transplante de medula óssea é o tratamento de escolha para a maioria dos pacientes.","C":"O uso de sangrias terapêuticas é indicado.","D":"A anticoagulação é indicada em razão da hiperviscosidade sanguínea.","E":"A mutação JAK 2 confirma o diagnóstico e é exigida para ele."},"answer":"C","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-168487","number":"168487","sourceNumber":"168487","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Uma menina com 8 anos de idade encontra-se internada em unidade hospitalar para\ntratamento de leucemia linfoide aguda. Cerca de 15 dias após uma sessão de quimioterpia, a\npaciente apresenta episódio de febre de 38.5 ºC. Ao exame, verifica-se que a frequência cardíaca,\na frequência respiratória e a pressão arterial estão normais para a idade, não havendo nenhum\nsinal de localização da febre. O hemograma vem mantendo contagem de neutrófilos abaixo de 500\ncélulas/mm³ nos últimos 7 dias. A conduta apropriada a ser adotada para essa paciente é","options":{"A":"colher hemocultura (2 amostras) e urinocultura, realizar radiografia de tórax e tomografia de\nseios da face, e iniciar antibioticoterapia de acordo com os resultados dos exames","B":"colher hemocultura (2 amostras), avaliar a realização de radiografia de tórax e uroanálise, e\niniciar antibioticoterapia empírica de amplo espectro","C":"tratar o caso como choque séptico, iniciando expansão volêmica e antibioticoerapia empírica de\namplo espectro","D":"iniciar antibioticoterapia empírica de amplo espectro, após serem afastadas as causas não\ninfecciosas da febre"},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-168484","number":"168484","sourceNumber":"168484","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Uma criança do sexo masculino com 5 anos de idade apresenta, há 3 semanas, astenia\ne febre baixa diária, redução do apetite e\nmanchas arroxeadas nos membros. Além disso, acorda\nquase todas as noites com queixa de dores em membros inferiores. Ao exame físico, ela apresenta\nhepatoesplenomegalia, equimoses em membros inferiores e poliadenomegalia. O hemograma\nevidencia anemia normocítica e normocrômica, contagem de leucócitos normal (9.000\nlecócitos/mm³), com linfocítose e presença de linfócitos atípicos e plaquetopenia (80.000\nplaquetas/mm³). A dosagem de desidrogenase lática mostra-se elevada. Pesquisa de anticorpo\nanticapsídeo viral de Epstein Barr e sorologia para citomegalvírus evidenciam IgG positivo e IgM\nnegativo. A velocidade de hemossedimentação (VHS) está elevada e as aminotransferases estão\nnormais. De acordo com o presente quadro clínico-laboratorial o diagnóstico é","options":{"A":"mielofibrose.","B":"artrite idiopática juvenil.","C":"mononucleose infecciosa.","D":"leucemia linfoblástica aguda."},"answer":"D","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-104747","number":"104747","sourceNumber":"104747","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Um homem de sessenta anos de idade, portador de neoplasia prostática recidivada\npós-cirurgia, em tratamento com quimioterapia, procurou a emergência por apresentar febre e\nmal-estar geral. O exame físico evidenciou emagrecimento, queda de cabelos e pele seca com\n\nalgumas lesões descamativas. Temperatura axilar de 38 °C; FC = 100 bpm; PA = 122/70 mmHg e\nFR = 18 mrpm. O hemograma mostra\nneutropenia importante de 600 cel/mm³. Antes mesmo de\nreencaminhar esse paciente ao seu oncologista, deve-se instituir tratamento com","options":{"A":"Antifúngico.","B":"Antiviral de última geração.","C":"Quinolona.","D":"Anti-histamínico.","E":"Hidratação endovenosa."},"answer":"C","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-97833","number":"97833","sourceNumber":"97833","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Um homem com 30 anos de idade apresenta linfadenomegalia da cadeia cervical\nposterior e subclavicular. Refere episódios\nde febre, sudorese ? principalmente no período noturno\n\n? e perda de peso. Nega outras queixas. O exame físico geral e o específico não mostraram outras\nalterações. O resultado da punção biópsia aspirativa de um linfonodo cervical foi compatível com\nlinfoma de Hodgkin. Foi realizada tomografia computadorizada de tórax e abdome que não mostrou\nmassas ou envolvimento de outras cadeias de linfonodos, além das citadas acima. Qual a opção\nterapêutica mais adequada para o paciente?","options":{"A":"Radioterapia.","B":"Cirurgia e radioterapia.","C":"Cirurgia e quimioterapia.","D":"Quimioterapia e radioterapia."},"answer":"D","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-75494","number":"75494","sourceNumber":"75494","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Menina com 3 anos de idade é admitida na Enfermaria de um hospital regional, no\ninterior do estado, por apresentar, há três\nsemanas, dor na região lateral do pescoço, com\nadenomegalia cervical bilateral, febre e queda do estado geral. Fez uso de anti-inflamatório não\nhormonal, tendo diminuído o desconforto, mas persistido a adenomegalia à direita, a febrícula e a\ninapetência. O exame físico mostra cadeias ganglionares cervicais bilaterialmente palpáveis, sendo\nque, à direita, palpa-se massa de consistência elástica, com aproximadamente 1 cm em seu maior\ndiâmetro, levemente dolorosa. Há, neste mesmo lado, nodulação em região supraclavicular, indolor,\ncom aproximadamente 0,8 cm em seu maior diâmetro. Hemograma: hemácias = 3.5 x 10¹²/mm³;\nhematócrito = 32%; hemoglobina = 10,4 g%; leucograma:16.000 leucócitos/mm³ - linfócitos: 65%;\nlinfócitos atípicos: 32%. A principal justificativa de transferência dessa criança para avaliação\nimediata com especialista é:","options":{"A":"febre e adenomegalia persistentes.","B":"presença de nodulação supraclavicular.","C":"dor à palpação de cadeia ganglionar cervical.","D":"hemograma com atipia linfocitária exagerada.","E":"consistência elástica de gânglio cervical à palpação."},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-137585","number":"137585","sourceNumber":"137585","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Um pré-escolar de 3 anos de idade foi levado ao pediatra de um pequeno\nCentro de Saúde regional para avaliação de\npalidez cutâneo-mucosa. A mãe relatou que a\ncriança sempre gozou de boa saúde. Entretanto, há cerca de 2 meses, tem se apresentado\nprostrada. Além disso, tem se mostrado cada vez mais pálida e, no último mês, surgiram\npequenas manchas vermelhas na pele. Ao exame: a criança se apresentava hipoativa,\nhipocorada 2+/4+, hidratada, anictérica e acianótica. Foi detectada poliadenomegalia cervical\ne inguinal. As auscultas respiratória e cardíaca estavam normais. O abdome estava distendido,\nflácido, indolor, com fígado palpável a 5 cm do rebordo costal direito e o baço palpável a 3 cm do\nrebordo costal esquerdo. Foi detectado rash petequial disseminado. O\n\nhemograma evidencia hematócrito de 22% (valor de referência = 36 ± 4%), hemoglobina de 7\ng/dL (valor de referência = 11,8 ± 1,2 g/dL), volume corpuscular médio de 85 fL (valor de\nreferência = 80 fL), concentração de hemoglobina corpuscular média de 32 g/dL (valor de\nreferência = 32 g/dL), 75 000 leucócitos/mm³ (valor de referência = 4 000 a 14 000\nleucócitos/mm³ ) com atipia linfocitária acima de 30%, e plaquetometria de 15 000\nplaquetas/mm³ (valor de referência = 140 000 a 400 000 plaquetas/mm³ ). Tendo em vista o\nprovável diagnóstico, qual dos fatores descritos neste caso está associado a um bom\nprognóstico para este paciente?","options":{"A":"Leucometria > 50 000 leucócitos/mm³.","B":"Plaquetometria < 150 000/mm³.","C":"Evolução de doença < 6 meses.","D":"Atipia linfocitária > 30%.","E":"Idade do paciente > 1 ano."},"answer":"E","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-351615","number":"351615","sourceNumber":"351615","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Sobre o tratamento da anemia em pacientes instáveis, assinale a alternativa\nCORRETA:","options":{"A":"A análise da necessidade de transfusão de hemoderivados em pacientes com instabilidade\nhemodinâmica só deve ser feita após a avaliação da fonte de sangramento e a interrupção da\nhemorragia.","B":"A infusão de volume superior a 1,5L de cristaloides em paciente hemodinamicamente instável\ntem sido associada à redução da mortalidade.","C":"Os pacientes com sangramento ou trauma, estáveis, que não demandam transfusão maciça,\npodem se beneficiar de uma estratégia mais restritiva, mantendo um limiar de hemoglobina de\n7g/dL.","D":"A relação entre a realização de transfusão de concentrados de hemácias frescos versus os\ncongelados e estocados por até 42 dias, apresenta uma diferença significativa no que se refere à\nmortalidade."},"answer":"C","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-359207","number":"359207","sourceNumber":"359207","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Um senhor de 58 anos foi encaminhado do Serviço de Hematologia, devido a linfoma\nprimário esplênico das células da zona marginal, após tratamento com quimioterapia, já com\nindicação de tratamento cirúrgico. Nesse caso, a conduta CORRETA é indicar:","options":{"A":"Vacinação; esplenectomia com linfadenectomia e drenagem da cavidade mandatória.","B":"Vacinação; esplenectomia subtotal e drenagem da cavidade mandatória.","C":"Vacinação; esplenectomia com linfadenectomia e biópsia hepática.","D":"Esplenectomia com linfadenectomia e drenagem da cavidade mandatória, não sendo necessária\na vacinação."},"answer":"C","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-359214","number":"359214","sourceNumber":"359214","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Em pacientes em uso de quimioterapia, o desenvolvimento de neutropenia pode ser\ncomum em muitos casos. Sobre este conceito, assinale a alternativa INCORRETA.","options":{"A":"A cobertura de Pseudomonas aeruginosa é realizada devido à gravidade gerada pelas infecções\npelo germe nesses pacientes, apesar de muito\nraras.","B":"A medição de temperatura retal não é recomendada em neutropênicos pelo risco de\nmicrosangramentos gerando bacteremia ou sangramentos maiores.","C":"Neutropenia grave é definida, quando há um valor absoluto de neutrófilos < 500 cels/microL.","D":"A síndrome de reconstituição mieloide se dá por um processo inflamatório novo ou a piora de um\nprévio em associação temporal com a recuperação de neutrófilos de aplasia."},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-368200","number":"368200","sourceNumber":"368200","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Durante o tratamento de algumas doenças oncológicas, pode aparecer a chamada\nsíndrome de lise tumoral, que vem acompanhada\nde alterações metabólicas características e que\ndevem ser abordadas prontamente. Quais são as principais alterações metabólicas na lise tumoral?","options":{"A":"Hiperuricemia, hipocalemia, hipercalcemia.","B":"Hipouricemia, hipocalcemia, hipofosfatemia.","C":"Hipercalcemia, hipercalemia, hipofosfatemia.","D":"Hiperuricemia, hipercalemia, hiperfosfatemia."},"answer":"D","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-346841","number":"346841","sourceNumber":"346841","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Homem de 21 anos apresenta múltiplas sufusões pelo corpo de início há 3 dias. Nega\ntraumas, outras manifestações clínicas, comorbidades conhecidas, uso de medicamentos e de\ndrogas lícitas ou ilícitas. Não possui história familiar significativa. Ao exame físico, PA:\n110X70mmHg, FC: 68bpm, Tax: 36,5°C. Apresenta sufusões nos membros superiores, inferiores e\ntronco. Sem outras anormalidades quaisquer (incluindo linfonodomegalias ou visceromegalias\nabdominais). Exames de laboratório: Hemoglobina: 15,3g/dL (VR 12-16g/dL); Leucócitos:\n5.840/mm³ (4000-11.000/mm³); Neutrófilos: 2.580/mm³ (1500-7000/mm³); Linfócitos: 1.250/mm³\n(1.000-4.000/mm³); Plaquetas: 9.000/mm³ (150.000 - 450.000/mm³); Hematoscopia do sangue\nperiférico: presença de macroplaquetas, sem outras anormalidades; Creatinina: 0,7mg/dL;\nBilirrubina total: 0,4mg/dL (<1,2mg/dL); PCR: 1,2mg/L (<5mg/L); TSH: 1,560mUI/L (0,5-5,0mUI/L);\nRNI 1,1; PTTa 25/25; Exame de urina sem alterações. Assinale a alternativa que apresenta um\nexame diagnóstico CORRETAMENTE indicado para seguir a propedêutica desse caso.","options":{"A":"Fibrinogênio.","B":"Mielograma.","C":"Anticorpos anti-HIV.","D":"TC de pescoço, tórax e abdome total."},"answer":"C","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-346858","number":"346858","sourceNumber":"346858","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Em pediatria, são causas de anemia com plaquetopenia, EXCETO:","options":{"A":"Leishmaniose visceral.","B":"Leucemia linfocítica aguda.","C":"Deficiência de folatos e vitamina B12.","D":"Púrpura trombocitopênica autoimune (P.T.I) e púrpura de Henoch- Schonlein."},"answer":"D","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-334760","number":"334760","sourceNumber":"334760","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"No câncer infantil é correto afirmar:","options":{"A":"Os cânceres pediátricos mais frequentes são as leucemias, os tumores do sistema nervoso\ncentral e os linfomas.","B":"O câncer na faixa etária pediátrica geralmente é hereditário e, na maioria dos casos, apresentam\nhistória familiar e/ou associações com\nalterações genéticas ou congênitas. Entretanto, o\nretinoblastoma (tumor maligno intraocular) raramente tem origem genética.","C":"A trissomia 21 tem envolvido o gene GATA 1 que interfere na diferenciação celular. Esses\npacientes têm risco aumentado para o\ndesenvolvimento de neoplasia de sistema nervoso central\n(cerca de 10 vezes maior) e câncer de estômago.","D":"A leucemia aguda raramente acomete as crianças, possuindo um período de latência grande\ncom história tardia de surgimento dos sintomas."},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-336310","number":"336310","sourceNumber":"336310","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Paciente 70 anos, hipertensa e diabética, portadora de neoplasia no estômago, em\nquimioterapia com última sessão há 1 semana. Apresenta astenia e febre há 24 horas. Ao exame:\nconfusa, PA: 80/50 mmhg, FC 112 bpm, tempo enchimento capilar lentificado, sat02 94% em ar\nambiente, FR 21 irpm, temp axilar 38,4ºC. Exames laboratoriais: hb 6,5 g/dl/ leucócitos 1000 (70%\nPMN)/ plaquetas: 44.000 | Cr 1,2 / Ur 68 / K 3,8 / Na 130 / AST 27 / ALT 32 / BT 1,0 (BD 0,2). É\n\ncorreto afirmar:","options":{"A":"Recomenda-se prescrição de salina hipertônica diante da hiponatremia sintomática.","B":"Recomenda-se a prescrição de plaquetas com alvo de manutenção >50.000.","C":"Cefepime + Vancomicina é uma opção adequada para esquema antimicrobiano empírico.","D":"O início de antibioticoterapia deve aguardar investigação complementar pormenorizada dada a\nausência de urgência."},"answer":"C","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-313276","number":"313276","sourceNumber":"313276","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Para um paciente de 29 anos, que chega ao Pronto Atendimento, com um quadro de\nfebre a esclarecer, sem queixas álgicas e com SSVV estáveis, o Clínico solicita, inicialmente, um\nhemograma. No resultado, observa-se Atipias Pelger, que o médico entender como:","options":{"A":"Alteração benigna dos leucócitos.","B":"Alteração maligna dos leucócitos.","C":"Alteração benigna da forma dos eritrócitos.","D":"Alteração maligna da forma dos eritrócitos.","E":"Alteração na contagem de plaquetas."},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-291915","number":"291915","sourceNumber":"291915","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Com relação às formas de reversão das coagulopatias relacionadas à anticoagulação\noral, assinale a alternativa CORRETA:","options":{"A":"A ingestão de carvão ativado por via oral é eficiente para a redução da absorção até quatro\nhoras da administração de inibidores diretos\nda trombina.","B":"Os pacientes que utilizaram rivaroxabana devem ser submetidos a diálise nos casos mais\ngraves.","C":"O andexanet alfa deve ser administrado em pacientes que utilizaram inibidores do fator Xa\n(apixaban, rivaroxabana).","D":"O uso de Kcentra 50UI/Kg é indicado para pacientes que utilizaram inibidores da trombina."},"answer":"C","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-306710","number":"306710","sourceNumber":"306710","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"P.T.C., 32 anos, chega ao PS queixando-se de cansaço, dispneia e palidez cutânea,\nalém de manchas roxas pelo corpo. Foi\nrealizado hemograma cujo resultado demonstra contagem\nde hemácias = 3,32 milhões/mm³, hemoglobina = 6,4 g/dL, hematócrito = 25,6%, volume\ncorpuscular médio = 130fL, RDW 14,6%, Leucócitos = 1.500/mm³, plaquetas = 43.000/mm³. Com\nbase neste caso, assinale a alternativa correta.","options":{"A":"Caso o paciente apresente sangramentos ou febre haverá indicação de transfusão de plaquetas,\ndevendo-se transfundir 01 unidade de plaquetas para cada 15 Kg de peso corpóreo do paciente.","B":"A terapia transfusional liberal com o objetivo de manter níveis normais de hemoglobina\napresenta melhores resultados que a terapia\ntransfusional restritiva, com objetivo de manter\nhemoglobina maior que 7,0g/dL em pacientes não coronariopatas.","C":"A paciente apresenta quadro de pancitopenia, com volume corpuscular médio aumentado,\nquadro muito comum em episódios carenciais, em\nque a deficiência de ácido fólico, relacionada à\nnão ingestão de carne vermelha é a principal causa.","D":"Neste caso há indicação de terapia transfusional com concentrado de hemácias para que seja\nmantenha nível de hemoglobina acima de 7,0g/dL, devendo-se coletar exames de avaliação do\nperfil de ferro, reticulócitos, dosagem de vitamina B12 e ácido fólico anteriormente à transfusão."},"answer":"D","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-313298","number":"313298","sourceNumber":"313298","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Cerca de 90% dos pacientes com Leucemia Linfocítica Aguda - LLA apresentam\nalterações laboratoriais hematológicas, no\ndiagnóstico, e estas representam o grau de envolvimento\nda Medula Óssea pelos blastos. Aproximadamente, 80% dos pacientes apresentam anemia:","options":{"A":"Macrocítica e hipocrômica, com contagem de reticulócitos alta.","B":"Microcítica e hipocrômica, com contagem de reticulócitos alta.","C":"Microcítica e normocrômica, com contagem de reticulócitos baixa.","D":"Normocítica e hipocrômica, com contagem de reticulócitos baixa.","E":"Normocítica e normocrômica, com contagem de reticulócitos baixa."},"answer":"E","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-304874","number":"304874","sourceNumber":"304874","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Pré-escolar, três anos e nove meses, sexo feminino, vem apresentando dores ósseas\ndifusas iniciadas há três meses, que não\nmelhoram com o uso de analgésicos comuns, associados\na febre baixa intermitente, cefaleia, vômitos frequentes, anorexia, perda ponderal de quatro quilos\ne\nirritação com prejuízo de sono. A partir do resultado do hemograma, foi diagnosticado \"anemia\ndiscreta\" tendo sido prescrito sulfato ferroso por seis meses. Há um mês, a mãe notou palidez que\nvem se acentuando. Exame físico: irritabilidade, fáceis de sofrimento, dificuldade para deambular\npela dor, hipocorada +/4+, adenomegalias cervicais, axilares e inguinais móveis, fibroelásticas, não\ncoalescentes, medindo de 0,5 a 1 cm de diâmetro, fígado palpável a 5 cm, do rebordo costal direito,\nbaço a 4 cm do rebordo costal esquerdo, petéquias em membros inferiores e sopro sistólico +/4+\npancardíaco, sem irradiação. A principal hipótese diagnóstica é:","options":{"A":"Neuroblastoma.","B":"Febre reumática.","C":"Artrite idiopática Juvenil.","D":"Leucemia linfoide aguda."},"answer":"D","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-283886","number":"283886","sourceNumber":"283886","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Homem de 65 anos procura o consultório médico referindo progressiva fadiga nos\núltimos 6 meses. Traz estes exames realizados há 30 dias: hemoglobina: 9 g/dl; creatinina: 2,5\nmg/dl; eletroforese de proteínas: Qual o provável diagnóstico?","options":{"A":"Gamopatia monoclonal de significado incerto (MIGUS).","B":"Macroglobulinemia de Waldenstrom.","C":"Mieloma múltiplo.","D":"Amiloidose.","E":"Sepse urinária."},"answer":"C","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":["question_bank/media/medcurso/medcurso-hemato-hem-2/283886.png"],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-257345","number":"257345","sourceNumber":"257345","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Homem de 69 anos, realizou hemograma que revelou anormalidade, confirmada após\nrepetição do exame. Está assintomático. É portador de diabetes mellitus, artrite reumatoide e\nobesidade grau 3. Faz uso de metformina e prednisona 20mg. É tabagista e fuma 2 maços de\ncigarros ao dia, desde os 20 anos. Exames de laboratório: Hemoglobina: 14,3g/dL; Leucócitos:\n15.630/mm3 ; Neutrófilos Segmentados: 10.200/mm3 ; Neutrófilos Bastonetes: 980/mm3 ;\nLinfócitos: 3.340/mm3 ; Eosinófilos: 340/mm3 ; Monócitos: 670/mm3 ; Basófilos: 30/mm3 ;\nPlaquetas: 268.000/mm3 ; Hemoglobina Glicada: 9,3%; Proteína C reativa: 5mg/L. Assinale a\nalternativa que NÃO apresenta uma causa provável para a anormalidade hematológica\napresentada por esse paciente:","options":{"A":"Diabetes mellitus.","B":"Obesidade.","C":"Prednisona.","D":"Tabagismo."},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-266368","number":"266368","sourceNumber":"266368","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Assinale a alternativa correta sobre o linfoma de Hodgkin.","options":{"A":"O subtipo de celularidade mista é o mais comum.","B":"A apresentação infradiafragmática exclusiva implica em pior prognóstico.","C":"A ressonância nuclear magnética é considerada o exame padrão ouro para o diagnóstico inicial.","D":"Idade inferior a 45 anos e níveis de hemoglobina inferiores a 10 g/dL são fatores de pior\nprognóstico."},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-hemato-hem-2-287854","number":"287854","sourceNumber":"287854","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Em relação aos distúrbios da coagulação, assinalar a alternativa CORRETA:","options":{"A":"TTPa avalia integridade da via extrínseca da coagulação.","B":"Diagnóstico de hemofilia deve ser fortemente suspeitado quando o TTPa for diminuído.","C":"Doença de von Willebrand é a coagulopatia hereditária mais comum.","D":"Pacientes com plaquetopenia, em geral, apresentam hematomas musculares ou sangramentos\nintra-abdominais, enquanto pacientes com deficiência de fatores de coagulação, em geral,\napresentam sangramento em pele e mucosas.","E":"TP avalia integridade da via intrínseca da coagulação."},"answer":"C","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-283924","number":"283924","sourceNumber":"283924","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Uma criança de 5 anos é atendida no ambulatório por gengivorragia após escovação de\ndentes, episódios que se repetiam há 3 dias. Havia apresentado tosse, coriza hialina, diarreia e\nfebrícula na semana passada. Ao exame físico, a criança está em bom estado geral,\n\nobservando-se a presença de petéquias em pescoço e pálpebras e hematomas em ambos os\nmembros inferiores. Seus principais exames\ncomplementares mostram ecografia abdominal normal,\nhemoglobina de 11g/dl, leucócitos de 8.300/mm³ sem formas jovens e plaquetas de 21.000/mm³. A\nhipótese diagnóstica mais provável é:","options":{"A":"Síndrome hematofagocítica.","B":"Leucemia linfocítica aguda.","C":"Leucemia mielocítica aguda.","D":"Púrpura de Henoch-Schönlein.","E":"Púrpura trombocitopênica imune."},"answer":"E","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-227075","number":"227075","sourceNumber":"227075","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Homem de 18 anos se queixa de manchas roxas nos 4 membros há 3 semanas.\nDesconhece doenças prévias, nega uso de\nmedicamentos ou uso de quaisquer drogas ilícitas. Sem\noutras queixas. O exame físico revela áreas de sufusão na pele dos membros superiores e\ninferiores, indolores e planas. Sem outras anormalidades. Exame de laboratório: hemoglobina 15,1\ng/dl, VCM 88 fl, HCM 28 pg, CHCM 34 g/dl, leucócitos 7.800/mm³, neutrófilos 4.560/mm³, linfócitos\n1.240/mm³, plaquetas 4.000/mm³. Considerando o caso descrito, assinale a alternativa que\napresente um teste que NÃO está indicado na propedêutica inicial do paciente:","options":{"A":"Hematoscopia do sangue periférico.","B":"Mielograma.","C":"Sorologia para HIV.","D":"Sorologias para hepatites virais."},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-234413","number":"234413","sourceNumber":"234413","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Um homem de 43 anos, promotor de justiça, residente em Vitória/ES, vai ao pronto\natendimento com o relato de febre há 3 horas. É portador de câncer do reto, sem metástases, e\nrecebeu dose de quimioterapia há 8 dias. Não apresenta outras queixas. Nega infecções e\ninternações prévias, e não possui comorbidades. Ao exame físico, está alerta e orientado; as\nmucosas estão coradas e hidratadas. Os dados vitais são PA: 128 X 78mmHg, FC: 65bpm, FR:\n13ipm, SpO? 98%. Os exames cardiovascular, respiratório, do abdômen, da cavidade oral e da\nregião perianal não apresentam anormalidades. Foi administrada dose de piperacilina-tazobactam\npela via intravenosa enquanto se aguardavam os resultados dos exames. Exames de laboratório\n(solicitados na urgência): hemoglobina 8,9g/dL; leucócitos 1.870/mm³; neutrófilos segmentados\n280/mm³; plaquetas 95.000/mm³; proteína C reativa 46mg/L; creatinina 0,5mg/dL; ureia 15mg/dL;\nbilirrubina total 0,5mg/dL; exame de urina: sem anormalidades. Radiografia do tórax: sem\nanormalidades. Considerando o caso clínico apresentado, assinale a conduta MAIS ADEQUADA\npara esse paciente:","options":{"A":"Alta hospitalar com a prescrição de amoxicilina-clavulanato e ciprofloxacino pela via oral.","B":"Desospitalização com prescrição de meropenem pela via intravenosa para tratamento no\ndomicílio.","C":"Internação hospitalar e manutenção da prescrição de piperacilina-tazobactam pela via\nintravenosa.","D":"Internação hospitalar e substituição do antibiótico por cefepime pela via intravenosa."},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-227310","number":"227310","sourceNumber":"227310","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"As leucemias têm como principal característica o acúmulo de células jovens anormais,\ndenominadas de blastos, que substituem as células sanguíneas normais na medula óssea. Nas\nleucemias é CORRETO afirmar:","options":{"A":"A Leucemia Linfoide Aguda (LLA) é uma doença grave e a taxa de sobrevida atual da LLA na\ninfância é inferior a 30%.","B":"Nas LLA a idade entre 01 a 09 anos é um fator de bom prognóstico.","C":"Nas leucemias a dor óssea é rara. Quando ocorre, é mais comum nos membros superiores e é\ncontrolada com analgésicos habituais.","D":"As leucemias são raras na infância e a presença de febre significa infecção bacteriana,\nrelacionada à neutropenia."},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-246800","number":"246800","sourceNumber":"246800","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Paciente de 5 anos, feminino, com história de dor em membros inferiores de início há\n15 dias, acompanhada de astenia, palidez,\nfebre e equimoses. Hemograma com pancitopenia. Ao\nexame físico, evidenciou-se uma hepatoesplenomegalia. O diagnóstico mais provável é:","options":{"A":"Hemofilia","B":"Febre reumática","C":"Púrpura de Henoch-Schonlein","D":"Lúpus eritematoso sistêmico","E":"Leucemia aguda"},"answer":"E","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-196763","number":"196763","sourceNumber":"196763","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Em relação às complicações tardias das esplenectomias totais, está correto:","options":{"A":"Pode existir uma trombocitose persistente, mas sem implicações clínicas.","B":"O principal agente da sepse pós-esplenectomia é o Streptococcus pneumoniae.","C":"A sepse é geral geralmente benigna e a mortalidade muito baixa.","D":"A imunização apenas no pós-operatório é ineficaz."},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-212962","number":"212962","sourceNumber":"212962","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Em qual das seguintes situações está correta a indicação da transfusão de\nhemoderivados?","options":{"A":"Transfusão de concentrado de plaquetas em quando contagem plaquetária < 50.000/µL, mesmo\nna ausência de fatores de risco.","B":"Transfusão de concentrado de plaquetas nos casos de dengue com contagem plaquetária <\n10.000/µL, independente da existência ou não de sangramentos.","C":"Transfusão de concentrado de plaquetas nos casos de cirurgia neurológica com contagem\nplaquetária < 100.000/µL.","D":"Transfusão de concentrado de hemácias nos casos de pré-operatório de cirurgia abdominal de\ngrande porte com Hb < 11,0 g/dl.","E":"Transfusão de crioprecipitado nos casos de sangramento ativo com INR > 2,0."},"answer":"C","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-215096","number":"215096","sourceNumber":"215096","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Sr. RGP, vítima de acidente automobilístico grave, foi submetido a laparotomia\nexploradora que evidenciou grave lesão\nhepática, e volumoso hemoperitôneo, sendo necessária a\nexérese de 50% do lobo esquerdo do fígado. Exames: Hb 6,8 g/dl; Htco. 18,3%; plaquetas =\n22.000; TAP 40% (N = 70% a 120%) e PTTa 66?? (N = 29?? +/- 9??). Quais hemocomponentes\nvocê utilizaria para tratar o Sr. RGP, sabendo que ele é ?A? positivo?","options":{"A":"Sangue total A positivo, pois o paciente necessita repor hemácias, plaquetas e fatores da\ncoagulação.","B":"Concentrado de hemácias A positivo, plaquetas e crioprecipitado, pois houve grave lesão\nhepática.","C":"Sangue total A positivo, infundidos rapidamente, para não perdermos a ação dos fatores de\ncoagulação termo-lábeis.","D":"Concentrado de hemácias A positivo, plaquetas por aférese e plasma rico em plaquetas, pois a\nlesão mais grave é a plaquetopenia.","E":"Concentrado de hemácias A positivo, plaquetas e plasma fresco congelado."},"answer":"E","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-202773","number":"202773","sourceNumber":"202773","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Um paciente portador de púrpura trombocitopênica idiopática que é submetido à\nesplenectomia, deve ser submetido à imunização contra:","options":{"A":"Streptococcus pneumoniae, Haemophilus influenzae, Mycobacterium bovis.","B":"Streptococcus pneumoniae, Neisseria meningitidis, Mycobacterium bovis.","C":"Haemophilus influenzae, Neisseria meningitidis, Mycobacterium bovis.","D":"Streptococcus pneumoniae, vírus da hepatite B, Neisseria meningitidis.","E":"Streptococcus pneumoniae, Haemophilus influenzae, Neisseria meningitidis."},"answer":"E","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-199556","number":"199556","sourceNumber":"199556","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"As linfonodomegalias (aumento dos línfonodos) localizadas ou disseminadas são\ncaracterísticas de uma enorme gama de patologias em pediatria. Nas linfonodomegalias é\nCORRETO afirmar:","options":{"A":"Linfonodomegalia localizada, com febre por mais de 7 dias descarta linfomas, lúpus eritematoso\nsistêmico e tuberculose.","B":"O ácido úrico é encontrado em quantidade elevada nas células neoplásicas e pode estar\naumentado nas linfonodomegalias por linfomas e/ou leucemias.","C":"É mais evidente e frequente no período neonatal, pois o tecido linfático está aumentado de\nvolume para proteger o recém-nascido da\nexposição a antígenos que acontece durante a infância.","D":"Os linfonodos retroauriculares e supraclaviculares são considerados reacionais."},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-188005","number":"188005","sourceNumber":"188005","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Homem, 70 anos, procura o ambulatório de clínica médica com queixa de cansaço e\ndor lombar há 6 meses. Antecedentes pessoais: Hipertensão arterial com uso regular das\nmedicações. Trouxe exames complementares: Hemograma: Hemoglobina: 8,0 g/dL / VCM 83 /\nLeucócitos: 5.200/mm3 (Bastonestes 0%, Segmentados 67%, Eosinófilos 3%, Basófilos 0%,\n\nLinfócitos: 28%, Monócitos: 2%)) Plaquetas 250.000/mm3. Ureia: 120 mg/dL. Creatinina: 6,8 mg/dL,\nSódio: 140 mEq/L, Potássio: 4,2 mEq/L, Cálcio iônico: 13,1 mg/dL. Urina tipo 1: normal. Radiografia\nde coluna lombar: lesões líticas de L1 a L4. Que exame complementar deverá ser solicitado na\nsequência para definição diagnóstica?","options":{"A":"Dosagem de ferro sérico e ferritina.","B":"Eletroforese de proteínas séricas e urinária.","C":"Ressonância Magnética de coluna lombar.","D":"Eletroneuromiografia.","E":"Biópsia renal."},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-172752","number":"172752","sourceNumber":"172752","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Escolar com história de linfadenomegalia simétrica, palidez cutâneo-mucosa, febre,\nhepatoesplenomegalia, dor óssea e manifestações hemorrágicas nos membros. Qual o diagnóstico\nmais provável?","options":{"A":"Mononucleose infecciosa.","B":"Leucemia aguda.","C":"Linfoma de Hodgkin.","D":"Imunodeficiência primária."},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-155361","number":"155361","sourceNumber":"155361","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Em relação ao Mieloma Múltiplo (MM), assinale a alternativa CORRETA:","options":{"A":"É uma neoplasia benigna, de origem hematopoiética, caracterizada pela proliferação clonal de\nplasmócitos na medula óssea, que, na maioria dos casos, secretam proteína monoclonal detectável\nno sangue ou urina.","B":"Corresponde a aproximadamente 0,2% dos tumores malignos e a até 5% das neoplasias\nhematológicas.","C":"É mais frequente em mulheres do que em homens, e em brancos (caucasianos) do que em\nnegros.","D":"Mais de 90% dos casos ocorrem após os 50 anos, com pico de incidência no ocidente entre 60 e\n70 anos de idade.","E":"No Brasil, a doença ocorre mais tardiamente (a idade mediana dos pacientes ao diagnóstico é\nde 80 anos)"},"answer":"D","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-162588","number":"162588","sourceNumber":"162588","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Paciente feminina de 18 anos de idade consulta para pré-operatório de mamoplastia\nredutora. Refere história de sangramento intenso\napós extração dentária. Exames pré-operatórios\ndemonstraram hemograma normal, TTPA 52s (VR: < 35s), INR 1,02 (VR: 1,0 ? 1,3). Qual o\ndiagnóstico mais provável?","options":{"A":"Afibrinogenemia congênita.","B":"Hemofilia A.","C":"Doença de Von Willebrand.","D":"Deficiência de Fator XIII.","E":"Deficiência de Fator V."},"answer":"C","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-148574","number":"148574","sourceNumber":"148574","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Paciente com história de febre há 12 dias, associada a mialgia leve e artralgia. Durante\no exame físico, foram encontrados linfonodos\ncervicais palpáveis em cadeias cervical anterior e\nposterior, dolorosos à palpação, de consistência elástica e não aderidos aos planos profundos.\n\nDevem estar presentes as seguintes etiologias no diagnóstico diferencial:","options":{"A":"Tuberculose ganglionar, histoplasmose disseminada, toxoplasmose, infecção por Epstein-Barr.","B":"Infecção aguda pelo HIV, tuberculose ganglionar, dengue, infecção por citomegalovírus.","C":"Sífilis, infecção por citomegalovírus, leptospirose, rubéola.","D":"Infecção aguda pelo HIV, doença de Chagas, infecção por Epstein-Barr e aspergilose invasiva.","E":"Aspergilose invasiva, sífilis, infecção por citomegalovírus, infecção aguda pelo HIV."},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-137821","number":"137821","sourceNumber":"137821","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Paciente masculino, 62 anos, portador de neoplasia de pulmão metastático,\n\nencontra-se em tratamento quimioterápico e evolui com quadro de febre aferida, temperatura axilar\nde 38ºC, há um dia. Nega outros sintomas e\nexame físico sem alterações. Hemograma\napresentando leucócitos totais: 950/mm3. Qual dos fatores abaixo é considerado de bom\nprognóstico na abordagem inicial da neutropenia 220/mm3 febril?","options":{"A":"Tratamento precoce com claritromicina ambulatorial.","B":"Profilaxia com quinolonas.","C":"Hipotensão.","D":"RX de tórax normal.","E":"Hospitalização precoce."},"answer":"E","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-111567","number":"111567","sourceNumber":"111567","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Homem de 69 anos é internado numa enfermaria de clínica geral. Os dados de\nanamnese mais relevantes são: prostração,\núltima evacuação há uma semana, náuseas, poliúria,\ncefaleia e dificuldade em reconhecer os familiares. À propedêutica física, observam-se: mucosas\nressecadas e descoradas, além de delirium. Os exames mostram: áreas líticas em calota craniana\ne eritrócitos em roulleaux. É provável que à biópsia de medula óssea, detecte-se aumento\nsignificativo no número de","options":{"A":"células de Reed-Sternberg.","B":"mieloblastos.","C":"linfoblastos.","D":"neutrófilos hipersegmentados.","E":"plasmócitos."},"answer":"E","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-111571","number":"111571","sourceNumber":"111571","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Considere algumas características de linfomas: I. Não costuma apresentar sintomas\ncompressivos. II. Apresentação clínica variada, porém segue estereótipo de massa linfonodal\nindolor e sintomas sistêmicos. III. Sítio de origem com predomínio nodal, mas podendo ser\nextranodal em até 35% dos casos. IV. Disseminação linfonodal sem contiguidade. São próprios do\nlinfoma não-Hodgkin APENAS:","options":{"A":"I e III.","B":"I e II.","C":"II e III.","D":"I e IV.","E":"III e IV."},"answer":"E","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-88876","number":"88876","sourceNumber":"88876","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"A apresentação clínica inicial na maioria dos pacientes com linfomas não Hodgkin se\ncaracteriza por:","options":{"A":"Linfadenopatia periférica indolor.","B":"Anemia hemolítica autoimune.","C":"Perda ponderal acelerada.","D":"Sudorese noturna profusa.","E":"Pancitopenia febril."},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-43314","number":"43314","sourceNumber":"43314","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Dentre as patologias citadas, qual o principal diagnóstico diferencial na interpretação\ndo\nhemograma: Hemácias em milhões/mm³ = 4; Hemoglobina em g/dl = 12,4; Hematócrito em % = 37;\nVol. Glob. Média em u3 = 78; Hem. Glob. Média em uug = 25,9; C.H. Glob. Média em % = 33,3;\nRDW = 15,5; MPV = 10,4; Leucócitos por mm³ = 12.100; Neutrófilos = 7% 847; Promielócitos = 0%\n\n0; Mielócitos = 0% 0; Metamielócitos = 0% 0; Bastões = 0% 0; Segmentados 7% 847; Eosinófilos =\n\n2% 242; Basófilos 0% 0; Linfócitos típicos = 19% 2.299; Monócitos = 0% 0; Blastos = 72% 8.712;\nPlaquetas = 83.000 K/ul?","options":{"A":"Trombocitemia Essencial.","B":"Púrpura Trombocitopênica Imunológica.","C":"Anemia Ferropriva.","D":"Leucose Aguda.","E":"Mielodisplasia."},"answer":"D","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-363984","number":"363984","sourceNumber":"363984","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Qual anormalidade cromossômica no Mieloma Múltiplo é altamente sensível à ação do\ninibidor de BCL2 venetoclax?","options":{"A":"Translocação t (14; 16).","B":"Translocação t (11; 14).","C":"Ganho do cromossomo 1 (+1q).","D":"Deleção do 17p del (17p)."},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-363983","number":"363983","sourceNumber":"363983","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"A doença de von Willebrand subtipo 2A se caracteriza por","options":{"A":"aumento da ligação do fator de von Willebrand às plaquetas, levando à plaquetopenia.","B":"redução da ligação do fator de von Willebrand às plaquetas e ao colágeno, com redução dos\nníveis séricos de fator de von Willebrand.","C":"perda da função de ligação do fator de von Willebrand às plaquetas, com uma redução dos\nmultímeros de alto peso molecular mais efetivos.","D":"redução da ligação do fator de von Willebrand ao fator VIII da coagulação, com redução dos\nníveis séricos de fator de von Willebrand e do fator VIII."},"answer":"C","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-355601","number":"355601","sourceNumber":"355601","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Pré-escolar, três anos, é atendido no ambulatório de pediatria geral com queixas de\nfebre e dor nas pernas. A febre tem sido\nintermitente, tendo chegado a 38,6°C nos últimos cinco\ndias e a dor nas pernas o tem acordado à noite. As vacinas estão atualizadas e o paciente não tem\ncomorbidades. Mãe relata que recentemente surgiram algumas manchas arroxeadas nos braços e\npernas, porém, relaciona a trauma associado a atividades. Refere infecção viral prévia há\naproximadamente três semanas, com resolução espontânea. Sinais vitais: Tax. 38,2°C, FC 120\nbatimentos/minuto, FR 24 irpm, PA 100 x 60 mmHg e saturação de oxigênio de 15 100% em ar\nambiente. Adenomegalia cervical inexpressiva. Ausculta cardíaca e pulmonar sem alterações.\n\nAbdome sem hepatoesplenomegalia. Presença de equimoses discretamente dolorosas em áreas\nexpostas e não expostas. Exame neurológico\nsem alterações. Exames laboratoriais: 1.500\nleucócitos/mm3 (5% de eosinófilos, 5% neutrófilos, 85% linfócitos, 5% monócitos); hemoglobina 8,5\ng/dL, hematócrito 24%, reticulócitos 0,4%, plaquetas 75.000/mm³ . O diagnóstico mais provável\npara esse paciente é de:","options":{"A":"anemia aplástica.","B":"leucemia linfocítica aguda","C":"leucemia linfocítica crônica","D":"mononucleose infecciosa","E":"imunossupressão pós-viral"},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-354823","number":"354823","sourceNumber":"354823","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Leia o relato do caso clínico a seguir. Paciente cirrótico Child-Pugh C, 53 anos de\nidade, apresenta quadro clínico e radiológico\ncompatível com apendicite aguda. A equipe cirúrgica\nindicou apendicectomia. Os resultados dos exames laboratoriais atuais são: Hb: 12,6 g/dL; Ht:\n38,9%, LT: 4200; plaq: 78.000 cel/mm³; tempo de protrombina: RNI: 1,69; tempo de tromboplastina\nparcial ativado: relação P/N: 1,31. De acordo com o caso relatado, qual é a conduta transfusional a\nser adotada?","options":{"A":"Transfusão de 1 UI de plaquetaférese pré-procedimento cirúrgico.","B":"Transfusão de 10 mL/Kg de plasma fresco congelado pré-procedimento.","C":"Transfusão de 2 UI de plaquetaférese pré-procedimento cirúrgico.","D":"Transfusão de 25 mL/Kg de plasma fresco congelado pré-procedimento."},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-354797","number":"354797","sourceNumber":"354797","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Leia o relato do caso clínico a seguir. Paciente, 19 anos de idade, sexo masculino,\napresenta confusão mental e cefaleia há 4 dias,\nalém de petéquias em todo o corpo. Os resultados\ndos exames laboratoriais são: Hb: 5,5g/dL; Plaquetas: 29.000/mm³; Esquizócitos em lâmina de\nsangue periférico; Desidrogenase lática (DHL): 2.400 UI/dL (VR: até 246 UI/dL); Teste antiglobina\ndireto: negativo. De acordo com o caso relatado qual é a principal suspeita diagnóstica?","options":{"A":"Anemia hemolítica auto-imune.","B":"Microangiopatia trombótica.","C":"Púrpura trombocitopênica imune.","D":"Aplasia de medula óssea."},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-334769","number":"334769","sourceNumber":"334769","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Paciente de 32 anos de idade realizou quimioterapia de consolidação para leucemia\nlinfoblástica aguda (LLA) com altas doses de\nmetotrexato e citarabina há 7 dias. Procurou pronto\natendimento do hospital escola relatando febre aferida de 38,4°C, negava qualquer sinal ou sintoma\ninfeccioso. O hemograma solicitado na urgência revelou 300 neutrófilos/mm³. Neste caso, qual é a\nconduta a ser utilizada?","options":{"A":"colher hemoculturas e exames de bioquímica e orientar o paciente a retornar em 12 horas para\nreavaliação já que está sem foco infeccioso identificável.","B":"colher hemoculturas e exames de bioquímica e iniciar amoxicilina por via oral e reavaliar em o\npaciente em 24 horas.","C":"internar o paciente e após coleta de hemoculturas e exames gerais, e iniciar antibioticoterapia\nparenteral de amplo espectro com droga que tenha\nação antipseudomonas.","D":"internar paciente e após coleta de hemoculturas e iniciar ceftriaxona caso haja evidencia de\nbactéria resistente escalonar antibioticoterapia posteriormente."},"answer":"C","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-321554","number":"321554","sourceNumber":"321554","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Leia o caso clínico. Paciente submetido a quimioterapia com fludarabina e\nciclofosfamida, seguido de terapia com receptor\ndo antígeno quimérico de células T (CAR-T cell)\npor leucemia linfoide aguda. No sexto dia, após a infusão das células, paciente apresenta\ntemperatura de 38.9ºC, hipotensão, com necessidade de altas doses de drogas vasoativas,\naumento pronunciado de proteína C reativa e procalcitonina normal. O diagnóstico apropriado para\no paciente é de","options":{"A":"choque séptico.","B":"síndrome de liberação de citocinas.","C":"toxicidade a quimioterápicos.","D":"síndrome de neurotoxicidade associada a células efetoras imunes."},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-346434","number":"346434","sourceNumber":"346434","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Homem de 47 anos, com câncer de estômago, em tratamento quimioterápico, chega ao\npronto socorro com queixa de febre alta (39,2ºC) e tosse com expectoração clara. Apresenta sinais\nvitais estáveis e a radiografia de tórax é normal. Assinale a alternativa correta quanto à conduta\nimediata a ser tomada:","options":{"A":"Solicitar uma tomografia de tórax em virtude da tosse. Caso venha normal, orientar o paciente e\nprescrever sintomáticos para casa;","B":"Iniciar antibioticoterapia endovenosa empírica independente do hemograma, haja visto que a\npaciente está em tratamento com quimioterapia;","C":"Solicitar hemograma e, se leucócitos abaixo de 1000 cels/mm3, coletar as culturas e iniciar\nantibioticoterapia empírica endovenosa imediatamente;","D":"Após um exame físico minucioso, caso nenhum foco infeccioso seja identificado, prescrever\nsintomáticos e orientar o paciente. Exames\nsubsidiários neste caso não são necessários porque o\npaciente está estável, sendo a clínica soberana."},"answer":"C","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-342630","number":"342630","sourceNumber":"342630","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Um homem de 49 anos apresenta insuficiência renal aguda e diminuição do nível de\nconsciência. Exames laboratoriais revelam leucocitose discreta com neutrofilia e trombocitopenia\nsevera (<10.000/mm?). A avaliação do sangue periférico, por sua vez, mostra anemia\nmicroangiopática. Os testes de coagulação são normais. O diagnóstico mais provável é:","options":{"A":"anemia hemolítica autoimune","B":"púrpura trombocitopênica trombótica","C":"coagulação intravascul lar disseminada","D":"síndrome do anticorpo antifosfolípide"},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-342647","number":"342647","sourceNumber":"342647","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Qual é a causa mais frequente de linfadenomegalia na infância?","options":{"A":"hiperplasia policlonal reacional","B":"tuberculose","C":"linfoma de Hodgkin","D":"doença da arranhadura do gato"},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-315769","number":"315769","sourceNumber":"315769","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Quando a TFGe chegar em 15mL/ min/1,73m2, devemos evitar o uso de enoxaparina.\nEstá correto que:","options":{"A":"Uma alternativa nessa condição é a Heparina Não Fracionada HNF, pois tem metabolismo\nexclusivamente renal.","B":"Uma alternativa nessa condição não é a Heparina Não Fracionada HNF, pois tem metabolismo\nexclusivamente hepático.","C":"Uma alternativa nessa condição é a Heparina Não Fracionada HNF, pois tem metabolismo\nexclusivamente hepático.","D":"Uma alternativa nessa condição é a Heparina Não Fracionada HNF, pois tem metabolismo não\nexclusivamente hepático."},"answer":"C","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-315774","number":"315774","sourceNumber":"315774","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Entre os anticoagulantes injetáveis, a HNF foi a primeira sintetizada. Sendo correto o\nitem:","options":{"A":"A heparina é um polissacarídeo não sulfatado com uma faixa de peso molecular de 3.000 a\n30.000Da (média, 15.000Da).","B":"A heparina é um amido sulfatado com uma faixa de peso molecular de 3.000 a 30.000Da\n(média, 15.000Da).","C":"A heparina é um polissacarídeo sulfatado com uma faixa de peso molecular de 3.000 a\n30.000Da (média, 15.000Da).","D":"A heparina é um ácido sulfatado com uma faixa de peso molecular de 3.000 a 30.000Da (média,\n15.000Da)."},"answer":"C","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-314105","number":"314105","sourceNumber":"314105","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Paciente do sexo masculino de 38 anos procura médico para avaliação de massa em\ncavidade oral em região de palato associado a sintomas B, com febre e perda de peso. Em\ninvestigação, foi observado ser paciente com sorologia positiva para HIV. Após realizar a biópsia da\nlesão, o resultado esperado é linfoma:","options":{"A":"Plasmablástico.","B":"Imunoblástico.","C":"Linfoblástico.","D":"De Burkitt."},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-294263","number":"294263","sourceNumber":"294263","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Qual dos anticoagulantes diretos a seguir tem maior depuração renal?","options":{"A":"Dabigatrana.","B":"Rivaroxabana.","C":"Edoxabana.","D":"Apixabana."},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-316315","number":"316315","sourceNumber":"316315","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Sobre neutropenia febril, assinale a alternativa ERRADA:","options":{"A":"As principais portas de entrada para infecções nos pacientes neutropênicos são pele, trato\nrespiratório superior e trato gastrointestinal.","B":"A primeira medida após o diagnóstico de neutropenia febril é o início de esquema empírico de\nantibiótico.","C":"A instituição de terapia empírica deve ser realizada com ceftriaxone ou ciprofloxacino.","D":"A presença de mucosite predispõe à reativação de herpes simples e ela se manifesta na forma\nde úlceras na mucosa, como na primoinfecção."},"answer":"C","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-316316","number":"316316","sourceNumber":"316316","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Paciente de 82 anos de idade apresenta, em exames de rotina, o seguinte hemograma:\nHb 11,8 g/dl; Ht 34,4%; VCM 82 fl; HCM 33 pg;\nRDW 12 %; global de leucócitos 22.380; bastões\n\n0%; segmentados 24%; eosinófilos 1%; basófilos 0,2%; linfócitos típicos 71,2%; monócitos 3,6%;\nplaquetas 290.000/mm. Qual a principal hipótese diagnóstica?","options":{"A":"Leucemia linfoblástica aguda.","B":"Leucemia linfocítica crônica.","C":"Leucemia mieloide aguda.","D":"Leucemia mieloide crônica."},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-311912","number":"311912","sourceNumber":"311912","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Na investigação de um paciente com neutropenia, é correto dizer que:","options":{"A":"na mielodisplasia, a celularidade da medula óssea estará normal ou aumentada e a morfologia\ndas células normal.","B":"na anemia megaloblástica muitas vezes dispensa a análise da medula óssea quando se observa\nmacrócitos ovais e VCM alto no sangue periférico.","C":"no hiperesplenismo, apesar da morfologia celular normal, a população celular na medula óssea\nestará suprimida por sequestro esplênico.","D":"na leucemia aguda, a medula óssea se encontra hipocelular, com células de morfologia anormal\n(leucoblastos e mieloblastos)."},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-295359","number":"295359","sourceNumber":"295359","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Qual dessas doenças não faz parte do grupo de gamopatias monoclonais?","options":{"A":"Síndrome POEMS.","B":"Agamaglobulinemia ligada ao X.","C":"Amiloidose de cadeias leves.","D":"Macroglogulinemia de Waldenstrom."},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-311913","number":"311913","sourceNumber":"311913","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Na avaliação de um paciente com um possível estado de hipercoagulabilidade,","options":{"A":"se o paciente apresentar necrose cutânea após iniciar uso de varfarina, deve-se pesquisar\ndeficiência de proteína C ou proteína S.","B":"níveis séricos diminuídos de proteína C, proteína S e antitrombina em pacientes com trombose\naguda apontam para distúrbio hereditário da\ncoagulação.","C":"a ocorrência de trombose arterial, após os 40 anos, em pacientes com história familiar para\ntrombose, indica a presença de estados de hipercoagulabilidade hereditários.","D":"a trombose de veia hepática (síndrome de Budd-Chiari) ou a trombose de veia porta podem\nindicar neoplasia maligna oculta ou endocardite não bacteriana."},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-317945","number":"317945","sourceNumber":"317945","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Qual das seguintes proteínas inibe a hemostasia?","options":{"A":"Trombina.","B":"Fator tecidual.","C":"Fibrina.","D":"Proteína C."},"answer":"D","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-294272","number":"294272","sourceNumber":"294272","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Diante de paciente jovem do sexo feminino com quadro de anemia hemolítica\nmicroangiopática, trombocitopenia, manifestação neurológica e aumento de escórias renais, a\nmelhor hipótese diagnóstica é de:","options":{"A":"Púrpura trombocitopênica imune.","B":"Púrpura trombocitopênica trombótica.","C":"Púrpura de Gardner-Diamond.","D":"Púrpura de Henoch-Schönlein."},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-311914","number":"311914","sourceNumber":"311914","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Sobre os anticoagulantes de ação direta (DOAC), afirma-se:","options":{"A":"a apixabana tem tempo de meia-vida entre 9 a 14 horas e, apesar da posologia de duas\ntomadas diárias, apresenta baixa taxa de sangramentos em relação à varfarina.","B":"a rivaroxabana foi o primeiro DOAC a ser aprovado e, por possuir tempo de meia-vida de quase\n24h, permite o uso em dose única diária.","C":"a dabigatrana é um inibidor direto do fator X ativado que apresenta metabolização hepática e\neliminação predominantemente intestinal.","D":"a edoxabana é um pró-fármaco cujo metabólito ativo inibe diretamente a trombina, sendo seu\nuso restrito em renais crônicos por ter\neliminação predominantemente renal."},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-302866","number":"302866","sourceNumber":"302866","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Menino de três anos é admitido no pronto atendimento com queixa de epistaxe\nespontânea há algumas horas, de volume\npequeno. A mãe do paciente relata história de infecção\nviral do trato gastrointestinal (diarreia aguda) há 2 semanas, com resolução completa. Ao exame:\nbom estado geral, corado, hidratado. Ausculta cardíaca e pulmonar sem alterações. Baço, fígado e\nlinfonodos não palpáveis. Equimoses e petéquias evidentes em membros inferiores, sem outras\nalterações. Hemograma evidenciando: hemoglobina 13,0 g/dl; VCM 80 fL; leucócitos 9.700/mm3,\ncom contagem diferencial normal; plaquetas 15.000/mm3; 1% de reticulócitos. O diagnóstico mais\nprovável é:","options":{"A":"Leucemia aguda.","B":"Síndrome hemolítico-urêmica.","C":"Púrpura trombocitopênica trombótica.","D":"Púrpura trombocitopênica idiopática.","E":"Doença de Gaucher."},"answer":"D","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-313216","number":"313216","sourceNumber":"313216","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"O uso da vitamina K profilática no recém-nascido reduz a incidência de que patologia?","options":{"A":"icterícia neonatal","B":"doença hemorrágica do recém-nascido","C":"fenilcetonúria","D":"sepse neonatal"},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-300937","number":"300937","sourceNumber":"300937","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Assinale a alternativa CORRETA levando-se em consideração o diagnóstico de\nneutropenia febril:","options":{"A":"É considerada um diagnóstico de exclusão, motivo pelo qual deve-se buscar exaustivamente a\ncausa da febre antes de instituir o tratamento.","B":"Deve ser considerada também para pacientes febris que estão fora de tratamento\nantineoplásico.","C":"Tem a mesma conotação para os pacientes em tratamento oncológico e para os pacientes\nportadores de aplasia medular medicamentosa.","D":"Precisa ser tratada o mais precocemente possível para reduzir a morbidade e a mortalidade dos\npacientes em tratamento quimioterápico."},"answer":"D","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-300953","number":"300953","sourceNumber":"300953","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Assinale a alternativa CORRETA que corresponde ao sintoma de apresentação mais\nfrequente da doença do enxerto X hospedeiro:","options":{"A":"Icterícia.","B":"Hematoquezia.","C":"Dor abdominal.","D":"Erupção cutânea maculopapular."},"answer":"D","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-300981","number":"300981","sourceNumber":"300981","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"O uso de heparina não fracionada no ambiente hospitalar é uma rotina do clínico e faz\nparte do arsenal no manejo de profilaxia de tromboembolismo venoso, quanto das medidas para\nanticoagulação plena. O exame laboratorial para controle de anticoagulação desta droga é:","options":{"A":"Tempo de Protrombina (TAP).","B":"Tempo de Tromboplastina Parcial Ativada (TTPA).","C":"Dosagem de fator VIII.","D":"Tempo de Sangramento (TS)."},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-308297","number":"308297","sourceNumber":"308297","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Em relação às doenças neoplásicas na infância, qual a mais prevalente?","options":{"A":"Leucemia.","B":"Tumor de Wilms.","C":"Linfoma.","D":"Neuroblastoma."},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-311979","number":"311979","sourceNumber":"311979","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"\"O Instituto Nacional do Câncer (INCA) estima a ocorrência anual de aproximadamente\n420 mil casos novos de câncer para o Brasil\nno biênio 2016-2017 (excluindo-se os tumores de pele\nnão melanoma). O câncer infanto-juvenil representa de 1 a 3% dos casos, estimando-se, assim, a\nocorrência de 12.600 novos casos de câncer na faixa etária de 0 a 19 anos para o ano de 2017.\"\nDisponível em: https://www.inca.gov.br/estimativa/introdução. Acesso em:13 de jan.2022. Embora o\ncâncer na criança e no adolescente seja raro, representa a principal causa de óbito por doença\nnesta faixa etária. Quais sinais ou sintomas abaixo estão mais relacionados a sinais de alerta para\ncâncer?","options":{"A":"Linfonodo retroauricular 1cm de diâmetro, indolor, sem febre associada, sem vermelhidão.","B":"Dor em membros inferiores difusa, não capacitante, uma vez por semana, vespertina, com\nhemograma normal.","C":"Dor abdominal periumbilical, duas vezes por semana, pós-alimentar, sem massas palpáveis.","D":"Cefaleia vespertina três vezes ao mês, sem vômitos, leve intensidade, sem progressão."},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-277404","number":"277404","sourceNumber":"277404","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Assinale a alternativa que não apresenta um aspecto prognóstico relevante nas\nleucemias linfocíticas agudas (LLAs):","options":{"A":"idade avançada","B":"número de cromossomos no cariótipo","C":"febre","D":"leucometria inicial"},"answer":"C","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-281982","number":"281982","sourceNumber":"281982","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Os quadros clínicos compatíveis com sangramentos relacionados a defeitos na\nhemostasia primária são:","options":{"A":"Hemartroses e sangramento em trato gastrointestinal (TGI).","B":"Petéquias e sangramento mucocutâneo.","C":"Hematomas musculares e sangramento em sistema nervoso central.","D":"Hemartroses e hematúria."},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-281272","number":"281272","sourceNumber":"281272","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"São causas de síndrome hemofagocítica secundária (adquirida) todas as abaixo,\nexceto:","options":{"A":"Infecções virais.","B":"Doenças autoimunes.","C":"Neoplasias.","D":"Intoxicações."},"answer":"D","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-281985","number":"281985","sourceNumber":"281985","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Paciente de 51 anos, mulher, com diagnóstico de câncer de mama, encontra-se em\nquimioterapia adjuvante. Procurou o pronto-socorro 10 dias após sua quimioterapia, relatando febre\nde 39ºC há 3 dias associada à tosse seca. Nega outras queixas associadas. Nega tabagismo e\nnega etilismo. Ao exame encontrava-se em bom estado geral; descorada +/4+; PA 120 x 80 mmHg;\nlúcida e orientada em tempo e espaço; hidratada; febril ao toque e eupneica em ar ambiente. Rx de\ntórax PA normal. Exame de urina 1 normal. Hemograma com Hb 10 g/dl; leucócitos 1.000 / µL\n(neutrófilos 400/ µL) e plaquetas de 100.000/mm3. Qual alternativa melhor descreve o caso acima\nde neutropenia febril e qual a melhor conduta?","options":{"A":"Escala MASCC ? 21; considerar tratamento com antibiótico oral em casa com Ciprofloxacino e\nClindamicina + Clavulanato.","B":"Escala MASCC < 21 e tratamento com antibiótico endovenoso em regime de internação com\nPiperacilina e Tazobactam.","C":"Escala MASCC ? 21; considerar tratamento em regime de internação com Cefepime.","D":"Escala MASCC ? 21; considerar tratamento com antibiótico oral em casa com Ciprofloxacino e\nAmoxicilina + Clavulanato."},"answer":"D","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-257726","number":"257726","sourceNumber":"257726","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Mulher de 72 anos é admitida na unidade de emergência após acidente automotivo. A\nhistória médica pregressa inclui insuficiência renal leve, fibrilação atrial, hipertensão e\ndiabetes. Ela\nestá atualmente tomando lisinopril, varfarina e metformina. Os valores dos resultados dos testes\nlaboratoriais incluem: contagem de leucócitos 12.000/µL com diferencial normal, hemoglobina 7,4\ng/dL, plaquetas 256.000/µL e INR 4,86. A esplenectomia emergencial é realizada após laceração\nesplênica. A paciente recebeu sete unidades de glóbulos vermelhos de doadores ABO compatíveis\ne seis unidades de plasma fresco congelado. Sua evolução no pós-operatório imediato é normal e\nela está recebendo fluidos intravenosos contínuos. Oito horas depois, a enfermeira relata dispneia\ne taquicardia progressivas. Ela não tem febre ou expectoração. O exame revela uma saturação de\noxigênio de 90% pela oximetria de pulso, frequência cardíaca de 106 BPM, pressão arterial de\n160/90 mmHg, distensão venosa jugular, 2+ edema bilateral de membros inferiores, sem\nsensibilidade na panturrilha e fígado palpável. A radiografia de tórax demonstra pequeno derrame\npleural bilateral e infiltrados hilares. Qual é a próxima etapa mais apropriada no manejo desse\npaciente?","options":{"A":"Antibióticos de amplo espectro.","B":"Anticoagulação empírica e angiotomografia computadorizada.","C":"Furosemida.","D":"Esteróides."},"answer":"C","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-258176","number":"258176","sourceNumber":"258176","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Paciente de 72 anos, do sexo feminino, assintomática, em exame de rotina notado com\npico monoclonal de 3,8 g/dl em gamaglobulina. Apresenta creatina sérica de 1,4 mg/dl, cálcio sérico\nde 8,1 mg/dl, tomografia de corpo todo de baixa intensidade normal, mielograma com infiltração\nplasmocitária de 18%, relação de cadeias leves livres kappa/lambda: 120. Segundo o International\nMyeloma Working Group, trata-se de:","options":{"A":"Síndrome de POEMS.","B":"Pico monoclonal de significado indeterminado.","C":"Mieloma múltiplo indolente.","D":"Mieloma múltiplo ativo."},"answer":"D","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-257727","number":"257727","sourceNumber":"257727","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Mulher de 43 anos se apresenta ao pronto-socorro com história de desconforto\nabdominal progressivo e ganho de peso há três\nsemanas. Ela relata não possuir doenças\npregressas e não faz uso de medicamentos. No exame físico, nota-se uma face pletórica. O\nabdômen está tenso, sensível e moderadamente distendido. Os achados laboratoriais demonstram\nhemoglobina de 18,7 g/dL, contagem de leucócitos de 9000/µL, contagem de plaquetas de\n401.000/ µL, nível de alanina aminotransferase (ALT) de 84 U/L, aspartato aminotransferase (AST)\nde 107 U/L e nível de bilirrubina total de 0,9 mg/dL. O teste sérico de gravidez é negativo. A\nultrassonografia abdominal com doppler demonstra trombose da veia hepática. Qual dos seguintes\ntestes de diagnóstico tem mais probabilidade de estabelecer a causa da apresentação clínica da\npaciente?","options":{"A":"Pesquisa da mutação JAK2V617F.","B":"Pesquisa de trombofilias hereditárias.","C":"Tomografia computadorizada (TC) helicoidal do abdômen.","D":"Citometria de fluxo para expressão de CD55 e CD59."},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-258177","number":"258177","sourceNumber":"258177","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"O Blinatumomab é um anticorpo monoclonal biespecífico, utilizado no tratamento de\nleucemias linfóides agudas como tratamento de segunda linha. O anticorpo de liga aos sítios de\nligação:","options":{"A":"CD20 e CD5.","B":"CD19 e CD3.","C":"CD19 e CD5.","D":"CD20 e CD3."},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-258179","number":"258179","sourceNumber":"258179","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Pacientes com diagnóstico de mieloma múltiplo, que apresentam depósitos no rim de\nproteínas com características de fibrilas amiloide do tipo AL e coradas com vermelho congo. Esses\npacientes apresentam clinicamente com mais frequência:","options":{"A":"acidose tubular renal.","B":"lesão renal aguda.","C":"doença renal crônica.","D":"síndrome nefrótica."},"answer":"C","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-274769","number":"274769","sourceNumber":"274769","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Paciente sexo masculino, 48 anos, dá entrada na unidade hospitalar, conduzido por\nfamiliares, com história de astenia há 5 dias. Ao avaliar paciente no pronto atendimento, o mesmo\nrefere que apresenta febre vespertina há aproximadamente 25 dias, de 38,3°C. Refere não ter\noutros sintomas associados, exceto uma leve odinofagia. Refere ainda que, durante os momentos\nfebris, sente muita dor no corpo, mas fora das crises se sente bem. Paciente não apresenta dados\nrelevantes de antecedentes patológicos. Ao examiná-lo, você percebe um gânglio cervical à direita,\naumentado, levemente doloroso e pouco móvel. Restante do exame físico sem alterações. Sobre o\nraciocínio clínico diante do caso, é imperativo aplicar as evidências diante dos dados descritos. A\nconstrução de hipóteses clínicas segue algumas técnicas sempre com objetivo de buscar a maior\nprobabilidade pré-teste possível da verdade diagnóstica. Diante da apresentação clínica do caso\nanterior e seu contexto descrito, a melhor técnica para construção de hipóteses diagnósticas é:","options":{"A":"construção hipotético dedutiva.","B":"reconhecimento de padrões.","C":"hipótese probabilística.","D":"abordagem sindrômica."},"answer":"D","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-274770","number":"274770","sourceNumber":"274770","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Paciente sexo masculino, 48 anos, dá entrada na unidade hospitalar, conduzido por\nfamiliares, com história de astenia há 5 dias. Ao avaliar paciente no pronto atendimento, o mesmo\nrefere que apresenta febre vespertina há aproximadamente 25 dias, de 38,3°C. Refere não ter\noutros sintomas associados, exceto uma leve odinofagia. Refere ainda que, durante os momentos\nfebris, sente muita dor no corpo, mas fora das crises se sente bem. Paciente não apresenta dados\nrelevantes de antecedentes patológicos. Ao examiná-lo, você percebe um gânglio cervical à direita,\naumentado, levemente doloroso e pouco móvel. Restante do exame físico sem alterações.\n\nAnalisando o contexto clínico descrito, suas respectivas informações e forma de apresentação, a\nhipótese clínica pode melhor ser trabalhada na perspectiva de uma manifestação:","options":{"A":"consumptiva em potencial.","B":"viral.","C":"febril de origem indeterminada.","D":"miastênica."},"answer":"C","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-281279","number":"281279","sourceNumber":"281279","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Assinale a alternativa incorreta em relação às opções terapêuticas para síndrome\nhemofagocítica secundária.","options":{"A":"Protocolo HLH-2004 (8 semanas de quimioterapia).","B":"Imunoglobulina intravenosa.","C":"Diálise peritoneal.","D":"Corticoide."},"answer":"C","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-274816","number":"274816","sourceNumber":"274816","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Linfadenopatia é um achado frequente na atenção primária à saúde, podendo\nrepresentar desde um aumento reacional por\nprocesso infeccioso, até evidência de neoplasia. Com\nrelação às linfadenopatias, marque a alternativa correta.","options":{"A":"Linfonodos normais são papáveis, têm em geral 20 mm de diâmetro, consistência elástica, são\nindolores à palpação e móveis.","B":"A ocorrência de linfadenopatia supraclavicular deve alertar para a possibilidade de patologias\ntorácicas ou abdominais graves.","C":"Existindo a indicação de biopsia do linfonodo, a Punção Aspirativa com Agulha Fina (PAAF) é o\nprocedimento de escolha.","D":"Pacientes com linfadenopatia generalizada devem ser acompanhados de forma expectante por\n3 a 4 semanas, antes de se iniciar\ninvestigação com exames, já que dentro deste período de\nespera a maioria das linfadenopatias se resolvem espontaneamente."},"answer":"D","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-232205","number":"232205","sourceNumber":"232205","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"O distúrbio hipercoagulável genético mais comum associado a alto risco de\ntromboembolia venosa é:","options":{"A":"deficiência de proteína C.","B":"deficiência de proteína S.","C":"deficiência de antitrombina.","D":"deficiência do fator V de Leiden."},"answer":"C","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-254210","number":"254210","sourceNumber":"254210","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Paciente 31 anos, admitido no PA por quadro de febre, astenia e sangramento\n(gengivorragia). Exames laboratoriais revelaram\npancitopenia, alteração de TAP e fibrinogênio.\nEquipe assistente colheu mielograma que revelou presença de 55% de blastos na medula, às\ncustas de promielócitos. Considerando a hipótese diagnóstica provável após os exames, qual a\nopção terapêutica indicada que mudou o prognóstico dos pacientes diagnosticados com essa\ndoença?","options":{"A":"Gentuzumabe.","B":"Rituximabe.","C":"Ácido transretinoico.","D":"Adriamicina."},"answer":"C","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-231938","number":"231938","sourceNumber":"231938","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Uma jovem de 23 anos, hígida, procura a Emergência de devido a \"alergia\" na perna.\nVocê avaliou e viu que apresentava petéquias\nem MMII, com o restante do exame físico normal. A\npaciente nega qualquer tipo de sangramento. Você solicitou um hemograma, e veio o seguinte\nresultado: Hb 12,8g/dL; leucócitos = 6.200/mm³ (diferencial normal); e plaquetas = 26.000/mm³\n(com revisão microscópica). A conduta terapêutica correta mais adequada é:","options":{"A":"transfundir plaquetas","B":"repetir contagem plaquetária no citrato","C":"realizar aspirado de medula óssea","D":"iniciar corticoide","E":"indicar plasmaférese"},"answer":"D","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-234331","number":"234331","sourceNumber":"234331","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Paciente de 65 anos, previamente hígido, refere cefaleias leves há seis meses, que\nvêm se intensificando. Em avaliação com\nclínico geral, notado baço percutível, mas não palpável.\nHemograma mostra hemoglobina de 16,8 g/dl, Ht: 50%, GB: 12.900/ul, com bastões: 06%,\nsegmentados: 68%, eosinófilos: 03%, basófilos: 00%, linfócitos: 20%, monócitos: 03%, plasmócitos:\n\n01%, plaquetas: 500.000/ul. Apresenta DHL: 250 (nl pelo método: 150 - 270), eritropoetina: 1,2\nUI/L. Biópsia de medula óssea mostra\nhipercelularidade evidente, com megacariócitos formando\nagregados, com variação de tamanho e fibras reticulínicas esparsas. Pesquisada mutação JAK2\nexon14: negativa, CALR: negativa, MPL: negativa. Pesquisa de mutação JAK2 exon12: positiva.\nSegundo os critérios diagnósticos das neoplasias hematológicas da Organização Mundial da\nSaúde, de 2016, o diagnóstico é:","options":{"A":"Mielofibrose primária pré-fibrótica.","B":"Policitemia vera.","C":"Trombocitemia essencial.","D":"Mielofibrose primária fibrótica."},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-234332","number":"234332","sourceNumber":"234332","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Paciente de 40 anos, com leucemia mieloide crônica, sem outras comorbidades, com\nausência de resposta molecular maior aos 24 meses, sendo considerada falha ao tratamento com\nimatinibe. Trocado seu tratamento para nilotinibe, 400 mg, duas vezes ao dia, e, após oito meses,\napresenta resposta citogenética completa e resposta molecular completa. Em avaliação periódica\napós três anos de tratamento com nilotinibe, relata dor e frialdade em pé direito. Após avaliação\nclínica e de imagem, detectada doença vascular oclusiva. Nesse caso, qual é a conduta?","options":{"A":"Redução na dose do Nilotinibe para 300 mg, duas vezes ao dia.","B":"Suspensão definitiva do Nilotinibe.","C":"Anticoagulação oral.","D":"Observação e reavaliação em um mês."},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-229541","number":"229541","sourceNumber":"229541","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Qual o PRINCIPAL exame para controle laboratorial no uso de heparina não\nfracionada?","options":{"A":"Tempo de protrombina.","B":"Tempo de tromboplastina parcial ativada.","C":"Hemograma.","D":"Tempo de sangramento."},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-232290","number":"232290","sourceNumber":"232290","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Na criança, a trombocitopenia imune primária:","options":{"A":"É geralmente um distúrbio agudo, autolimitado e imunomediado.","B":"É caracterizada por trombocitopenia (plaquetas menores de 40000/mm³) isolada ou secundária.","C":"Ocorre em 80-85% dos casos na forma persistente.","D":"Ocorre na forma recém-diagnosticada quando a remissão se dá em menos de seis meses."},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-234403","number":"234403","sourceNumber":"234403","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"O acometimento primário do sistema nervoso central por linfoma é, mais\nprovavelmente, do tipo:","options":{"A":"Células B.","B":"Hodgkin.","C":"Kaposi.","D":"Células T."},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-214935","number":"214935","sourceNumber":"214935","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Qual evento está relacionado à deficiência da fase primária da coagulação, que é uma\ndas causas de sangramento genital na\npuberdade:","options":{"A":"diminuição de fibrinogênio","B":"doença de von Willebrand","C":"aumento de antitrombina III","D":"alterações intrínsecas no fator IV"},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-202726","number":"202726","sourceNumber":"202726","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Leia o caso clínico a seguir. Um homem de 68 anos foi internado em unidade de terapia\nintensiva por insuficiência respiratória aguda 72 horas após hemicolectomia. A pressão era de\n100/60 mmHg, a frequencia cardíaca de 120 batimentos por minuto (regular), a frequência\nrespiratória de 28 respirações por minuto e temperatura de 38,1 °C. A análise da gasometria\narterial mostrou PaO? de 63 mmHg e saturação de oxigênio de 84%, com oxigênio suplementar de\n5 L/min. A análise laboratorial mostrou concentração de hemoglobina de 11,0 g/dL, 84% de\nneutrófilos com desvio à esquerda notável, alguns esquizócitos no esfregaço de sangue periférico,\ncreatinina de 2,4 mg/dL e concentração de bilirrubina total de 1,2 mg/dL. O paciente foi intubado e\nventilado, obtendo uma saturação de oxigênio de 98% e estabilizado hemodinamicamente com\ncristaloides e administração intravenosa de vasopressor. Ele foi tratado com antibióticos de amplo\nespectro e contínua profilaxia com heparina subcutânea. Testes de coagulação de rotina\nmostraram uma contagem de plaquetas de 98.000 (152.000 no dia anterior), um tempo de\nprotrombina (TP) de 17 segundos (normal, <12 segundos), o que equivale a uma razão\nnormalizada internacional (INR) de 1,4, tempo de tromboplastina parcial ativada de 43 segundos\n(normal, <28 segundos), concentração de D-dímero de 7,5 µg/mL (normal, <0,5 µg/mL) e\nconcentração de fibrinogênio de 3,5 g/L (normal, 1,3 g/l). O diagnóstico do paciente é:","options":{"A":"púrpura trombocitopênica trombótica.","B":"coagulação intravascular disseminada.","C":"tromboembolismo pulmonar.","D":"trombocitopenia induzida por heparina."},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-201734","number":"201734","sourceNumber":"201734","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Na deficiência do fator XII, há:","options":{"A":"Hemorragias cutâneo-mucosas espontâneas.","B":"Associação com cistos hepáticos.","C":"Micro-hemorragias cerebrais.","D":"Prolongamento do TTPa, sem consequências clínicas."},"answer":"D","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-202721","number":"202721","sourceNumber":"202721","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Leia o caso clínico a seguir. Paciente de 68 anos foi ao cirugião geral para avaliação de\nhérnia inguinal. O médico fez a avaliação e solicitou exames pré-operatórios que demonstraram um\nhemograma com hemoglobina de 13,9 g/dl, plaquetas de 208.000, leucócitos totais de 32800 com\n88% de linfócitos. O hematologista fez um esfregaço de sangue periférico que demonstrava\npredomínio de linfócitos pequenos e alguns raros prolinfócitos, além de manchas de Gumprecht. O\ndiagnóstico do paciente é:","options":{"A":"leucemia linfoide aguda.","B":"mononucleose aguda.","C":"reação leucemoide.","D":"leucemia linfoide crônica."},"answer":"D","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-216476","number":"216476","sourceNumber":"216476","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Marque a alternativa correta:","options":{"A":"A hemofilia é uma doença hemorrágica recessiva ligada ao Y.","B":"A hemofilia B representa 80% dos casos de hemofilia.","C":"A hemofilia se caracteriza clinicamente por eventos recorrentes de tromboembolismo venoso e\narterial.","D":"Os homens apresentam manifestações clínicas da doença, enquanto as mulheres são\nportadoras de um gene mutante e em geral são assintomáticas."},"answer":"D","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-201737","number":"201737","sourceNumber":"201737","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"O linfoma de zona marginal esplênico está associado à infecção com o:","options":{"A":"Helicobacter pylori.","B":"Chlamydophila psittaci.","C":"Vírus da hepatite C.","D":"Campylobacter jejuni."},"answer":"C","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-214190","number":"214190","sourceNumber":"214190","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Homem com 35 anos informa que tem observado o aparecimento de vários linfonodos\nindolores, aumentado de tamanho, na região cervical nos últimos 30 dias, febril (>38 °C), suores\nnoturnos, perda de mais de 10% do peso sem causa aparente, fadiga e prurido. Teve diagnóstico\nde Linfoma de Hodgkin esses sintomas são classificados como","options":{"A":"Sintomas A.","B":"Sintomas B.","C":"Sintomas C.","D":"Sintomas D."},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-178754","number":"178754","sourceNumber":"178754","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Paciente do sexo feminino, 19 anos, portadora de leucemia mieloide aguda em\ntratamento quimioterápico. Apresenta-se no\npronto-atendimento com anemia importante (Hb: 6.2) e\ninforma dois episódios de reação febril não hemolítica. Qual a melhor escolha para a transfusão de\nconcentrado de hemácias nessa paciente?","options":{"A":"Irradiado.","B":"Deleucotizado.","C":"Fenotipado.","D":"Lavado com solução salina.","E":"Convencional."},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-187695","number":"187695","sourceNumber":"187695","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Não é causa de prolongamento do tempo de Protrombina:","options":{"A":"Hipofibrinogenemia.","B":"Doença de Von Willebrand.","C":"Deficiência do fator VII.","D":"Coagulacação intra-vascular disseminada."},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-187715","number":"187715","sourceNumber":"187715","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Para reverter a anticoagulação causada pelo uso da heparina, utilizam-se:","options":{"A":"Infusão de antitrombina III e plasma fresco.","B":"Vitamina K e plasma fresco.","C":"Plasma fresco e sulfato de protamina.","D":"Ácido épsilon aminocapróico e sulfato de protamina."},"answer":"C","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-187531","number":"187531","sourceNumber":"187531","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Com a identificação de gânglio indolor, endurecido e aderido a plano profundo na\nregião supraclavicular esquerda, tem-se o diagnóstico mais provável","options":{"A":"gânglio reacional inespecífico.","B":"lúpus eritematoso sistêmico.","C":"neoplasia.","D":"tuberculose."},"answer":"C","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-173559","number":"173559","sourceNumber":"173559","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Paciente com leucemia mieloide crônica em fase crônica, em uso imatinibe, 400 mg, há\n18 meses. Seu exame de RT-PCR para BCR-ABL\nmostra, na escala internacional, uma\ndeterminação quantitativa de 0,1%. Segundo os critérios do Consórcio Internacional LeukemiaNet,\nsua resposta ao tratamento é:","options":{"A":"Resposta molecular completa.","B":"Resposta molecular maior.","C":"Resposta molecular menor.","D":"Resposta molecular incompleta."},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-173568","number":"173568","sourceNumber":"173568","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Paciente do sexo masculino, de 78 anos, completamente assintomático, com\ndiagnóstico de mieloma múltiplo, com\nhemoglobina de 14 g/dL, leucócitos de 9.000/uL, plaquetas\nde 160.000/uL, cálcio iônico normal, creatinina de 1,0, inventário ósseo normal, mielograma com\n66% de plasmócitos, relação de cadeias Kappa/Lambda (Free Light Chain) de 120,0, proteína M de\n4,0 g/dL. Segundo o International Myeloma Working Group, qual é a conduta indicada?","options":{"A":"Ressonância magnética para completar estadiamento.","B":"Corticoterapia isolada.","C":"Observação e seguimento.","D":"Quimioterapia tripla."},"answer":"D","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-174106","number":"174106","sourceNumber":"174106","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Paciente do sexo masculino, de 32 anos, refere que há três meses iniciou quadro de\nastenia e emagrecimento. Há um mês, febre noturna, icterícia e aumento do volume da região axilar\nesquerda. Ao exame físico, os achados positivos são: ictérico++, hipocorado++,\nhepatoesplenomegalia, massa na região axilar direita de cerca de 6 cm, associada a linfonodos\ninguinais bilaterais. Nega histórico pregresso de doença pessoal ou drogadição. Achados\nlaboratoriais iniciais incluem: Hb = 8,7 g/dl; leucócitos = 3790/mm³, plaquetas = 48.000/mm3; biT =\n\n9.5mg/dl; biD = 8,9 mg/dl; TGO = 192 UI/I; TGP = 1110 UI/I; FA = 2015 UI/I; GGT = 1480 UI/I;\n\nalbumina = 2.2 g/dl; LDH = 936 UI/I. Teste rápido para HIV: positivo. O diagnóstico mais provável\npara o paciente é:","options":{"A":"linfoma de Hodgkin.","B":"doença de Erdheim Chester.","C":"linfoma não Hodgkin.","D":"doença de Kikuchi Fujimoto."},"answer":"C","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-186452","number":"186452","sourceNumber":"186452","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"A doença que se caracteriza por acometer idosos, causar dores ósseas e insuficiência\nrenal, com lesões líticas em radiografias é\na(o):","options":{"A":"Síndrome de Fanconi.","B":"Granulomatose de Wegener.","C":"Mieloma múltiplo.","D":"Doença de Behçet."},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-186502","number":"186502","sourceNumber":"186502","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Entre as anormalidades abaixo, qual NÃO é sugestiva de púrpura trombocitopênica\ntrombótica:","options":{"A":"Aumento dos níveis de lactato-desidrogenase.","B":"Aumento da bilirrubina indireta.","C":"Altas concentrações de haptoglobina.","D":"Plaquetopenia."},"answer":"C","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-178794","number":"178794","sourceNumber":"178794","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Uma criança de 5 anos com quadro de epistaxe, gengivorragia e equimoses em\nmembros inferiores há 3 dias, precedido por\nquadro de resfriado comum, apresenta exame físico\nsem linfonodos palpáveis ou hepatoesplenomegalia. Apresenta ao hemograma plaquetopenia\nisolada de 6.000 plaquetas. Qual é a terapêutica de primeira opção para o quadro?","options":{"A":"Imunoglobulina humana intravenosa.","B":"Ácido tranexâmico.","C":"Ácido aminocaproico.","D":"Transfusão de plaquetas.","E":"Mielograma."},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-183269","number":"183269","sourceNumber":"183269","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Sobre a transfusão de concentrado de hemácias para perdas sanguíneas agudas, é\nINCORRETO afirmar:","options":{"A":"Com hemoglobina menor que 6 g/gL a transfusão geralmente é necessária.","B":"Hemoglobinas entre 6 e 10 g/dL a transfusão é ditada por circunstâncias clínicas.","C":"Perdas sanguíneas rápidas estimadas em 30% exigem transfusão rápida.","D":"Hemoglobinas maiores que 10 g/dL raramente requerem transfusão."},"answer":"C","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-187586","number":"187586","sourceNumber":"187586","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Cirurgião geral é chamado para avaliar criança internada de urgência duas semanas\napós a última sessão de quimioterapia,\napresentando febre, dor abdominal intensa, diarreia e\nhematoquezia. Ao exame, hipocorada, taquicárdia e achado de dor à palpação em fossa ilíaca\ndireita com descompressão brusca duvidosa. A conduta e diagnóstico mais prováveis são:","options":{"A":"Rx de abdome agudo, hemograma, EAS e cirurgia por provável apendicite.","B":"tomografia de abdome, hemograma, EAS e cirurgia por provável apendicite.","C":"tomografia, hemograma, EAS e antibioticoterapia e repouso intestinal por provável tiflite.","D":"tomografia de abdome, hemograma, EAS e cirurgia por provável tiflite."},"answer":"C","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-156970","number":"156970","sourceNumber":"156970","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Qual evento está relacionado à deficiência da fase primária da coagulação, que é uma\ndas causas de sangramento genital na\npuberdade?","options":{"A":"Diminuição de fibrinogênio.","B":"Doença de von Willebrand.","C":"Aumento de antitrombina III.","D":"Alterações intrínsecas no fator IV."},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-160528","number":"160528","sourceNumber":"160528","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Homem de 36 anos é atendido com quadro de anemia há 6 meses, evoluindo, nos\núltimos dias, com emagrecimento, febre,\nepistaxe e hemorragia gengival. O hemograma apresenta\nleucocitose importante e o mielograma revela a presença de células imaturas granulocíticas. O\ndiagnóstico mais provável é:","options":{"A":"Leucemia Linfoide Aguda.","B":"Linfoma Hodgkin.","C":"Linfoma não Hodgkin.","D":"Leucemia Mieloide Aguda."},"answer":"C","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-150224","number":"150224","sourceNumber":"150224","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Paciente de 60 anos, do sexo masculino, em tratamento para leucemia mieloide aguda,\nsubtipo M2. Pesa 64 quilos. Chega no dia 18 de indução da remissão para avaliação ambulatorial.\nEncontra-se assintomático, apresentando hemograma do dia com hemoglobina de 8,0 g/dL,\nleucócitos totais de 400/ul e contagem plaquetária de 15.000/uL. Nesse caso, qual é a conduta\nindicada?","options":{"A":"Transfusão de duas unidades de concentrado de hemácias.","B":"Observação.","C":"Transfusão de duas unidades de concentrado de hemácias e aplicação de Granulokine\nsubcutânea até recuperação de série branca.","D":"Transfusão de uma aférese de plaquetas ou seis unidades de concentrado de plaquetas."},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-150760","number":"150760","sourceNumber":"150760","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Com relação às reações transfusionais:","options":{"A":"As reações ditas leves são desconsideradas pelo NOTIVISA (Sistema de Notificação em\nVigilância Sanitária).","B":"Os sintomas mais comuns na reação febril não hemolítica são tremores, calafrios e febre.","C":"A investigação e notificação da reação transfusional é de responsabilidade exclusiva do banco\nde sangue que distribuiu a unidade\ntransfundida.","D":"O acúmulo de citocinas em concentrados de hemácias é causa de reações do tipo\nincompatibilidade ABO."},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-150229","number":"150229","sourceNumber":"150229","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Qual é a intercorrência mais frequente nos pacientes com leucemia promielocítica\naguda?","options":{"A":"Coagulação intravascular disseminada.","B":"Síndrome ATRA.","C":"Infiltração do sistema nervoso central.","D":"Neutropenia febril."},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-156513","number":"156513","sourceNumber":"156513","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Marque a afirmativa correta:","options":{"A":"Na doença de Willebrand o Fator X da coagulação esta deficiente","B":"A Policitema Vera é também conhecida como síndrome mieloproliferativa ou Doença de\nVasquez.","C":"A Púrpura de Henoch-Schonlein é também conhecida como síndrome do cromossomo 13.","D":"O tratamento do hiperesplenismo é sempre cirúrgico"},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-156534","number":"156534","sourceNumber":"156534","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"São agente bacterianos predominantes nos pacientes pediátricos Oncológicos:","options":{"A":"Pneumocystis formely, Cryptosporidium;","B":"Bordetela pertusis, Ureaplasma urealítico","C":"Micoplasma, Epstein-Barr","D":"Staphylococcus species, Enterobactérias"},"answer":"D","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-160536","number":"160536","sourceNumber":"160536","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Augusto, 7 anos, portador de síndrome de Down, é levado à Unidade de Pronto\nAtendimento (UPA) com quadro de astenia,\nmialgia e febre intermitente de 38ºC há três dias. No\nexame físico apresenta o seguinte quadro: hipocorado ++/4+, febril (38,2ºC), acianótico, ausculta\nrespiratória com MV fisiológico, sem RA, FR: 26 irpm, ACV: BNF, 2T, presença de sopro sistólico\n\n++/4+, FC: 110 bpm. No abdome, presença de fígado a 3 cm RCD, ponta de baço palpável RCE.\nEncontrados também gânglios inguinais, auxiliares e cervicais palpáveis bilateralmente. Foi\nsolicitado hemograma de urgência com o seguinte resultado: Ht 28/ Hb 7,5/ 80.000 leucócitos/ 4000\nneutrófilos/ 82.000 linfócitos, sendo 80% de blastos, 100.000 plaquetas. Qual exame complementar\ndeve ser solicitado no próximo passo, para elucidação do diagnóstico neste caso?","options":{"A":"Ultrassonografia abdominal.","B":"Mielograma.","C":"Provas inflamatórias.","D":"Sorologias."},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-128003","number":"128003","sourceNumber":"128003","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"O paciente é um homem de 58 anos que está internado em um hospital geral, para uma\ncirurgia de hérnia inguinal. Encontra-se em bom estado geral. O exame físico é normal, exceto por\nalguns nódulos em região cervical, 1 x 1 cm, indolores, não aderidos a planos profundos. O Ht é\n42%; plaquetas = 335.000/mm; leucócitos = 50.000/mm³; granulócitos = 4%; monócitos = 1%;\nlinfócitos = 95%. Marque a alternativa com a hipótese diagnóstica mais provável para o caso\ndescrito acima:","options":{"A":"Leucemia Linfocítica Crônica (LLC).","B":"Leucemia Mieloide Crônica (LMC).","C":"Leucemia Linfocítica Aguda (LLA).","D":"Leucemia Mieloide Aguda (LMA)."},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-136876","number":"136876","sourceNumber":"136876","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"O Mieloma Múltiplo (MM) é uma neoplasia hematológica caracterizada pela proliferação\nclonal de plasmócitos malignos no\nmicroambiente de medula óssea associado ao surgimento de\nproteína monoclonal sérica e/ou urinária e presença de disfunção de órgãos-alvo. Sobre o MM,\nsabe-se que:","options":{"A":"a doença óssea no MM consiste em lesões líticas em saca-bocado, osteopenia ou fraturas e o\nmétodo padrão para diagnosticar essas lesões é a ressonância nuclear magnética.","B":"para o diagnóstico de MM é necessário apenas a presença da proteína monoclonal sérica e/ou\nurinária.","C":"a eletroforese de proteínas é um estudo fundamental para detecção da proteína monoclonal no\nsoro ou na urina e a ausência de pico monoclonal não exclui o diagnóstico.","D":"o MM é precedido por uma fase de gamopatia monoclonal de significado indeterminado (GMSI)\nou de mieloma assintomático, na qual já\ndeve ser instituído tratamento quimioterápico de forma a\nprevenir evolução da doença."},"answer":"C","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-127711","number":"127711","sourceNumber":"127711","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Considerando a mielofibrose primária, qual situação está relacionada a um melhor\ncomportamento clínico e prognóstico?","options":{"A":"Mutação JAK2.","B":"Mutação na região CARL.","C":"Mutação MPL.","D":"Presença da proteína de fusão BCR-ABL."},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-129885","number":"129885","sourceNumber":"129885","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Paciente, de 18 anos, do sexo masculino, é admitido no pronto-socorro com queixa de\nfebre aferida há duas horas de 39°C. Nega dispneia, disúria, diarreia, otalgia ou qualquer outro\nsintoma infeccioso. Ao exame físico, apresenta-se levemente taquicárdico, sem hipotensão arterial,\ntaquipneia ou qualquer outra alteração na avaliação do aparelho cardiovascular e respiratório ou no\nexame abdominal. Revela ao médico estar em tratamento quimioterápico, fase de indução, para\nleucemia mieloide aguda diagnosticada há 20 dias. O hemograma solicitado na urgência revela:\nhemoglobina = 7,5 mg/dl; leucócitos totais = 500/mm³; neutrófilos = 100/mm³; linfócitos = 400/mm³;\nplaquetas = 25.000/mm³. Qual conduta deve ser estabelecida?","options":{"A":"Liberar o paciente e solicitar seu retorno em caso de aparecimento de qualquer sintoma\ninfeccioso.","B":"Iniciar antibiótico oral (levofloxacino ou amoxicilina + clavulanato + ciprofloxacino), colher\nculturas, solicitar radiografia de tórax e reavaliar em 48 horas.","C":"Encaminhar para avaliação ambulatorial do especialista.","D":"Iniciar imediatamente antibiótico endovenoso (cefepima, piperacilina + tazobactam ou\nmeropenem), colher hemoculturas e realizar radiografia de tórax."},"answer":"D","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-109164","number":"109164","sourceNumber":"109164","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Paciente de 70 anos inicia sintoma de dor lombar agravada à noite, cansaço, perda de\n15 kg em três meses e parestesia em luva e\nem bota. Ao exame físico, encontra-se emagrecido,\ncom palidez em mucosas e hiperpigmentação cutânea generalizada. Linfonodos cervicais, axilares\ne inguinais bilateralmente aumentados, além de hepatoesplenomegalia homogênea. Exames\nlaboratoriais mostram: hematócrito de 25% com VCM de 87 fl; proteínas totais: 9,5 g/dl; globulinas:\n7,0 g/dl; creatinina: 2,5 mg/dl; cálcio: 10,4 mg/dl; VHS: 112 mm/H e aumento monoclonal de IgC na\neletroforese de proteínas. O diagnóstico mais provável é:","options":{"A":"Leucemia linfoide crônica.","B":"Síndrome POEMS.","C":"Hemocromatose.","D":"Amiloidose."},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-110236","number":"110236","sourceNumber":"110236","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"As leucemias na infância e na adolescência são classificadas em LLA (Leucemia\nLinfoide Aguda), LMA (Leucemia Mieloide Aguda) e\nLMC (Leucemia Mieloide Crônica). Sobre este\ntipo de câncer, na infância, tem-se que:","options":{"A":"O diagnóstico diferencial entre as formas LLA e LMA pode ser feito pela análise do hemograma,\nque revela leucocitose na primeira e leucopenia\nna segunda.","B":"Dor óssea, linfonodomegalia e hepatoesplenomegalia são muito comuns na LLA, a forma mais\ncomum na infância.","C":"A forma mais prevalente na infância é a LMA, que tem um pico de incidência na fase etária\npré-escolar e escolar.","D":"Paciente com aumento plaquetário e ausência de esplenomegalia são características da LMC, a\nforma mais prevalente na infância."},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-101167","number":"101167","sourceNumber":"101167","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Paciente com leucemia mieloide crônica em uso de imatinibe, 400 mg/dia. No terceiro\nmês de tratamento apresenta Hb: 9,0 g/dl;\nGB: 12.300, com 1% de mielócitos, 2% de\nmetamielócitos, 18% de bastões, 40% de segmentados, 2% de eosinófilos, 2% de basófilos, 35%\nde linfócitos, 10% de monócitos e 450.000/ul de plaquetas. Baço não palpável, com traube\nocupado. No caso desse paciente, qual é a conduta indicada?","options":{"A":"Manter imatinibe 400 mg/dia e agendar retorno em três meses.","B":"Manter imatinibe 400 mg/dia e agendar retorno em um mês para checar aderência.","C":"Elevar a dose de imatinibe para 600 mg/dia.","D":"Trocar imatinibe para inibidor de tirosina quinase de segunda geração (dasatinibe ou\nnilotinibe)."},"answer":"D","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-109381","number":"109381","sourceNumber":"109381","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"A leucemia mielocítica aguda é responsável por cerca de 11% dos casos de leucemia\nnos EUA. A infiltração gengival (hipertrofia\ngengival) é mais observada, dentre os subtipos, no\nseguinte:","options":{"A":"M1.","B":"M2.","C":"M3.","D":"M4."},"answer":"D","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-83677","number":"83677","sourceNumber":"83677","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"São procedimentos necessários para o estadiamento de linfoma de Hodgkin:","options":{"A":"Biópsia de medula óssea e imunofenotipagem de sangue periférico.","B":"Biópsia de gânglio linfático e cariótipo banda G.","C":"Hemograma e mielograma.","D":"Anamnese e exame físico detalhados.","E":"Tomografia computadorizada (tórax e abdome total) e eletroforese de imunoglobulinas séricas."},"answer":"D","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-78072","number":"78072","sourceNumber":"78072","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Qual dos critérios abaixo é um critério menor para o diagnóstico (OMS 2008) de\npolicitemia vera?","options":{"A":"Vitamina B12 baixa.","B":"Eritropoetina baixa.","C":"Reação leucoeritroblástica.","D":"Cromossomo Philadelphia positivo."},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-78082","number":"78082","sourceNumber":"78082","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"No diagnóstico de mieloma múltiplo, todos os critérios de lesão de órgão-alvo\nenglobam-se em:","options":{"A":"plasmócitos > 10% em medula óssea e pico monoclonal > 3,0 g/dl.","B":"anemia, hipoalbuminemia, pico monoclonal.","C":"anemia, creatinina acima de 2,0, hipercalcemia, lesões osteolíticas.","D":"anemia, aumento de DHL, hipercalcemia e pico monoclonal > 3,0 g/dl."},"answer":"C","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-61734","number":"61734","sourceNumber":"61734","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Um contador de 44 anos de idade vem visitá-lo tendo sido diagnosticado,\nrecentemente, leucemia linfocítica crônica. Ele\npesquisou sua doença na internet e leu que\nnormalmente acontece nos idosos, com idade média de 72 anos. Quais dos seguintes fatores na\nsua história pregressa e antecedentes possivelmente podem ter contribuído para o seu diagnóstico\nnuma idade tão precoce?","options":{"A":"Ele trabalhava numa área de exposição à energia nuclear.","B":"Ele tinha uma infecção crônica por Epstein-Barr vírus três anos atrás.","C":"Ele foi tratado com methotrexate para doença inflamatória intestinal quatro anos atrás.","D":"Sua mãe morreu de linfoma não Hodgkin."},"answer":"D","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-62708","number":"62708","sourceNumber":"62708","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Um paciente de 70 anos apresentou alterações em eletroforese de proteínas e foi\nencaminhado para avaliação. Sem queixas ou alterações ao exame físico. Apresenta hemograma\ncom Hb:13,0, GB: 6.000/ul e plaquetas de 150.000/ul. Eletroforese de proteínas com albumina de\n4,0 g/dl, gamaglobulinas de 3,5 g/dl, com pico monoclonal IgG/Kappa, cálcio sérico normal,\ncreatinina de 1,5, glicemia de 135,0. Inventário ósseo mostra osteopenia leve. Mielograma mostra\ninfiltração por 15% de plasmócitos anaplásicos. O diagnóstico, nesse caso, é:","options":{"A":"Síndrome de POEMS.","B":"Mieloma múltiplo indolente.","C":"Mieloma múltiplo sintomático.","D":"Pico monoclonal de significado indeterminado."},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-62740","number":"62740","sourceNumber":"62740","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Paciente de 59 anos relata emagrecimento de 15 quilos em oito meses e desconforto\nabdominal, com dores em hipocôndrio\nesquerdo. Ao exame, está descorado, leve, emagrecido,\nsem adenomegalias e baço a 5 cm do rebordo costal esquerdo. Hemograma com Hb: 8,0 g/dl, GB:\n22.000/uL, com blastos: 00%, promielócitos: 00%, mielócitos: 03%, metamielócitos: 02%, bastões:\n\n14%, segmentados: 60%, eosinófilos: 01%, basófilos: 00%, linfócitos: 17%, monócitos: 03%,\nplaquetas: 450.000/uL, eritroblastos 10/100 GB.\nMielograma mostrou-se inconclusivo. Análise\nmolecular mostra PCR para BCR-ABL negativo, PCR para mutação JAK2 negativa. Cariótipo em\nandamento. Com base nesses dados, qual é o diagnóstico?","options":{"A":"Mielofibrose primária.","B":"Leucemia mieloide crônica.","C":"Linfoma esplênico.","D":"Trombocitemia essencial."},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-63215","number":"63215","sourceNumber":"63215","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Em relação às leucemias, é correto afirmar:","options":{"A":"As leucemias mieloides agudas correspondem a 50% das leucemias na infância.","B":"O pico de incidência da leucemia linfoide aguda ocorre em menores de 1 ano e em\nadolescentes.","C":"Hipertrofia gengival, coagulação intravascular disseminada e cloromas são manifestações\nclínicas mais frequentes na leucemia linfoide aguda.","D":"As translocações t (4;11) e t (9;22) estão relacionadas ao melhor prognóstico nas leucemias\nlinfoides agudas.","E":"A neutropenia febril é uma complicação frequente do tratamento quimioterápico das leucemias,\nsendo necessária intervenção rápida com início\nde antibioticoterapia endovenosa."},"answer":"E","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-61841","number":"61841","sourceNumber":"61841","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Um paciente de 60 anos, masculino, é internado para investigação de síndrome\nconsumptiva e quadro de paraparesia de\nmembros inferiores. Ausência de linfonodomegalias ao\nexame físico. Nos exames de investigação: Hb: 9.0 g/dl; Ht: 27%, sem outras anormalidades no\nhemograma; cálcio: 11,4 mg/dl; fósforo: 4,5 mg/dl; ureia: 67 mg/dl; creatinina: 3,4 mg/dl;\nsorologias\npara HIV e hepatites negativas. TC de tórax revelou lesões ósseas líticas em costelas. TC de\nabdome normal, RN de coluna evidenciou lesão expansiva em nível de L4-L5. Qual conduta será\ncapaz de definir a principal hipótese diagnóstica deste paciente?","options":{"A":"Punção liquórica.","B":"Cintilografia de paratireoides.","C":"Avaliação prostática.","D":"Mielograma.","E":"Cintilografia óssea."},"answer":"D","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-47305","number":"47305","sourceNumber":"47305","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Um paciente com mieloma múltiplo, em tratamento quimioterápico, apresenta trombose\nvenosa profunda recente em veia femoral\ndireita. O quadro sugere efeito do uso de:","options":{"A":"bortezomibe","B":"ácido zoledrônico","C":"ciclofosfamida","D":"talidomida"},"answer":"D","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-47782","number":"47782","sourceNumber":"47782","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"As leucemias agudas são patologias graves, que acometem todas as faixas etárias e\nque exigem encaminhamento para centros\nespecializados em seu tratamento. Nas leucemias\nagudas:","options":{"A":"O diagnóstico é descartado em um paciente com 21% de blastos na medula óssea, mas sem\nblastos no sangue periférico.","B":"O subtipo mieloide é mais comum em crianças e o subtipo linfoide é mais comum em adultos.","C":"A presença de manifestações leves pode ocorrer por semanas a meses, antes que o paciente\nreceba o diagnóstico.","D":"A incidência na população é similar em indivíduos que já tenham sido submetidos ou não à\nquimioterapia."},"answer":"C","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-51020","number":"51020","sourceNumber":"51020","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Um menino de 5 anos de idade com história de febres e fadiga há um mês mostra\nanemia severa, trombocitopenia moderada e\n12.000 leucócitos/mm³. Uma biópsia de medula óssea\nrevelará mais provavelmente qual das enfermidades listadas abaixo?","options":{"A":"leucemia linfoblástica aguda.","B":"leucemia mieloblástica aguda.","C":"leucemia linfocítica crônica.","D":"leucemia mieloide crônica.","E":"leucemia de células pilosas."},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-48858","number":"48858","sourceNumber":"48858","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Assinale a alternativa correta em relação à doença mais subjacente à amiloidose\nsistêmica.","options":{"A":"Leucemia linfoide crônica.","B":"Adenocarcinoma de cólon.","C":"Linfoma de células B.","D":"Mieloma múltiplo.","E":"Carcinoma broncogênico."},"answer":"D","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-35620","number":"35620","sourceNumber":"35620","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Mulher de 68 anos apresenta astenia e dor lombar há 8 meses. Na última semana,\nhouve queda do estado geral, obstipação, dor\nabdominal e vômito. A paciente apresenta-se\ndesidratada e com confusão mental. Os exames laboratoriais mostram lesões líticas nas vértebras\nlombares, anemia, elevação dos níveis séricos de creatinina, cálcio, ácido úrico e globulinas. A\nfosfatase alcalina é normal. O exame que confirmará a principal hipótese diagnosticada é:","options":{"A":"Dosagem do paratormônio.","B":"Mamografia.","C":"Cintilografia óssea.","D":"Bioquímica do liquor.","E":"Mielograma."},"answer":"E","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-34008","number":"34008","sourceNumber":"34008","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Na doença óssea em mieloma múltiplo:","options":{"A":"A superexpressão de RANK-L pelos plasmócitos neoplásicos sobrepuja a capacidade inibitória\nda osteoprotegerina e promove, assim, aumento da\natividade dos osteoblastos.","B":"Os inibidores da osteólise bloqueiam a progressão\n\ndas fraturas patológicas, dores ósseas e hipercalcemia em até 70%.","C":"O exame mais sensível para lesões osteolíticas é o PET/PET-CT.","D":"A infusão endovenosa mensal de inibidores da osteólise é recomendada por três anos, pois,\nalém deste limite, seu uso está associado à osteonecrose de mandíbula."},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-34074","number":"34074","sourceNumber":"34074","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Criança com seis anos de idade, há um mês vem apresentando febre, dor nos\nmembros inferiores associada à palidez\ncutâneo-mucosa. Realizou hemograma e mielograma com\ndiagnóstico de leucemia linfoide aguda. Na leucemia linfoide aguda:","options":{"A":"A presença de tumores em tecidos moles, chamados de cloromas, constitui um dos indicadores.","B":"As manifestações osteoarticulares são raras e, quando presentes, fazem diagnóstico diferencial\ncom artrite reumatoide juvenil e febre\nreumática.","C":"Os sintomas iniciais comuns incluem febre, palidez (anemia) e sinais de sangramento (petéquias\ne equimoses).","D":"A dor osteoarticular, na maioria das vezes, cede com repouso e anti-inflamatórios não\nhormonais."},"answer":"C","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-8943","number":"8943","sourceNumber":"8943","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Paciente de 75 anos, masculino, assintomático em consulta de rotina, apresentou-se,\nao exame físico, com discretas adenomegalias\ncervicais, axilares e inguinais, além de\nesplenomegalia, também discreta. Sem outras alterações no exame físico. Trata-se de paciente\nhígido que ainda executa trabalhos rurais leves. Durante a avaliação laboratorial, observou-se, em\nhemogramas seriados durante cinco meses, linfocitose (linfócitos > 15.000 com predomínio de\nlinfócitos pequenos e maduros) e plaquetopenia (plaquetas < 100.000) persistentes, além de\nanemia leve. A definição diagnóstica neste caso é dada por:","options":{"A":"imunofenotipagem do sangue periférico","B":"Citogenética","C":"Teste terapêutico com corticoide","D":"Pesquisa de anticorpo anticardiolipina (IgG e IgM) e anticoagulante lúpico"},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-16202","number":"16202","sourceNumber":"16202","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Sobre leucemia linfoide aguda (LLA), pode-se dizer que:","options":{"A":"As artrites são frequentes.","B":"É uma doença clonal aguda.","C":"A perda de peso é acentuada.","D":"As dores ósseas são raras."},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-274016","number":"274016","sourceNumber":"274016","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Pré-escolar do sexo masculino, deu entrada em pronto-atendimento com história de\nfebre há 10 dias, de caráter intermitente,\ncom artralgias em membros inferiores, adinamia e com\naparecimento de equimoses em membros e parede abdominal. Ao exame físico, apresenta palidez\ne hepatoesplenomegalia. Fez hemograma, que evidenciou pancitopenia. O diagnóstico MAIS\nPROVÁVEL é:","options":{"A":"Leucemia aguda.","B":"Calazar.","C":"Mononucleose infecciosa.","D":"Artrite reumatoide juvenil."},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-274019","number":"274019","sourceNumber":"274019","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"A Linfo-histiocitose ou síndrome hemofagocítica é uma desordem inflamatória com\nfagocitose de elementos sanguíneos, onde o macrófago, promove uma cascata inflamatória de\nforma desregulada, provocado secundariamente a uma série de agentes etiológicos. Selecione a\nopção correta, sobre o agente infeccioso mais comum da síndrome hemofagocítica secundária.","options":{"A":"Vírus da dengue.","B":"Leishmania sp.","C":"Citomegalovírus.","D":"Vírus Epstein Barr."},"answer":"D","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-250215","number":"250215","sourceNumber":"250215","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"O crioprecipitado contém todos os fatores de coagulação, EXCETO:","options":{"A":"Fator XIII.","B":"Fator de Von Willebrand.","C":"Fator IX.","D":"Fator VIII."},"answer":"C","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-250232","number":"250232","sourceNumber":"250232","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Homem de 65 anos, diagnóstico prévio de insuficiência cardíaca congestiva (fração de\nejeção: 35%), internada devido perda de peso (10 kg/6 meses), anemia e dor lombar. Apresenta os\nseguintes exames: Hb: 8g/dL, hematócrito: 24 %, Cr: 3 mg/dL, Ur: 100 mg/dL, AST: 45 U/L, ALT: 38\nU/L. À radiografia de coluna lombar: osteopenia difusa e fraturas parciais de L3 e L4 por\nencunhamento. Após 3 dias de internação, teve dor abdominal importante e anúria, laboratório com\ncálcio total: 17 mg/dL e albumina: 3,2 g/dL. Sobre o caso clínico, assinale a alternativa CORRETA:","options":{"A":"Eletroforese de proteínas séricas e urinárias, mielograma e biópsia de medula óssea podem\najudar a esclarecer o diagnóstico hematológico.","B":"A conduta mais adequada para a hipercalcemia deste paciente é a hidratação vigorosa.","C":"8% de plasmócitos na medula óssea confirma a principal hipótese diagnóstica.","D":"A etiologia mais provável da hipercalcemia em questão é o uso de diurético tiazídico."},"answer":"D","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-216423","number":"216423","sourceNumber":"216423","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Em relação à síndrome hemofagocítica, é correto afirmar, EXCETO:","options":{"A":"A presença de hemofagocitose no aspirado ou biópsia de medula óssea é a condição obrigatória\npara concluir o diagnóstico.","B":"São critérios diagnósticos: febre, esplenomegalia, citopenias afetando duas ou mais séries,\nhipertrigliceridemia, hipofibrinogenemia, entre outros.","C":"São etiologias comuns na forma secundária da doença: infecção por vírus Epstein-Barr, calazar,\nneoplasias hematológicas e colagenoses.","D":"Nível sérico de ferritina superior a 10.000 ng/mL tem alta especificidade para o diagnóstico,\nalém\nde ser importante marcador de atividade da doença, resposta terapêutica e prognóstico."},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-216203","number":"216203","sourceNumber":"216203","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Esplenomegalia e pancitopenia, associadas a um aspirado de medula óssea \"seco\"\nsuscitam como PRINCIPAL hipótese:","options":{"A":"Mielodisplasia.","B":"Leucemia de células pilosas.","C":"Anemia hemolítica extravascular.","D":"Anemia aplásica."},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-176220","number":"176220","sourceNumber":"176220","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Sobre a trombocitopenia induzida por heparina (TIH) é correto afirmar, EXCETO:","options":{"A":"Afeta em torno de 3% dos pacientes expostos à heparina não-fracionada e uma porcentagem\nmenor de pacientes expostos à heparina de\nbaixo peso molecular.","B":"Na apresentação típica, o quadro ocorre após um mínimo de 5 dias de exposição à heparina e\nocorre um declínio maior ou igual a 50% da contagem basal de plaquetas.","C":"Embora os casos sejam geralmente assintomáticos, tromboses arteriais e/ou venosas podem\nser detectadas na maioria dos pacientes até cerca\nde 30 dias após o diagnóstico.","D":"Quando se suspeita de TIH tipo II, deve-se imediatamente suspender a administração de\nheparina e substituí-la por um anticoagulante alternativo. Uma dessas alternativas atualmente\nestudadas é o Fondaparinux.","E":"A transfusão de plaquetas está indicada na maioria das vezes e deve ser iniciada de forma\nprofilática e\n\nprecoce, mesmo sem sangramento aparente e com plaquetas ainda acima de 50.000/mm3, pois\ngeralmente ocorre uma nova queda muito rápida nos dias subsequentes ao início do quadro."},"answer":"E","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-176236","number":"176236","sourceNumber":"176236","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Paciente do sexo masculino com 59 anos de idade, com histórico de dor lombar\npersistente e anemia normocítica e\nnormocrômica, foi submetido à TC de coluna lombar que\nmostrou diversas lesões líticas em segmentos torácicos e lombossacrais. A eletroforese de\nproteínas séricas revelou pico monoclonal nas gamaglobulinas, mais especificamente de IgG. A\nbiópsia de medula óssea revelou 12% de plasmócitos clonais. O paciente nega dispneia, mesmo\naos esforços, e tem ecocardiograma normal. O TRATAMENTO DE ESCOLHA nessa situação é:","options":{"A":"Quimioterapia isolada com melfalan.","B":"Quimioterapia isolada com lenalidomida.","C":"Transplante autólogo de medula óssea.","D":"Apenas controle de sintomas e complicações da doença de base.","E":"Plasmaféreses de repetição."},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-155297","number":"155297","sourceNumber":"155297","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Paciente sexo feminino, 35 anos de idade, com diagnóstico de hepatopatia crônica\nconsequente à Síndrome de Budd-Chiari. Na\ninvestigação etiológica, a paciente pode ser portadora\nde uma das seguintes doenças subjacentes, EXCETO:","options":{"A":"Hemoglobinúria paroxística noturna.","B":"Deficiência de homocisteína.","C":"Policitemia vera.","D":"Mutação do fator V de Leiden.","E":"Neoplasia."},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-131874","number":"131874","sourceNumber":"131874","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Menina de 5 anos de idade apresentando febre baixa intermitente, dor em membros\ninferiores, palidez, dor articular, epistaxe leve e dificuldade para deambular há 4 semanas. Ao\nexame físico, evidenciam-se equimoses em membros, petéquias disseminadas, mucosas\nhipocoradas, linfadenomegalia cervical e inguinal e hepatoesplenomegalia. Qual exame é\nimportante como investigação inicial?","options":{"A":"Coagulograma.","B":"Coombs direto e indireto.","C":"Pesquisa de anticorpo antiplaquetário.","D":"Hemograma.","E":"Fator reumatoide."},"answer":"D","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-105713","number":"105713","sourceNumber":"105713","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Adolescente de 15 anos apresenta, há 3 semanas, febre alta, adinamia, equimoses em\nmembros inferiores, hemoglobina 10 g/dl, leucócitos 50.000/mm³, neutrófilos 5.000/mm³, presença\nde blastos e plaquetas 35.000/mm³. Qual o exame importante para o diagnóstico?","options":{"A":"Coombs direto e indireto.","B":"Mielograma.","C":"Biópsia de medula óssea.","D":"Coagulograma.","E":"Eletroforese de hemoglobina."},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-62595","number":"62595","sourceNumber":"62595","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Mulher, 29 anos, iniciou quadro de confusão mental e equimoses há 3 dias, com\ndiminuição do volume urinário. Ao exame,\napresenta-se em regular estado geral; sonolenta;\npressão arterial = 120 x 80 mmHg; pulso = 80 bpm; frequência respiratória = 18 irpm. Equimoses\nem MMSS e MMII. Hemoglobina = 6,5 g/dl; VCM = 100 fl; reticulócitos = 28%; 12.000\nleucócitos/mm³; 80 bastões/mm³ (6,7%); 9.000 neutrófilos/mm³; 1.800 linfócitos/mm³; 65.000\nplaquetas/mm³. Esfregaço de sangue demonstra fragmentação das hemácias e policromasia. Qual\né a conduta terapêutica indicada?","options":{"A":"Plasmaférese.","B":"Esplenectomia.","C":"Ciclosporina.","D":"Transfusão de plaquetas.","E":"Pulsoterapia com ciclofosfamida."},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-28232","number":"28232","sourceNumber":"28232","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Menino de 04 anos, ativo em bom estado geral, apresenta febre há três dias. Fígado a\n3 cm do rebordo costal direito. Exames\ncomplementares: Hemograma - Htc 33%; Hb 11,5;\nLeucócitos 5.800/mm³ com 70% de eosinófilos. Proteinograma normal. Parasitológico de fezes\nnegativo. A hipótese diagnóstica mais provável é:","options":{"A":"Ascaridíase","B":"Toxocaríase","C":"Abscesso hepático amebiano","D":"Eosinofilia tropical","E":"Leucemia eosinofílica"},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-11433","number":"11433","sourceNumber":"11433","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Em relação à regulação da resposta imune pelas células T, analise nas afirmativas a\nseguir: I. Células T migram da medula óssea para o timo, onde começam a expressar receptores\npara antígenos, sendo que, a maioria destes receptores tem duas cadeias, ? e ?, e são chamados\nreceptores ?/?; II. Como uma consequência da seleção dentro do timo, algumas células T que têm\navidez intermediária para autoantígenos entram na periferia, onde têm potencial para se\ntransformarem em células efetoras patogênicas; III. Quando CD80 e CD86, duas proteínas de\nsuperfície de células B e células dendríticas, interagem com a molécula CD28 na superfície das\ncélulas T, ocorre anergia ou tolerância imune, enquanto que a interação com CTLA-4 (?cytotoxic T -\nlymphocyt-associated antigen 4?) provoca ativação destas células; Analise:","options":{"A":"Se todas as afirmativas estiverem corretas.","B":"Se somente as afirmativas I e III estiverem corretas.","C":"Se somente as afirmativas I e II estiverem corretas.","D":"Se somente as afirmativas II e III estiverem corretas.","E":"Se nenhuma afirmativa estiver correta."},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-281461","number":"281461","sourceNumber":"281461","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"A chance de adquirir HIV em uma transfusão de fator VIII nos EUA é zero, pela\nseguinte justificativa:","options":{"A":"Todos os doadores do fator VIII são rastreados.","B":"O fator VIII é submetida ao processo de \"\"purging\"\" a laser antes da liberação.","C":"O fator VIII é produzido sinteticamente.","D":"O fator VII é produzido sob demanda.","E":"O fator VIII é importado nos EUA."},"answer":"C","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-263720","number":"263720","sourceNumber":"263720","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Adolescente de 15 anos de idade apresenta adenomegalia cervical unilateral há 6\nmeses e com crescimento progressivo; nos\núltimos 2 meses cursa com febre diária, perda de peso\ne sudorese. Qual diagnóstico mais provável?","options":{"A":"Linfoma de Burkitt.","B":"Neuroblastoma.","C":"Carcinoma de tireoide.","D":"Linfoma de Hodgkin.","E":"Carcinoma de glândulas salivares."},"answer":"D","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-278969","number":"278969","sourceNumber":"278969","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Qual é a causa mais frequente de linfadenomegalia na infância?","options":{"A":"Linfoma de Hodgkin","B":"Tuberculose","C":"Hiperplasia reacional","D":"Doença da arranhadura do gato","E":"Toxoplasmose adquirida"},"answer":"C","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-244709","number":"244709","sourceNumber":"244709","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"A síndrome da lise tumoral que pode ocorrer no tratamento de algumas doenças\nonco-hematológicas com grande significado em pediatria, tem como alterações metabólicas\nclássicas:","options":{"A":"Hiperuricemia ? hipocalemia ? hipercalcemia.","B":"Hipocalcemia ? hipofosfatemia ? hiperuricemia.","C":"Hipercalcemia ? hipercalemia ? hipofosfatemia.","D":"Hiperuricemia ? hipercalemia ? hiperfosfatemia.","E":"Hiperuricemia ? hipocalemia ? hipercalcemia."},"answer":"D","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-252447","number":"252447","sourceNumber":"252447","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Criança de três anos, sexo masculino, internada em um hospital municipal,\ndiagnosticada recentemente com Leucemia Linfoide Aguda,\naguardando transferência para\nHospital especializado em Oncologia Pediátrica, evoluindo com desconforto respiratório, queda\nrepentina dos leucócitos de 100.000 mm³ para 13.000 mm³. O médico que estava de plantão\ndesconfiou da hipótese diagnóstica de síndrome de lise tumoral. Quais exames laboratoriais\ndeveria solicitar para diagnosticar a provável Síndrome de Lise Tumoral?","options":{"A":"Solicitar estudo genético para avaliar presença de cromossomo Filadélfia","B":"Solicitar novo mielograma com imunofenotipagem.","C":"Potássio sérico, cálcio sérico, fósforo sérico e ácido úrico.","D":"Solicitar Petscan","E":"Solicitar triglicérides, ferritina, dhl e fibrinogênio"},"answer":"C","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-203314","number":"203314","sourceNumber":"203314","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Analise, nos itens abaixo, o que se considera indicação de Esplenectomia e, em\nseguida, escolha a opção correta: I. Hiperesplenismo por doença autoimune; II. Traumatismo de\nbaço grau II; III. Lesão incidental;","options":{"A":"Somente I está correto","B":"Somente II está correto","C":"Todos estão corretos","D":"Somente II e III estão corretos","E":"Somente I e III estão corretos"},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-203205","number":"203205","sourceNumber":"203205","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"As doenças linfoproliferativas pró-transplante (PTLD ? do inglês Post-Transplant\nLymphoproliferative Disorders) podem representar uma\ncomplicação grave da imunossupressão. O\npatógeno que está intimamente ligado à indução da patologia em destaque é:","options":{"A":"Herpes vírus humano tipo 6.","B":"Vírus Epstein-Barr.","C":"CMV.","D":"Vírus varicela-zóster.","E":"HIV."},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-184835","number":"184835","sourceNumber":"184835","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Paciente, 30 anos do sexo feminino, com história há 1semana de febre diária, Tax 38,5\na 39,0°C.mal estar, cefaleia, confusão mental e\nhemiparesia a direita. Petéquias nos membros\ninferiores. Foi internada para investigação. No tercceiro dia de internação o quadro se agravou com\nepisódios de convulsão, oligúria, sedimento urinário com hematúria/proteinúria, ureia de 110 mg/dl,\ncreatinina de 1,9mg/dl, anemia: Hb 7,0 g/dl e Htc 25%, plaquetas 60.000 cel/mm³, aumento de\nbilirrubina indireta; Coombs direto negativo. Foi solicitado avaliação da hematologia, que observou\na presença de hemácias descritas como \"esquizócitos no sangue periférico\"da paciente. Qual a\nhipótese diagnóstica mais provável para a situação clínica acima apresentada?","options":{"A":"Dengue hemorrágica","B":"Síndrome hemolítica urêmica","C":"Síndrome hemofagocítica","D":"Síndrome antifosfolipides","E":"Púrpura trombocitopênica trombótica"},"answer":"E","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-175057","number":"175057","sourceNumber":"175057","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Paciente feminina, 22 anos, procura o ambulatório de clínica médica de um hospital de\nreferência queixando-se de febre vespertina, perda ponderal não quantificada, sudorese noturna e\naumento do volume cervical há 6 meses. Ao exame notava-se adenomegalias cervicais e\nsupraclaviculares à direita, indolores e endurecidas. Sem evidência de visceromegalias.\n\nApresentava hemograma normal e alargamento de mediastino na radiografia de tórax. Qual a\nprincipal hipótese diagnóstica?","options":{"A":"Linfoma não Hodgkin.","B":"Linfoma de Hodgkin","C":"Leucemia linfoide crônica","D":"Leucemia mieloide aguda","E":"Leucemia mieloide aguda"},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-177511","number":"177511","sourceNumber":"177511","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Ao avaliar um paciente de 52 anos pancitopênico com eritroblastos na periferia, dentre\nas possibilidades diagnósticas apresentadas\nabaixo, devemos pensar preferencialmente em:","options":{"A":"Mielodisplasia","B":"Deficiência de vitamina B12","C":"Anemia aplásica","D":"Esferocitose hereditária","E":"Ocupação medular por doença maligna"},"answer":"E","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-154375","number":"154375","sourceNumber":"154375","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Paciente 72 anos, masculino, tem anemia, insuficiência renal, hipercalcemia e lesões\nósseas líticas, com presença de proteína monoclonal por imunofixação. Qual deve ser o\ndiagnóstico?","options":{"A":"Adenocarcinoma de próstata metastático.","B":"Mieloma múltiplo.","C":"Adenocarcinoma de pulmão metastático.","D":"Neoplasia maligna de rim metastática.","E":"Tumor de paratireoide metastático."},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-160448","number":"160448","sourceNumber":"160448","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Um paciente de 55 anos é encaminhado à hematologia para investigação de mieloma\nmúltiplo. Ele está assintomático e os exames laboratoriais mostram (Conforme imagem do caderno\nde questões): Sobre esse cenário clínico, assinale a afirmativa verdadeira.","options":{"A":"Trata-se de um mieloma múltiplo assintomático (smoldering mieloma).","B":"A terapia de indução mais moderna consiste em pulsos isolados de dexametasona.","C":"O paciente apresenta mieloma múltiplo estágio IIB (dois-B).","D":"Há indicação para uso parenteral de pamidronato.","E":"O transplante heterólogo de medúla óssea é o tratamento mais eficaz."},"answer":"C","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":["question_bank/media/medcurso/medcurso-hemato-hem-2/160448.png"],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-160427","number":"160427","sourceNumber":"160427","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Define-se por reação transfusional qualquer intercorrência originada como\nconsequência da transfusão de\nhemocomponentes, durante ou após sua administração. Esses\neventos adversos podem variar de anafilaxia leve a quadros de hepatite grave, sepse e morte. A\nliteratura indica que a prevalência de reações transfusionais em crianças é elevada, e os fatores\nintervenientes são o tipo de hemocomponente, a faixa etária, comorbidade do peciente e\npolitransfusão, sendo que os dois primeiros associam-se, também, com tipo de reação ocorrida. O\nperfil das reações transfusionais costuma ser de eventos:","options":{"A":"De etiologia desconhecida; devido a sangue total.","B":"Alérgicos; devido a sangue total.","C":"De etiologia desconhecida; devido a concentrado de plaquetas.","D":"Alérgicos; devido a concentrado de plaquetas.","E":"Graves; devido a concentrado de hemácias."},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-154401","number":"154401","sourceNumber":"154401","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Escolar de 10 anos com diagnóstico de leucemia linfoblástica aguda apresenta\nsufusões hemorrágicas e hepatoesplenomegalia. Os\nexames laboratoriais apresentam hemograma\n\n= 110.000 leucócitos/ mm³ e predomínio de blastos; Hemoglobina = 7g/dl; Plaquetas = 20.000/mm³.\nApós iniciada a quimioterapia, as alterações\nesperadas para este paciente são:","options":{"A":"Hipercalemia, hipofosfatemia, hiperuricemia.","B":"Hipercalemia, hiperfosfatemia, hiperuricemia.","C":"Hipernatremia, hipercalemia, hiperfosfatemia.","D":"Hipernatremia, hipercalcemia, hiperuricema.","E":"Hipocalemia, hipocalcemia, hiperuricemia."},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-362827","number":"362827","sourceNumber":"362827","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Homem, negro, 60 anos, sem patologias prévias, vem para consulta com quadro de dor\nóssea principalmente em região lombar, associado com fratura patológica evidenciada a radiografia\nde coluna lombossacra. Traz exames laboratoriais prévios com anemia, elevação de creatinina e\nhipercalcemia. O diagnóstico mais provável é:","options":{"A":"mieloma múltiplo.","B":"hipoparatireoidismo.","C":"intoxicação por vitamina D.","D":"hiperparatireoidismo terciário."},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-362843","number":"362843","sourceNumber":"362843","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Pais relatam que, há aproximadamente 20 dias, seu filho de cinco anos iniciou quadro\nde adinamia, fadiga, dores em membros\ninferiores e nas articulações dos joelhos, febre intermitente\ne equimoses pelo corpo, após traumas leves. Exame físico: palidez cutâneo mucosa ++/4+,\nlinfonodomegalias em região cervical bilateralmente, baço palpável a 6,5cm do rebordo costal\nesquerdo, fígado palpável a 3,5cm do rebordo costal direito, equimoses difusas em membros\ninferiores e dorso. Há cerca de uma semana, foi iniciado pelo médico assistente corticoide via oral\npara criança, com melhora das dores em membros inferiores. Exames laboratoriais: hematimetria:\n2.800.000/ mm3, hematócrito: 22,5%; hemoglobina: 7,4g/dL, VCM: 78,3fL, CHCM: 32,8g/dL; HCM:\n25,7pg; leucócitos: 8.000/mm3 (linfócitos 88%, segmentados 12%), contagem de plaquetas\n25.000/mm3. Qual a principal hipótese diagnóstica?","options":{"A":"Leishmaniose visceral","B":"Artrite reumatoide","C":"Leucemia linfoide aguda","D":"Mononucleose infecciosa"},"answer":"C","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-327331","number":"327331","sourceNumber":"327331","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Homem, 31 anos, procurou atendimento médico pois notou nódulo em axila esquerda\nque vem aumentando de tamanho, associado à\nfadiga, perda de peso e febre não aferida. Foi\nsubmetido à biópsia, em que foram visualizadas células gigantes, multinucleadas, com nucléolos\nevidentes, compatíveis com células de Reed- Sternberg. Diante do quadro clínico e do resultado da\nbiópsia, qual a hipótese diagnóstica?","options":{"A":"Tuberculose ganglionar","B":"Linfoma de Hodgkin","C":"Linfoma não Hodgkin","D":"Micose fungoide"},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-348442","number":"348442","sourceNumber":"348442","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Escolar de 10 anos, sexo masculino, com história de febrícula e sudorese noturna há\nmais de um mês, é levado à consulta no posto de saúde. Relata aparecimento de ínguas nas\nregiões cervical, axilar, inguinal e supraclavicular, de dor abdominal difusa leve, astenia e perda\nponderal de 2kg em 1 mês. Nega casos de tuberculose na família. Vacinas em dia. Nega doenças\nou comorbidades. Há 3 meses, fez uso de Nitazoxanida. O exame inicial evidenciou paciente em\nbom estado geral, hipocorado ++/4+, hidratado, anictérico, acianótico, febril (38ºC), eupneico,\nconsciente e orientado. Pressão arterial de 100×60mmHg e frequência cardíaca de 80bpm. Exame\ncardíaco e pulmonar apresentavam-se normais. Ao exame de abdome apresentou esplenomegalia\npalpável a 3cm do rebordo costal esquerdo; hepatomegalia palpável a 5cm do rebordo costal\ndireito. Linfadenopatias palpáveis e visíveis nas cadeias ganglionares cervicais, supraclaviculares,\naxilares e inguinais. Exames laboratoriais: Hemograma: Ht 30%, Hb 9,5g/dL, Leucócitos\n15.600/mm³ (Neutrófilos 13%, Linfócitos 81%, Eosinófilos 3%, macrófagos 3%), Plaquetas\n175.000/mm³. Teste tuberculínico: < 5mm. Baciloscopias de escarro induzido negativas. Cultura\nainda sem resultado. VHS: 85 mm/1ª hora. Sorologias negativas para toxoplasmose, rubéola, HIV,\ncitomegalovirose, mononucleose infecciosa e sífilis. Radiografia de tórax: massa volumosa no\nmediastino médio de contornos irregulares com calcificações. Qual a principal hipótese\ndiagnóstica?","options":{"A":"Cisto broncogênico","B":"Tuberculose ganglionar","C":"Neuroblastoma","D":"Linfoma"},"answer":"D","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-330890","number":"330890","sourceNumber":"330890","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"A criança possui mais tecido linfoide que o adulto e apresenta resposta mais\nexacerbada aos antígenos externos, o que contribui para a incidência aumentada de\nlinfadenomegalias na infância. Sobre as linfadenomegalias, é correto afirmar:","options":{"A":"O linfoma não Hodgkin cursa com linfadenomegalia localizada, volumosa e assimétrica em\nrelação ao lado contra lateral.","B":"Os linfonodos dolorosos se devem à vasodilatação de liberação de bradicininas e são exclusivos\nde quadros infecciosos.","C":"Aumento dos linfonodos occipitais em crianças menores são sinais de alerta para doenças\nlinfoproliferativas, como os linfomas.","D":"A adenopatia reacional é a causa mais comum de aumento do tamanho dos linfonodos e surge\ndevido ao aumento das células intrínsecas do tecido linfoide."},"answer":"D","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-308309","number":"308309","sourceNumber":"308309","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Em relação ao Mieloma Múltiplo, é correto afirmar:","options":{"A":"É comum o surgimento de hepatoesplenomegalia e linfonodomegalias com a progressão da\ndoença.","B":"É uma doença de adulto jovem, entre 20 e 40 anos, frequente no sexo masculino.","C":"Anemia, insuficiência renal, lesões líticas e hipercalcemia fazem parte do quadro\nclínico-laboratorial.","D":"É necessário realizar biópsia de linfonodo e eletroforese de hemoglobina para diagnóstico."},"answer":"C","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-308310","number":"308310","sourceNumber":"308310","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Mulher de 26 anos deu entrada no pronto atendimento, relatando manchas roxas há 3\ndias de aparecimento espontâneo. Ao exame físico: petéquias e equimoses em membros inferiores.\nNega uso de medicações. Foram realizados exames laboratoriais iniciais: hemoglobina: 12,2 g/dl;\nmorfologia de série eritrocitária: sem alterações; leucócitos 5.600/mm³ (diferencial normal);\nplaquetas: 4.000/mm³. Não há comorbidades e o restante da investigação laboratorial foi normal.\n\nQual o diagnóstico e a conduta?","options":{"A":"Trombocitopenia primária imune; prednisona.","B":"Púrpura trombocitopênica trombótica; transfusão de plaquetas.","C":"Trombocitopenia primária imune; transfusão de plaquetas.","D":"Púrpura trombocitopênica trombótica; plasmaférese."},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-308312","number":"308312","sourceNumber":"308312","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Homem de 64 anos, previamente hígido, vem ao ambulatório relatando astenia há 1\nano, perda de peso (10 kg em 6 meses) e dor em hipocôndrio esquerdo. Ao exame físico,\napresenta esplenomegalia. Hemograma apresenta série vermelha com anemia e presença de\nhemácias em lágrimas: série branca com leucocitose, desvio até mielócitos e plaquetopenia.\n\nObserve o hemograma a seguir. Qual é a conduta a ser seguida?","options":{"A":"Iniciar antibioticoterapia.","B":"Investigar lúpus eritematoso sistêmico.","C":"Solicitar eletroforese de proteínas.","D":"Biópsia de medula óssea."},"answer":"D","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":["question_bank/media/medcurso/medcurso-hemato-hem-2/308312.png"],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-313407","number":"313407","sourceNumber":"313407","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Mulher, 65 anos, com diagnóstico de leucemiae passado de infecção fúngica, tendo a\núltima quimioterapia há 15 dias em ambiente hospitalaronde permanece desde então devido\nplaquetopeniacom necessidade de transfusões, inicia quadro febril com picos de até 39ºC. Ao\nexame físico não é possível estabelecer foco infeccioso. PA de 120x80 mmHg. Ausência de sinais\nde desidratação. Hemograma revela neutrófilos de 100. PCR elevada. A melhor conduta\nantimicrobiana nesse momento é:","options":{"A":"Cefepime endovenoso;","B":"Fluconazol endovenoso;","C":"Ertapenem endovenoso;","D":"Ciprofloxacino + amoxicilina/clavulanato."},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-258921","number":"258921","sourceNumber":"258921","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Paciente, 69 anos, sexo masculino, aposentado, vem ao Pronto Atendimento para\nconsulta, apresentando-se com dispneia e fadiga há\noito semanas com piora gradativa e agravo da\nsituação nas últimas 48 horas. Tem antecedentes de HAS bem controlada com metoprolol e\nnifedipina, além de artrite reumatoide com envolvimento de ambas as mãos, já em fase de\nremissão. Ao exame, apresenta PA de 130 x 80 mmHg, FC: 99 BPM e FR de 21 IRPM Sat O2 =\n95%. Está hipocorado 3+/4+, com petéquias e hematomas nos membros superiores e inferiores.\n\nRCR com sopro sistólico em região paraesternal de 3+/6+. Não apresenta visceromegalias.\nRealizou exames, sendo evidenciado hematócrito\nde 21% com volume corpuscular médio (VCM) de\n106 fL, contagem de leucócitos de 2.400 células/mm3 com 60% de neutrófilos, e contagem de\nplaquetas de 38.000/mm³. Em relação ao caso clínico, a principal hipótese diagnóstica é:","options":{"A":"Estenose Mitral.","B":"Síndrome Mielodisplásica.","C":"Púrpura Trombocitopênica Essencial.","D":"Púrpura Trombocitopênica Trombótica."},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-283983","number":"283983","sourceNumber":"283983","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Mulher, 65 anos, com diagnóstico de leucemia e passado de infecção fúngica, tendo a\núltima quimioterapia há 15 dias em ambiente hospitalar onde permanece desde então devido\nplaquetopenia com necessidade de transfusões, inicia quadro febril com picos de até 39oC. Ao\nexame físico não é possível estabelecer foco infeccioso. PA de 120x80mmHg. Ausência de sinais\nde desidratação. Hemograma revela neutrófilos de 100. PCR elevada. A melhor conduta\nantimicrobiana nesse momento é:","options":{"A":"cefepime endovenoso","B":"fluconazol endovenoso","C":"ertapenem endovenoso","D":"ciprofloxacino + amoxacilina/clavulanato"},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-244784","number":"244784","sourceNumber":"244784","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Uma jovem de 20 anos cehga ao pronto-socorro para avaliação de um rash nos\nmembros inferiores. Na semana anterior,\napresentou epstaxe, com duração de 2 horas. No dia\nanterior, teve um 2º episódio de epistaxe e notou hematomas esparsos. Ao exame físico, foram\nencontrados equimoses e petéquias nos membros, VCN =89fL, leucócitos normais e plaquetas =\n17.000/mL. Qual é o tratamento inicial indicado para o caso?","options":{"A":"Transfusão de plaquetas imediata","B":"Imunoglobulina intravenosa","C":"Observação e seguimento no dia seguinte","D":"Prednisona","E":"Anti-histamínicos"},"answer":"D","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-247680","number":"247680","sourceNumber":"247680","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Paciente do sexo feminino, 50 anos, em tratamento quimioterápico para câncer de\nmama, procura pronto atendimento por tosse\nseca há 2 dias, e febre de 39ºC iniciada hoje. Nega\nsintomas urinários ou gastrointestinais, bem como comorbidades. Sinais vitais normais (exceto por\ntemperatura atual de 38,7ºC). Exame segmentar respiratório, cardíaco, abdominal e da pele não\nrevelam anormalidades. Hemograma colhido na urgência mostra Hb = 9,5 leucócitos = 1.900\n(segmentados 25%, bastões 2%) e plaquetas = 90.000. Função hepática e renal normais. Rx tórax\nnormal. Diante desse quadro, a conduta mais adequada é:","options":{"A":"Internação em UTI, colher hemocultura e urocultura, e iniciar antibioticoterapia cobrindo germes\ngram-positivos e gram-negativos, aeróbios e anaeróbios.","B":"Colher hemocultura e urocultura, dar medicamentos sintomáticos e fazer curva térmica nas\npróximas 24 horas.","C":"Hospitalização, coleta de hemocultura e urocultura, e antibioticoterapia com cefalosporina de 3ª\ngeração e macrolídeo por 7 a 14 dias.","D":"Por se tratar de quadro de baixo risco, pode ser tratado com amoxicilina+clavulanato e\nciprofloxacino oral por internação breve ou mesmo ambulatorialmente."},"answer":"D","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-214578","number":"214578","sourceNumber":"214578","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Homem, 56 anos, obeso, com hipertensão e diabetes mal controlados. Apresenta-se\ncom febre há 5 dias e celulite extensa em\nmembro inferior direito relacionada à úlcera plantar\ninfectada. Hemograma de admissão: glóbulos vermelhos = 3.800.00/mm³; hemoglobina = 11,5 g/dl;\nhematócrito = 34,8%; VCM = 87 fl; HCM = 32 pg/mm³; glóbulos brancos = 43.000/mm³ (mielócitos =\n4%; metamielócitos = 7%; bastões = 13%; neutrófilos = 55%; basófilos = 0%; eosinófilos = 4%;\n\nlinfócitos = 8%; monócitos = 9%); RDW = 16%; reticulócitos = 1,3%; plaquetas = 520.000. A\nhipótese diagnóstica e a conduta são:","options":{"A":"Leucemia mieloide aguda; mielograma e hibridação fluorescente in situ (FISH).","B":"Reação leucemoide e plaquetose reacional; iniciar antibioticoterapia.","C":"Leucemia mieloide aguda e quadro reacional sobreposto; mielograma e antibioticoterapia.","D":"Leucemia mieloide crônica; mielograma e pesquisa de cromossomo Philadelphia."},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-221326","number":"221326","sourceNumber":"221326","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Nas alternativas a seguir, assinale a que NÃO representa uma abordagem correta\nfrente a uma criança com plaquetopenia.","options":{"A":"Assim que diagnosticada a PTI, deve-se iniciar transfusão de plaquetas a cada 4 horas.","B":"História clínica, exame físico e exame de hemograma interpretado corretamente permitem\nrealizar o diagnóstico diferencial das plaquetopenias da infância na maior parte dos casos.","C":"A Púrpura Trombocitopênica Idiopática (PTI) recentemente diagnosticada é, geralmente,\nprecedida por infecções virais.","D":"Exames complementares, tais como dosagem de anticorpo contra plaquetas, podem auxiliar na\nconfirmação diagnóstica em alguns casos, mas podem ser falsamente negativos em uma parcela\ndos pacientes pediátricos."},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-181082","number":"181082","sourceNumber":"181082","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"A neutropenia significa diminuição dos neutrófilos e está presenta quando sua\nquantidade cai abaixo de 1500 celulas/µL. Tal situação é encontrada em alguns pacientes\noncológicos. O risco de infecções graves ocorre quando seus níveis caem abaixo de 500\ncélulas/µL. Qual o sitio de infecção mais comum:","options":{"A":"Genitália;","B":"Pele;","C":"Períneo;","D":"Mucosa."},"answer":"D","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-181610","number":"181610","sourceNumber":"181610","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Paciente de 42 anos, previamente hígido, com diagnóstico de câncer de mama em\ntratamento quimioterápico pós-operatório. Fez 3\nciclos de quimioterapia sem intercorrências. Há 14\ndias fez o 4º ciclo, também sem toxicidades até o momento. Há 24 horas iniciou febre associada a\ncalafrios. Nega sintomas respiratórios, digestivos ou urinários. Ao exame: TAx = 38,5°C; PA = 125 x\n85 mmHg; FC = 89 bpm; FR = 16 irpm. Ausculta cardiopulmonar sem anormalidades. Radiografia\nde tórax e EAS normais. Hemograma mostra 1.200 leucócitos, 400 neutrófilos, sem desvio.\n\nHemoglobina = 9,0 g/dl e plaquetas normais. Função hepática e renal normais. A abordagem mais\napropriada para o caso é:","options":{"A":"Internação hospitalar, coleta de culturas e administração de sintomáticos, aguardando resultados\ndas culturas para instituição de terapêutica\nguiada por antibiograma.","B":"Oferecer tratamento ambulatorial com amoxicilina + clavulanato associado à quinolona, com\norientações para retornar se piorar ou febre não ceder em 48 horas, se paciente bem orientado.","C":"Internação em Unidade de Terapia Intensiva (leito de isolamento) e instituição imediata de\nantibioticoterapia de amplo espectro cobrindo Gram-positivos e negativos.","D":"Iniciar protocolo de sepse com terapia de reposição hídrica agressiva, hemotransfusão para\ncorrigir anemia e antibioticoterapia de amplo espectro."},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-159420","number":"159420","sourceNumber":"159420","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Homem de 32 anos consulta por ter percebido nódulo no pescoço há 3 semanas.\nQueixa também de febre, sudorese noturna e\ntosse seca. Ao exame físico, apresenta\nlinfodonomegalia cervical em cadeia posterior indolor. Os linfonodos são endurecidos, o maior tem\n2,5 cm de diâmetro. Não foram encontradas linfodonomegalias em outros locais,\nhepatoespenomegalia ou qualquer outras alterações relevantes. Assinale a alternativa que indica a\nconduta CORRETA para este caso.","options":{"A":"Realizar hemograma e sorologias virais.","B":"Realizar biópsia excisional do linfonodo.","C":"Punção por agulha fina do linfonodo.","D":"Prescrever antibióticos e observar por mais 1 a 2 semanas."},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-156508","number":"156508","sourceNumber":"156508","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"I.N.G., 65 anos, sexo masculino, vinha em investigação devido à anemia e astenia de\ninício há cerca de 6 meses, no entanto, evoluiu com quadro de náuseas, vômitos e hiporexia\nassociado à oligúria e queda da própria altura. Radiografia de crânio com evidência de lesões\nlíticas. Exames laboratoriais demonstram elevação das escórias nitrogenadas, além de elevação de\ncálcio, ácido úrico e globulinas, com fosfatase alcalina normal. Qual é o melhor exame para\nconfirmar a principal hipótese diagnóstica?","options":{"A":"Mielograma.","B":"Biópsia Renal.","C":"Cintilografia óssea.","D":"Dosagem de Paratormônio."},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-109238","number":"109238","sourceNumber":"109238","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"No Linfoma Não Hodgkin, é considerado sintoma B quando o paciente apresenta as\nseguintes alterações:","options":{"A":"Febre, perda de peso e esplenomegalia.","B":"Febre, perda de peso e sudorese noturna.","C":"Esplenomegalia, perda de peso e linfocitose.","D":"Febre, ganho de peso e sudorese noturna."},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-75383","number":"75383","sourceNumber":"75383","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Das hemopatias, qual NÃO apresenta manifestações articulares em sua evolução\nclínica?","options":{"A":"Mieloma múltiplo.","B":"Leucose.","C":"Púrpura trombocitopênica idiopática.","D":"Linfoadenopatia angioimunoblástica."},"answer":"C","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-330638","number":"330638","sourceNumber":"330638","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Fondaparinux é pentassacarídeo sintético, que:","options":{"A":"se liga seletivamente à trombina leva à inibição do fator Xa. Devido à sua discreta interação com\ncomponentes do plasma, não possui ação anticoagulante previsível e pouca variabilidade\nindividual.","B":"se liga seletivamente à trombina leva à inibição do fator Xa. Devido à sua discreta interação com\ncomponentes do plasma, possui ação anticoagulante imprevisível e pouca variabilidade individual.","C":"se liga não seletivamente à trombina leva à inibição do fator Xa. Devido à sua discreta interação\ncom componentes do plasma, possui ação\nanticoagulante previsível e pouca variabilidade\nindividual.","D":"se liga seletivamente à trombina leva à inibição do fator Xa. Devido à sua discreta interação com\ncomponentes do plasma, possui ação anticoagulante previsível e pouca variabilidade individual."},"answer":"D","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-332992","number":"332992","sourceNumber":"332992","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Paciente de 30 anos, previamente hígida, nota aparecimento de petéquias em\nmembros inferiores nas últimas 2 semanas, sem\nqualquer outra queixa. O exame físico é normal e\no hemograma mostra apenas plaquetopenia, com 30 mil plaquetas/mm3, sem alterações na série\nvermelha ou nos leucócitos. Sobre esse quadro clínico, é correto afirmar:","options":{"A":"Diante do alto risco de sangramento grave, a paciente tem indicação de internamento para\ntransfusão de concentrado de plaquetas.","B":"A principal hipótese diagnóstica é de púrpura trombocitopênica imune (PTI), sendo corroborada\npor achado de esplenomegalia e biópsia de medula\nóssea mostrando baixa contagem de\nmegacariócitos.","C":"Frente à hipótese diagnóstica é de púrpura trombocitopênica imune (PTI), está indicada a\npesquisa de infecção pelo HIV, por ser potencial causa de plaquetopenia.","D":"Está indicada a internação hospitalar para transfusão de concentrado de hemácias e\nesplenectomia no mesmo internamento, já que,\nnessa condição, a destruição das plaquetas ocorre\nno baço."},"answer":"C","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-301600","number":"301600","sourceNumber":"301600","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Uma criança com dor musculoesquelética pode apresentar alterações radiológicas que\nsugerem leucemia. Das alternativas apresentadas, qual a que apresenta um achado radiológicos\nsugestivo de leucemia nessas crianças?","options":{"A":"Fraturas de estresse.","B":"Rarefação metafisária.","C":"Osteoporose.","D":"Erosões ósseas."},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-274977","number":"274977","sourceNumber":"274977","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Criança, 8 anos, sexo masculino, em tratamento com quimioterapia devido à leucemia,\nprocura o pronto atendimento com quadro de febre intensa (39?40ºC). Ao exame: REG, descorado\n1+/4+, hidratado, acianótico, anictérico, sem sinais de irritação meníngea. Oroscopia e otoscopia\nnormais. AP: murmúrio vesicular presente, sem ruídos adventícios. ACV: RCR 2T sem sopro.\n\nAbdome: flácido, indolor, sem massas ou visceromegalias, RHA +. Pulsos +, perfusão 2 segundos.\nColhidos exames e culturas (hemocultura e urocultura), optou-se por internação e início de\nantibioticoterapia. Nesse caso, qual seria o antibiótico para iniciar?","options":{"A":"Ceftriaxona.","B":"Cefalexina.","C":"Amoxicilina.","D":"Sulfametoxazol + trimetoprima.","E":"Piperacilina + tazobactama."},"answer":"E","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-239613","number":"239613","sourceNumber":"239613","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"O acometimento ósseo pelo mieloma múltiplo - MM é característico da doença,\npodemos apenas concordar que:","options":{"A":"São lesões líticas que afetam predominantemente o esqueleto axial (crânio, coluna e gradil\ncostal) e as áreas proximais dos membros superiores e inferiores.","B":"São lesões blasticas que afetam predominantemente o esqueleto axial (crânio, coluna e gradil\ncostal) e as áreas proximais dos membros superiores e inferiores.","C":"São lesões líticas que afetam raramente o esqueleto axial (crânio, coluna e gradil costal) e as\náreas proximais dos membros superiores e inferiores.","D":"São lesões líticas que afetam predominantemente o esqueleto axial (crânio, coluna e poupam os\ngradis costais) e as áreas proximais dos membros superiores e inferiores."},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-239615","number":"239615","sourceNumber":"239615","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"A identificação da doença mieloma múltiplo - MM em seu estágio inicial e o\nencaminhamento ágil e adequado para o atendimento especializado dão à Atenção Básica um\ncaráter essencial para um melhor resultado terapêutico e prognóstico dos casos. A maioria dos\npacientes apresenta-se com sinais e sintomas de infiltração plasmocitária (óssea ou de outros\nórgãos) ou lesão renal por deposição de proteína monoclonal tumoral. As manifestações clínicas\nmais comuns ao diagnóstico são listadas abaixo, qual dos itens apresenta erro?","options":{"A":"Doença óssea - Dor óssea principalmente em tórax e coluna induzida pela movimentação (60%).","B":"Doença óssea evoluindo com déficit motor ou sensitivo, fraturas patológicas, redução da altura.","C":"Insuficiência renal - Edema, oligúria, uremia, elevação de creatinina (48%).","D":"A insuficiência renal é secundária principalmente à nefropatia obstrutiva devido a cilindros de\ncadeia pesada monoclonal (proteína de Bence Jones) que se depositam nos túbulos contornados\ndistais e coletores, conhecida como ?rim do mieloma?, e à hipocalcemia."},"answer":"D","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-239616","number":"239616","sourceNumber":"239616","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"No mieloma múltiplo - MM, plasmócitos monoclonais geralmente representam mais de\n10% das células nucleadas da medula óssea;\nno entanto 4% dos pacientes com MM sintomático\ntêm plasmocitose abaixo de 10%. Não podemos aceitar que:","options":{"A":"Isto pode ser consequência da infiltração focal por células do MM ou de problema de coleta da\nmedula óssea, principalmente quando realizado apenas mielograma.","B":"A infiltração corresponde a 50% em média.","C":"Se houver proteína-M elevada (maior que 5g/dL) ou sintomas sugestivos de hiperviscosidade,\nnão é recomendável a medida da viscosidade\nsérica.","D":"Deve-se repetir a coleta em local, preferivelmente com biópsia de medula óssea (BMO)."},"answer":"C","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-239687","number":"239687","sourceNumber":"239687","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Os linfomas (Doença de Hodgkin e Linfomas não Hodgkin) constituem um grupo de\ndoenças neoplásicas malignas que se originam de\ncélulas do sistema imunológico. Somente está\nerrado o item:","options":{"A":"Linfoma Difuso de Grandes Células B (LDGC B) é o mais comum, correspondendo a cerca de\n40% dos novos casos diagnosticados e a cerca\nde 30% de todos os casos de LNH.","B":"Linfoma de Burkitt, o LDGC B é dos mais incidentes em indivíduos HIV positivos.","C":"Os Linfomas não Hodgkin (LNH) agressivos compreendem um grupo biológica e clinicamente\nhomogêneo de hemopatias malignas.","D":"O LDGC B pode-se manifestar nos linfonodos ou sítios extra-nodais, como osso, pele, tireoide,\ntrato gastrointestinal (TGI), sistema nervoso central\n(SNC) e testículo."},"answer":"C","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-221291","number":"221291","sourceNumber":"221291","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Ticagrelor é um novo fármaco antagonista reversível do receptor não tienopiridínico\nP2Y12, sendo adequado o seguinte ao seu\n\nrespeito:","options":{"A":"Necessita de processo de conversão metabólica para um componente ativo","B":"Não necessita de processo de conversão metabólica para um componente inativo.","C":"Não necessita de processo de conversão metabólica para um componente ativo.","D":"Não necessita de processo de desconversão metabólica para um componente ativo."},"answer":"C","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-221318","number":"221318","sourceNumber":"221318","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Nas alternativas abaixo, assinale a que NÃO representa uma abordagem correta frente\na uma criança com plaquetopenia.","options":{"A":"Assim que diagnosticado a PTI, deve-se iniciar transfusão de plaquetas a cada 4 horas.","B":"História clínica, exame físico e exame de hemograma interpretado corretamente permitem\nrealizar o diagnóstico diferencial das\n\nplaquetopenias da infância na maior parte dos casos.","C":"A púrpura trombocitopênica idiopática (PTI) recentemente diagnosticada é, geralmente,\nprecedida por infecções virais.","D":"Exames complementares, tais como dosagem de anticorpo contra plaquetas podem auxiliar na\nconfirmação diagnóstica em\n\nalguns casos, mas podem ser falsamente negativos em uma parcela dos pacientes pediátricos."},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-216863","number":"216863","sourceNumber":"216863","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"As leucemias são as neoplasias mais comuns da infância, correspondendo a\naproximadamente 28% de todos os tipos de câncer na faixa etária pediátrica. Em relação às\nleucemias na infância, assinale a afirmativa CORRETA.","options":{"A":"As leucemias mieloides agudas são as mais comuns, correspondendo de 75 a 80% dos casos,\nseguidas pelas leucemias linfoides agudas, entre 15 a 20%.","B":"Estão entre os fatores prognósticos favoráveis da leucemia linfoide aguda: idade entre 1 a 9\nanos e leucometria abaixo de 50.000/mm³.","C":"Ao suspeitar ou diagnosticar uma leucemia, deve-se prontamente iniciar o corticoide sistêmico\nantes de encaminhar ao oncologista, como\nmaneira de melhorar o prognóstico.","D":"O transplante de medula óssea é o tratamento mais indicado para um paciente com leucemia\nlinfoide aguda."},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-216865","number":"216865","sourceNumber":"216865","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"A hemorragia digestiva é rara em crianças, mas é um tema de grande importância por\nse tratar muitas vezes de uma emergência além\nde causar uma apreensão à família. As causas são\ndiversas e a sistematização com a epidemiologia por idade, facilita na investigação diagnóstica.\n\nUma das causas mais comuns de hemorragia digestiva baixa na faixa etária entre 0 a 30 dias é:","options":{"A":"Síndrome hemolítico-urêmica.","B":"Doença inflamatória intestinal.","C":"Coagulopatia por deficiência vitamínica.","D":"Divertículo de Meckel."},"answer":"C","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-183410","number":"183410","sourceNumber":"183410","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Quanto à terapia transfusional, assinale a alternativa CORRETA.","options":{"A":"É considerado um sangramento excessivo quando a perda ultrapassar 50 ml/hora em 4 horas.","B":"Uma unidade de sangue total contém 1.000 ml de sangue com anticoagulante.","C":"O plasma fresco descongelado é utilizado como expansor volumétrico.","D":"A administração de 250 ml de concentrado de hemácias causa aumento de 1 g/dl de\nhemoglobina.","E":"A transfusão plaquetária está indicada na trombocitopenia induzida por heparina."},"answer":"D","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-177935","number":"177935","sourceNumber":"177935","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"A translocação entre os braços longos dos cromossomos 9 e 22 caracteriza qual\nneoplasia hematológica?","options":{"A":"Leucemia linfocítica crônica.","B":"Tricoleucemia.","C":"Leucemia mieloide crônica.","D":"Mielofibrose primária.","E":"Mieloma múltiplo."},"answer":"C","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-183433","number":"183433","sourceNumber":"183433","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Em pacientes com diagnóstico de LMA-M3, é CORRETO afirmar que:","options":{"A":"O início rápido de quimioterapia de indução de remissão melhora o prognóstico.","B":"O uso de ácido transretinoico previne graves eventos hemorrágicos na fase de indução.","C":"O uso de ácido transretinoico previne a síndrome de lise tumoral.","D":"Os eventos hemorrágicos estão relacionados exclusivamente à plaquetopenia.","E":"A hemoglobina deve ser mantida acima de 10 g/dl."},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-183479","number":"183479","sourceNumber":"183479","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Quanto à epidemiologia do câncer na criança, assinale a alternativa correta.","options":{"A":"Dentre os tipos de leucemias, o mais prevalente na faixa pediátrica é a leucemia linfoide aguda.","B":"A doença de Hodgkin é mais prevalente que o linfoma não Hodgkin na faixa pediátrica.","C":"O adenocarcinoma renal, também conhecido como Tumor de Wilms, é o tumor renal mais\nfrequente na infância.","D":"O retinoblastoma é mais comum em crianças com mais de 5 anos de idade.","E":"Tumor de sistema nervoso central é raro na infância."},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-156292","number":"156292","sourceNumber":"156292","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Mulher de 26 anos, relata queda de estado geral há 7 dias associada à febre aferida de\n(38-39°C). Notou que há 2 meses vem apresentando cansaço aos esforços e também o\naparecimento de \"hematomas na pele\", com episódios de gengivorragia. Ao exame físico\napresenta-se em mal estado geral, prostrada, e sonolenta. Está febril, hipocorada +3/+4, anictérica,\nsem adenopatia cervical, axilar ou inguinal. RCR 2T BNF sem sopros. Murmúrio vesicular presente\ne sem ruídos adventícios com frequência respiratória de 32 incursões por minuto. Abdome é flacido\nsem viceromegalias e membros inferiores apresentando algumas petéquias. Em adição à analise\ndo caso, considere ainda: (conforme imagem no caderno de questões). Para esse caso, assinale a\nalternativa com a conduta correta.","options":{"A":"Para confirmar o diagnóstico, deve se solicitar sorologia para leishmaniose visceral.","B":"Conduzir o caso como sepse, uma vez que o escore q SOFA é de 1.","C":"O aspirado de medula óssea é o exame necessário para confirmar o diagnóstico.","D":"Não está indicada a reposição de concentrado de plaquetas.","E":"Pelo quadro de neutropenia febril, está indicado o uso de cefepime."},"answer":"E","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":["question_bank/media/medcurso/medcurso-hemato-hem-2/156292.png"],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-155695","number":"155695","sourceNumber":"155695","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"João Pedro, de 28 anos, portador de leucemia linfoblástica aguda, vai à emergência\nqueixando-se de febre e calafrios há 24\nhoras. Na carteira de identificação do tratamento,\ndemonstra que está fazendo o esquema CVAD ( ciclofosfamida, vincristina, doxorrubicina e\ndexametasona) hiper fracionada e que a última dose foi há oito dias. Nega tosse e dispneia,\ncefaleia, dor abdominal ou diarreia. Nega contato com doentes nem fez viagem recente. Ao exame,\nfebril, com 39,1°C, com frequência cardíaca de 118 bpm, pressão arterial de 120/80 mmHg e\nfrequência respiratória de 25 IRPM, possui aparência de doente; a pele está quente e úmida, mas\nsem exantema. Sem sinais de mucosite, ausculta pulmonar nada digno de nota, exame\ncardiológico: taquicárdico e possui ritmo regular, com sopro sistólico +2/6 na borda esternal\nesquerda, e o abdome inocente. A região perianal está normal e não realizou toque retal. Apresenta\ncateter inserido na veia jugular interna direita sem eritema sobre o trajeto subcutâneo e sem\nsecreção purulenta no local de saída do cateter. É interessante notar que ele relata o aparecimento\nde tremores com calafrios decorridos 30 minutos do congestionamento do cateter. Os exames\nlaboratoriais mostram hemoglobina de 10,8 g/100mL, hematócrito de 33%, leucócitos totais de\n\n1.100 células/mm3, com diferencial de 8% de neutrófilos, 6% de bastonetes, 6% de eosinófilos,\n66% de linfócitos e 14% de monócitos (a\ncontagem absoluta de neutrófilos é de 88/mm3) e 195000\nplaquetas. Função renal e marcadores hepáticos normais. PCR + raio X tórax: normal e evidencia\ncateter de longa permanência implantado na veia subclávia direita. A partir desse caso, responda à\npróxima questão. Assinale a alternativa CORRETA quanto ao diagnóstico provável para este\npaciente e o possível foco da infecção.","options":{"A":"Neutropenia febril, e o foco provável é o trato geniturinário.","B":"Neutropenia febril, e o foco provável é o pulmão com possível pneumonia.","C":"Neutropenia febril, e o foco provável é o cateter.","D":"Endocardite bacteriana, e o foco foi o cateter.","E":"Neutropenia febril, e o foco provável é desconhecido."},"answer":"C","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-152347","number":"152347","sourceNumber":"152347","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Paciente masculino, 10 anos de idade, pesando 32 quilos, soropositivo para HIV de\ntransmissão vertical, apresenta diagnóstico de linfoma abdominal não Hodgkin há 1 semana. Fez\nquimioterapia há 4 dias. Hoje está hipoativo, hipotenso, desidratado, em anasarca, descorado e\nreferindo dor lombar à direita de forte intensidade. Tem diurese de 8 ml/hora; ureia de 205;\ncreatinina de 4,8; potássio de 6,1; cálcio de 8,2; ácido úrico urinário de 0,75 mg/dl; e gasometria\ncom acidose metabólica. Acerca desse caso, qual é o diagnóstico MAIS provável?","options":{"A":"Cálculo impactado em ureter distal.","B":"Cálculo coraliforme em pelve renal direita.","C":"Desidratação secundária a vômitos pós-quimioterapia.","D":"Síndrome da lise tumoral aguda."},"answer":"D","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-151016","number":"151016","sourceNumber":"151016","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Paciente de 75 anos com queixa de anemia e dor costal à direita. Radiografia de\ncostelas, crânio e coluna lombar evidenciando lesões líticas. Eletroforese de proteínas com pico\nmonoclonal. Considerando o diagnóstico mais provável, assinale a alternativa CORRETA:","options":{"A":"A dor decorrente da infiltração óssea piora principalmente à noite e deve ser tratada\ninicialmente\ncom uso de anti-inflamatórios.","B":"A proteinúria apresentada pelo paciente é à custa de cadeias leves e não de albuminúria.","C":"A hipergamaglobulinemia confere aos pacientes um aumento da resistência a infecções\nbacterianas e germes capsulados.","D":"A fosfatase alcalina é usualmente normal, mesmo com lesões ósseas extensas, por não haver\natividade osteoblástica."},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-156296","number":"156296","sourceNumber":"156296","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Paciente de 4 anos, sexo masculino, com diagnóstico de Púrpura Trombocitopênica\nImunológica (PTI) há 5 meses. Realizado\nmielograma, ao diagnóstico, sem alterações. No\nmomento, a criança está bem, sem sangramentos, porém com contagem plaquetária de 22000 e\nséries eritrocitária e leucocitária normais. Quais classificação e tratamento devem ser determinados\npara esse paciente?","options":{"A":"PTI aguda. Tratamento conservador com observação criteriosa e sem uso de medicamentos\npara aumentar o número de plaquetas.","B":"PTI aguda. Tratamento com imunoglobulina.","C":"PTI persistente. Tratamento com imunoglobulina.","D":"PTI persistente. Tratamento conservador com observação criteriosa e sem uso de\nmedicamentos para aumentar o número de plaquetas.","E":"PTI crônica. Tratamento conservador com observação criteriosa e sem uso de medicamentos\npara aumentar o número de plaquetas"},"answer":"D","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-156305","number":"156305","sourceNumber":"156305","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Considerando que PTI é um diagnóstico de exclusão para trombocitopenia, qual dos\nitens a seguir não é considerado causa plaquetopenia?","options":{"A":"Infecção por Helicobacter pylori.","B":"Infecção por Epstein-Barr.","C":"Síndrome do anticorpo antifosfolípide.","D":"Deficiência de tiamina.","E":"Hiperesplenismo."},"answer":"D","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-140357","number":"140357","sourceNumber":"140357","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Em relação a coagulação sanguínea, marque a alternativa CORRETA:","options":{"A":"Todos os fatores de coagulação são produzidos pelo fígado","B":"Todos os fatores de coagulação são dependentes de vitamina k para serem sintetizados","C":"A terapia com cumarínicos pode ser avaliada dosando-se o tempo de protrombina, que deve\nestar entre 1-2","D":"A heparina utilizada em soluções de lavagem de cateter é suficiente para causar\ntrombocitopenia","E":"Nenhuma das anteriores"},"answer":"E","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-137892","number":"137892","sourceNumber":"137892","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Escolar masculino em quimioterapia, em unidade de oncologia pediátrica, evolui com\npiora clínica. Assinale a alternativa que apresenta as alterações que ratificam a suspeita de lise\ntumoral:","options":{"A":"Hiperuricemia, hipercalemia e hiperfosfatemia.","B":"Hiperuricemia, hipercalemia e hipofosfatemia.","C":"Hipouricemia, hipercalemia e hiperfosfatemia.","D":"Hipouricemia, hipocalemia e hiperfosfatemia.","E":"Hiperuricemia, hipocalemia e hipofosfatemia."},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-130100","number":"130100","sourceNumber":"130100","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Paciente masculino, 47 anos, com história de há dois anos iniciar com parestesias,\nastenia e distensão abdominal. Apresentava\ntambém impotência sexual e escurecimento da pele.\nAo exame físico, apresentava palidez de mucosas, hepatoesplenomegalia e ginecomastia. Em\nestudo com radiografias, observavam-se lesões osteoblásticas na pelve e duas lesões\nosteoblásticas em escápula direita. À eletroneuromiografia, demonstrou padrão misto de\npolineuropatia em membros superiores e inferiores. Exames laboratoriais demonstravam anemia de\ndoença crônica, com leucócitos e plaquetas normais, além de níveis normais de creatinina, cálcio e\nglicose. O paciente apresentava baixos níveis de tiroxina livre e testosterona total; níveis\nelevados\nde Hormônio Estimulador da Tireoide (TSH) e prolactina. Eletroforese de proteínas com gamopatia\nmonoclonal e a dosagem específica das imunoglobulinas e das cadeias leves mostrou um aumento\nde IgA e lambda, respectivamente. Em suma, o paciente apresentava uma patologia crônica que se\nmanifestava com polineuropatia, hepatoesplenomegalia; múltiplas endocrinopatias caracterizadas\npor hipogonadismo, hiperprolactinemia e hipotireoidismo; pico monoclonal de IgA e lambda;\nalterações de pele; e lesões osteoescleróticas em vários ossos. O diagnóstico mais provável, nesse\ncaso, é:","options":{"A":"Síndrome de POEMS.","B":"Mieloma múltiplo.","C":"Síndrome SAPHO.","D":"Pico monoclonal de significado indeterminado."},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-107611","number":"107611","sourceNumber":"107611","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Paciente masculino, 68 anos, sem comorbidades significativas, apresenta achado de\nexame físico de esplenomegalia (6 cm abaixo do\nRCE). Seu hemograma mostra: Hb 14 g%,\nLeucócitos 78.000/mm³ (Blastos 2%, promielócitos 3%, mielócitos 7%, meta 8%, bastões 10%,\n\nsegmentados 45%, eosino 3%, baso 5%, linfo 15%, mono 2%),Plaquetas:850.000/mm³. Qual a\nconduta adequada ao caso?","options":{"A":"Solicitar recoleta, pois o quadro clínico não é compatível com o exame.","B":"Encaminhar o paciente ao Pronto-Socorro, pois se trata de reação leucemoide.","C":"Solicitar pesquisa do gene de fusão BCR abl por PCR em sangue periférico.","D":"Solicitar Cariótipo com Banda G de sangue periférico.","E":"Indicar tratamento imediato com mesilato de imatinibe."},"answer":"C","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-107693","number":"107693","sourceNumber":"107693","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Paciente masculino, 76 anos, procura Serviço de Pronto Atendimento com história de\nfraqueza progressiva há 15 dias. Há 7 dias, observou equimoses esparsas não relacionadas a\ntraumas. Há 2 dias, iniciou com febre e queda do estado geral. Antecedente de DM e HAS há 5\nanos, usando Metformina e Losartan. O exame físico mostra palidez +++/4+, Tax = 38,4 C, PA =\n90/60 mmHg, FC 120 bpm, ausência de linfonodomegalias, abdome flácido com baço palpável 3\ncm RCE, equimoses grandes esparsas pelo corpo. O Hemograma inicial mostra: Hb 7 g% VCM 90,\nLeucócitos 1.700/mm³ (30% neutrófilos, linfócitos 65% e Monócitos 5%), Plaquetas 20.000/mm³.\n\nQual a conduta?","options":{"A":"Triagem de foco infeccioso, iniciar antibioticoterapia empírica e indicar punção aspirativa de\nmedula óssea.","B":"Triagem de foco infeccioso, iniciar antibioticoterapia empírica e solicitar sorologias para\nhepatites\ncrônicas e leishmaniose.","C":"Triagem de foco infeccioso e indicar antibioticoterapia empírica, aguardar o antibiograma e\nobservar evolução.","D":"Iniciar antibioticoterapia empírica imediata e indicar transfusão de concentrado de hemácias e\nplaquetas.","E":"Transfusão de concentrado de hemácias e plaquetas e indicar biópsia de medula óssea."},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-111730","number":"111730","sourceNumber":"111730","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Qual é um fator de bom prognóstico associado ao diagnóstico de leucemia linfoide\naguda na criança?","options":{"A":"Leucócitos em número maior que 50,000/mm³.","B":"Idade entre 1 e 10 anos.","C":"Doença em sistema nervoso central ao diagnóstico.","D":"Leucemia de linhagem T.","E":"Translocações cromossômicas na faixa 11q23."},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-83450","number":"83450","sourceNumber":"83450","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Paciente, 65 anos, masculino, com quadro de lombalgia há 2 meses, com piora à\nmovimentação. Refere que há 45 dias iniciou paraparesia e há 2 dias está com incapacidade de\nmovimentação de membros inferiores. Você está de plantão no pronto-socorro e faz o primeiro\natendimento do paciente. Escolha a conduta CORRETA:","options":{"A":"Trata-se de lombalgia crônica com sinais de gravidade. Deve-se internar o paciente e solicitar o\nTC de coluna lombar e torácica para\navaliação de compressão\n\nmedular.","B":"Deve-se solicitar TC de coluna lombar e, se normal, iniciar tratamento domiciliar com analgesia.","C":"Trata-se de lombociatalgia e deve-se realizar tratamento com AINE e fisioterapia.","D":"Deve-se considerar a hipótese diagnóstica de espondilite anquilosante, visto tratar-se de\nhomem com lombalgia crônica.","E":"Não é necessário realização de exames complementares, visto tratar-se de lombalgia aguda\ncuja principal etiologia é de origem mecânica."},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-60181","number":"60181","sourceNumber":"60181","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Das doenças abaixo, qual apresenta risco maior de desenvolvimento de linfoma quando\ncomparado à população geral?","options":{"A":"Lúpus eritematoso sistêmico.","B":"Doença de Behçet.","C":"Síndrome de Sjögren.","D":"Policondrite Recidivante.","E":"Doença Mista do Tecido Conjuntivo."},"answer":"C","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-64961","number":"64961","sourceNumber":"64961","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"O plantonista de Clínica Médica é chamado para avaliar paciente masculino de 71 anos\ninternado na enfermaria de ortopedia por fratura de L2, sem sintomas compressivos, que está\napresentando anemia (Hb = 7,8 g/dl) e insuficiência renal (creatinina = 2,5 mg/dl). O paciente\nrefere lombalgia intensa e progressiva há seis meses tendo realizado vários tratamentos\nortopédicos sem melhora. Nos últimos dois meses, evolui com fraqueza importante e epistaxes\nrecorrentes. Ao exame físico, apresenta palidez cutâneo-mucosa +++/4+, taquicardia em repouso e\ndor à compressão esternal. O exame radiológico de coluna mostra diminuição de altura com\nacunhamento de várias vértebras lombares e torácicas. Quais achados adicionais são esperados\npara o caso?","options":{"A":"Hipocalcemia, hiperuricemia e pico monoclonal em gamaglobulinas na eletroforese de proteínas.","B":"Lesões em saca-bocados na calota craniana, hipercalcemia e pico policlonal em gamaglobulinas\nna eletroforese de proteínas.","C":"Hipoalbuminemia, hiperuricema e pico policlonal em gamaglobulinas na eletroforese de\nproteínas.","D":"Hipocalcemia, lesões em saca-bocados em calota craniana e aumento dos níveis de IgG sérica.","E":"Hipoalbuminemia, hipercalcemia e pico monoclonal em gamaglobulinas na eletroforese de\nproteínas."},"answer":"E","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-45491","number":"45491","sourceNumber":"45491","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Vera tem 4 anos e comparece com o pai à consulta ambulatorial com história de febre\nbaixa intermitente há 2 semanas, anorexia, cansaço, dor em membros inferiores e articulações,\nsangramento nasal, cefaleia e vômitos. Ao exame, você verifica mucosas pálidas, sem alterações\nectoscópicas em membros inferiores ou articulações. O procedimento mais indicado para o\ndiagnóstico conclusivo de Vera é realizar:","options":{"A":"Provas de função reumática.","B":"Exame da medula óssea.","C":"Tomografia de crânio.","D":"Punção lombar.","E":"Cintilografia óssea."},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-45902","number":"45902","sourceNumber":"45902","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Paciente de 60 anos procura atendimento no ambulatório queixando-se de dores\nósseas localizadas em 1/3 médio de úmero direito e\ndor lombar baixa com irradiação e parestesia\nem membro inferior esquerdo. Relata ainda adinamia, astenia, emagrecimento de 5 Kg, formação\nde hematomas em MMII. Nega febre ou adenomegalias. Trouxe exames: creatinina 1,9 mg/dl,\ncálcio 11 mg/dl, hemoglogina 9,6 g/100 ml, imunofixação com elevação de imunoglobulina G no\nsoro. Qual diagnóstico mais provável e qual exame ajudaria a confirmá-lo?","options":{"A":"Leucemia mieloide crônica e mielograma com hipocelularidade com hipoplasia mieloide.","B":"Leucemia linfocítica crônica e contagens linfocitárias absolutas acima de 2.000/µL no sangue\nperiférico.","C":"Linfoma de Hodgkin e biópsia de linfonodo com observação de grandes células anaplásicas.","D":"Macroglobulinemia de Waldenström e mielograma com infiltração de neutrófilos.","E":"Mieloma múltiplo e mielograma com 10% ou mais de células plasmáticas."},"answer":"E","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-45529","number":"45529","sourceNumber":"45529","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"No Mieloma Múltiplo, a causa mais comum de insuficiência renal se deve a:","options":{"A":"Infiltração de plasmócitos no rim.","B":"Hiperuricemia.","C":"Depósito de proteína monoclonal (amiloidose).","D":"Hipocalcemia.","E":"Nefrite intersitical aguda."},"answer":"C","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-31827","number":"31827","sourceNumber":"31827","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Mulher, 23 anos de idade, queixando-se de tosse seca há 2 meses, realizou TC de\ntórax evidenciando vários linfonodos em região\nmediastinal. Submetida à biópsia, essa revelou a\npresença de células de Reed-Sternberg. Baseado nesses dados, o provável diagnóstico e subtipo\nhistológico são, respectivamente:","options":{"A":"Linfoma não Hodgkin e linfocítico de pequenas células.","B":"Doença de Hodgkin e celularidade mista.","C":"Doença de Hodgkin e esclerose nodular.","D":"Linfoma não Hodgkin e tipo grandes células (Burkitt).","E":"Doença de Hodgkin e predominância linfocitária."},"answer":"C","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-34513","number":"34513","sourceNumber":"34513","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Em relação à Neutropenia Febril, assinale a alternativa incorreta.","options":{"A":"Define-se febre como temperatura axilar superior a 38ºC e neutropenia como a contagem de\nneutrófilos absoluta de menos de 500/mm³ ou 1000/mm³ com tendência a queda, em duas\namostras separadas.","B":"Neutropenia Grave é aquela com contagem inferior a 200 cel/mm³.","C":"Uso de sondas no trato urinário e gastrointestinal são fatores complicadores na Neutropenia\nFebril.","D":"Mucosite com alteração da integridade da mucosa agrava o quadro.","E":"Pacientes submetidos a transplantes de medula não estão sujeitos à Neutropenia Febril mesmo\nusando quimioterápicos."},"answer":"E","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-359401","number":"359401","sourceNumber":"359401","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Homem de 35 anos é levado ao Pronto-Socorro por causa de fraqueza generalizada,\ndificuldade para deambular, náuseas e vômitos. Possui seminoma testicular com acometimento\nlinfonodal secundário acentuado. Recebeu a primeira quimioterapia quatro dias antes. Ao exame\nfísico, apresenta as mucosas desidratadas e coradas. Está alerta e orientado. Apresentou\ncontratura do antebraço e da mão durante a aferição da pressão arterial nesse membro. Exames\nde laboratório: creatinina 1,8mg/dL; ureia 64mg/dL; sódio 136mEq/L; potássio 6,2mEq/L; fósforo\n5,3mg/dL; ácido úrico 12,4mg/dL; cálcio iônico 0,72mmol/L. Assinale a alternativa que apresenta\numa conduta inicial INADEQUADA:","options":{"A":"Correção da hipercalemia - beta-2 agonista e furosemida IV.","B":"Correção da hipocalcemia - gluconato de cálcio IV.","C":"Hidratação venosa vigorosa com solução de cloreto de sódio 0,9%.","D":"Prescrição de rasburicase ou alopurinol."},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-301223","number":"301223","sourceNumber":"301223","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Mulher de 76 anos apresenta emagrecimento, dor lombar, astenia e dispneia aos\nesforços. Desconhece comorbidades prévias, nega\ntabagismo, etilismo ou uso de medicamentos.\nAo exame, as mucosas estão descoradas; sem outras anormalidades. Exames de laboratório: Hb\n7,3 g/dl; LG 6.500/mm³; Plq 112.000/mm³; VHS 95 mm na primeira hora; creatinina 2,2 mg/dl; ureia\n47 mg/dl; cálcio total 10,6 g/dl; albumina sérica 2,0 g/dl; LDH 450 UI/L; BT 0,9 mg/dl. A\nhematoscopia revelou o seguinte achado: Considerando o diagnóstico mais provável para essa\npaciente, assinale a alternativa que apresenta o(s) exame(s) MAIS ADEQUADO(S) a ser(em)\nsolicitado(s) nesse momento:","options":{"A":"Eletroforese de proteínas séricas e urinárias.","B":"Endoscopias do trato digestivo alto e baixo.","C":"Pesquisa do cromossomo Philadelphia.","D":"Teste de fragilidade osmótica de eritrócitos."},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":["question_bank/media/medcurso/medcurso-hemato-hem-2/301223.png"],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-263057","number":"263057","sourceNumber":"263057","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Paulo, cinco anos de idade, com primo diagnóstico de leucemia linfoide aguda, iniciou\nfebre (39,2ºC) associada a queixa de dor\nabdominal, cerca de 15 dias após fase de indução de\nquimioterapia. Ao exame físico, apresenta-se em bom estado geral, hidratado, hipocorado leve,\npulsos cheios. FC:92bpm, PA: 98x70mmHg, FR:22irpm, sem esforço, sons pulmonares fisiológicos,\nsem lesões de pele. Exames laboratoriais: Hb: 8g/dL; Htc:24%; Plaquetas: 70.000/mm³; Leucócitos\nglobal: 280/mm³ (segmentados: 80/mm³; eosinófilos: 50/mm³; monócitos:50/mm³;\nlinfócitos:100/mm³); Proteína C Reativa:200mg/L; Hemocultura em andamento. De acordo com este\ncaso clínico, assinale a alternativa que apresenta a antibioticoterapia de escolha para o tratamento\nempírico:","options":{"A":"Ampicilina e amicacina","B":"Cefepime","C":"Cefepime e vancomicina","D":"Ciprofloxacino"},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-233790","number":"233790","sourceNumber":"233790","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Criança de sete anos de idade foi admitida na UPA com relato de quadro de prostração,\nhiporexia, cansaço e dor em membros inferiores de início há duas semanas. Ao exame físico:\ncriança afebril, hipocorada e hidratada. Oroscopia e otoscopia sem alterações; FR = 28 irpm, sem\nsinais de esforço respiratório, SatO? = 96% em ar ambiente; FC = 110 bpm, pulsos periféricos\ncheios, perfusão imediata; abdome indolor sem visceromegalias. Resultado do hemograma:\nhemácias = 2,43 milhões/mm³ (VR: 4,0?5,2 milhões/mm³); hemoglobina: 8,5 g/dl (VR: 11,5?15,5\ng/dl); hematócrito = 25% (VR: 35?45%); global de leucócitos = 124.180/mm³ (VR:\n4.500?13.500/mm³); diferencial = 2% neutrófilos; 10% linfócitos; 88% blastos. Plaquetas =\n32.000/mm³ (VR: 150.000 a 450.000/mm³). Assinale a conduta imediata MAIS ADEQUADA:","options":{"A":"Iniciar ceftriaxona e oxacilina.","B":"Iniciar hiperidratação venosa.","C":"Realizar transfusão de hemácias.","D":"Realizar transfusão de plaquetas."},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-203275","number":"203275","sourceNumber":"203275","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Homem de 44 anos foi admitido em CTI com choque séptico que teve como foco lesão\ntraumática infectada extensa em membro inferior direito. Algumas horas após a admissão, foram\nobservadas petéquias, equimoses, sangramento no sítio de inserção de cateter venoso central e\ngengivorragia. O plantonista solicitou hemograma e coagulograma para avaliação inicial. À\nhematoscopia, foram observados numerosos esquizócitos. Dentre as opções a seguir, qual é o\ndiagnóstico MAIS PROVÁVEL e como devem estar o Tempo de Protrombina (TP), o Tempo Parcial\nde Tromboplastina ativado (PTTa) e contagem de plaquetas?","options":{"A":"Coagulação intravascular disseminada, TP e PTTa prolongados e trombocitopenia.","B":"Deficiência prévia de fator de coagulação e infecção aguda, TP e PTTa prolongados e\ntrombocitose.","C":"Púrpura trombocitopênica trombótica, TP normal, PTTa prolongado e trombocitopenia.","D":"Uso prévio de warfarin e infecção aguda, TP prolongado, PTTa normal e trombocitopenia."},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-174697","number":"174697","sourceNumber":"174697","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"No que diz respeito ao linfoma de Hodgkin, assinale a alternativa ERRADA:","options":{"A":"A afecção, cuja incidência atinge o pico por volta dos 30 anos, inicia-se mais frequentemente\nnos linfonodos cervicais, progredindo por\ncontiguidade.","B":"Do ponto de vista histopatológico, o linfoma de Hodgkin clássico, tipo celularidade mista,\ncaracteriza-se por aspecto celular heterogêneo e, particularmente, pela ausência de eosinófilos.","C":"Em jovens com linfoma de Hodgkin clássico, tipo esclerose nodular, é frequente o acometimento\ndo mediastino.","D":"Nas células de Hodgkin e nas células de Reed-Sternberg, é frequente a expressão\nimuno-histoquímica de uma proteína do vírus Epstein-Barr."},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-174750","number":"174750","sourceNumber":"174750","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"A propósito das intoxicações exógenas, assinale a alternativa ERRADA:","options":{"A":"A hipertermia, eventualmente fatal, pode ser observada na intoxicação por anfetaminas, em\nespecial na intoxicação pela 3,4-metilenodioximetanfetamina (ecstasy).","B":"A meta-hemoglobinemia, passível de ser causada por drogas como a dapsona e o nitrobenzeno,\npode ser tratada com o azul de metileno, que\nfavorece a conversão da meta-hemoglobina em\nhemoglobina, na medida em que aumenta a atividade da meta-hemoglobina redutase.","C":"A n-acetilcisteína está indicada na intoxicação pelo paracetamol, sendo mais efetiva quando\nadministrada até 8 a 10 horas após a ingestão do analgésico.","D":"A vitamina K reverte a ação dos anticoagulantes, em especial dos novos agentes disponíveis por\nvia oral como a dabigatrana, a rivaroxabana e a apixabana."},"answer":"D","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-174772","number":"174772","sourceNumber":"174772","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Mulher de 34 anos passou a apresentar nas últimas seis semanas equimoses\nespontâneas principalmente nas pernas. Informa\ntambém sangramento excessivo na última\nmenstruação e episódio de epistaxe volumosa há cinco dias. Diz que está se sentindo bem e\ncontinua trabalhando normalmente. Sem passado mórbido de importância. Não há história familiar\nde doença hemorrágica. Não é tabagista e ingere bebida alcoólica apenas socialmente. Nega uso\natual e recente de qualquer medicamento. Ao exame, observam-se múltiplas equimoses nas suas\npernas e, em menor número, no abdome e braços. Há sangramento espontâneo nas gengivas. O\nexame de fundo de olho não evidencia hemorragias. Os dados vitais e o restante do exame físico\nestão dentro dos limites da normalidade. Hemoglobina = 12,9 g/dl (hematoscopia sem achados\ndignos de nota); leucócitos totais = 5.300/mm³ (contagem diferencial dentro da normalidade);\nplaquetas = 5.000/mm³; e RNI; PTT; função renal; íons; glicemia e bioquímica hepática dentro dos\nlimites da normalidade. Fator Antinuclear (FAN); anti-HIV e anti-HCV (vírus da hepatite C)\nnegativos. Considerando-se o diagnóstico mais provável, é possível afirmar que a plaquetopenia\napresentada pela paciente é resultante de:","options":{"A":"Consumo excessivo de plaquetas.","B":"Destruição de plaquetas por autoanticorpos e possível inibição da produção/liberação dessas\ncélulas pelos megacariócitos.","C":"Redução da produção de plaquetas devido à deficiência de ácido fólico e/ou vitamina B12.","D":"Redução da produção de plaquetas devido à infiltração da medula óssea por neoplasia."},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-174785","number":"174785","sourceNumber":"174785","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"J.K.L, 67 anos, sexo feminino, balconista, está em uso de dose terapêutica de\nenoxaparina por trombose venosa profunda\napós artroplastia de joelho. Após 6º dia de uso da\nreferida medicação, a contagem de plaquetas é de 66.000/mm³ (contagem de plaquetas antes da\nanticoagulação era de 212.000/mm³). Não está em uso de outros medicamentos e apresenta-se\nassintomática. Diante deste contexto, assinale a alternativa ERRADA:","options":{"A":"Deve-se evitar o uso de fondaparinux (inibidor indireto de fator Xa).","B":"Esta condição resulta da formação de anticorpos contra complexo heparina/fator-4-plaquetário.","C":"Inibidores diretos da trombina constituem-se em opção terapêutica.","D":"Trombose (arterial ou venosa) é uma complicação frequente."},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-149962","number":"149962","sourceNumber":"149962","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Sobre a utilização de hemocomponentes em pacientes cirúrgicos, assinale a alternativa\nCORRETA:","options":{"A":"A utilização de hemocomponentes leucodepletados está indicada para prevenção de reação\ntransfusional febril não hemolítica em pacientes com mais de duas reações prévias.","B":"As transfusões de plasma e/ou crioprecipitados devem ser feitas com filtros, devido à alta\nconcentração de leucócitos íntegros.","C":"O uso de concentrado de hemácias deve ser feito com parcimônia devido ao risco de sobrecarga\nvolumétrica.","D":"Plasma fresco congelado tem como uma de suas principais indicações promover expansão\nvolumétrica."},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-149933","number":"149933","sourceNumber":"149933","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Em relação a paciente submetido a profilaxia para trombose venosa profunda por\ntempo prolongado com heparina não fracionada, assinale a alternativa ERRADA:","options":{"A":"Esta droga é clareada principalmente pelos receptores situados no endotélio, macrófagos e rins","B":"Pode apresentar trombocitopenia autoimune","C":"Seu mecanismo de ação se faz por inativação de vários fatores da cascata de coagulação,\nsendo os mais sensíveis a trombina e o fator\nXa","D":"Sua maior afinidade por proteínas plasmáticas lhe confere maior biodisponibilidade e maior\nmeia-vida plasmática"},"answer":"D","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-149881","number":"149881","sourceNumber":"149881","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Paciente de cinco anos de idade há sete dias apresenta quadro de linfadenomegalia\ngeneralizada, hepatomegalia e febre baixa. Qual dos\nachados clínicos abaixo NÃO é considerado\nsinais de alertas para doença maligna?","options":{"A":"Emagrecimento e palidez cutâneo-mucosa.","B":"Linfadenomegalia com sinais inflamatórios.","C":"Linfonodos aderentes aos planos profundo ou superficial.","D":"Linfonodos com consistência aumentada."},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-127521","number":"127521","sourceNumber":"127521","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Paciente de 65 anos, hipertenso, é admitido em caráter de urgência em pronto-socorro\ncom síndrome de veia cava superior associada ao\nlinfoma do tipo grandes células. Foi iniciado\ntratamento com corticosteroides seguido de quimioterapia. Além da elevação do ácido úrico sérico,\nqual conjunto de alterações abaixo pode advir do tratamento do tumor, até sete dias após seu\ninício?","options":{"A":"Hipercalemia, hiperfosfatemia, hipocalcemia.","B":"Hipocalemia, hiperfosfatemia, hipocalcemia.","C":"Hipercalemia, hipofosfatemia, hipercalcemia.","D":"Hipocalemia, hipofosfatemia, hipercalcemia."},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-101861","number":"101861","sourceNumber":"101861","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Mulher de 47 anos apresenta-se para exame admissional, sem passado mórbido de\nimportância. Ao exame físico, seu baço foi palpado a cerca de 4 cm abaixo do rebordo costal\nesquerdo, sem outras alterações. Trouxe consigo um hemograma recente com alterações muito\nsugestivas de leucemia mieloide crônica. Assinale a alternativa com as alterações no hemograma\nMAIS prováveis para esse diagnóstico:","options":{"A":"Leucocitose, eosinopenia, linfopenia, presença de eritroblastos e de plaquetas gigantes.","B":"Leucocitose, trombocitose, basofilia e presença de todos os tipos celulares da linhagem\nneutrofílica, sem atipias.","C":"Leucopenia, anemia, trombocitopenia e presença de neutrófilos hipersegmentados.","D":"Leucopenia, linfopenia, anemia e presença de mieloblastos."},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-60307","number":"60307","sourceNumber":"60307","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Criança do sexo masculino, 7 anos de idade, diagnóstico de leucemia linfoide aguda,\nrecebeu quimioterapia há 10 dias. É atendida na\nunidade de pronto atendimento com queixa de\nfebre (38,5°C) há 3 horas que cedeu ao uso de dipirona. O exame físico não evidenciou\nanormalidades. O hemograma mostrou leucometria de 1.200 céls/mm³ (10% neutrófilos e 85% de\nlinfócitos). Assinale a alternativa que indica CORRETAMENTE a conduta inicial nesse quadro:","options":{"A":"Antibioticoterapia oral com cobertura para Gram-positivos, em ambiente domiciliar.","B":"Internação e antibioticoterapia de amplo espectro com cobertura para Gram-negativos.","C":"Observação domiciliar da curva térmica, uma vez que a criança não apresenta qualquer\nalteração ao exame físico.","D":"Observação hospitalar da curva térmica, uma vez que a criança não apresenta qualquer\nalteração ao exame físico."},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-71467","number":"71467","sourceNumber":"71467","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Paciente de 45 anos, portador de leucemia linfoide aguda em tratamento\nquimioterápico, vem ao pronto atendimento com\nquadro de febre de 39ºC, tremores e prostração.\nHemograma realizado no dia anterior mostra contagem de leucócitos de 200/microL, contagem de\nplaquetas de 23.000/microL e hemoglobina de 9,1 g/dl. Em relação ao caso clínico apresentado,\ntodas as afirmações são corretas, EXCETO:","options":{"A":"Se a neutropenia desse paciente tiver duração superior a 2 semanas, o risco de infecção fúngica\naumenta significativamente.","B":"Sinais e sintomas de infecção podem estar muitas vezes ausentes em neutropênicos graves.","C":"A presença concomitante de plaquetopenia e anemia indica quadro de aplasia irreversível de\nmedula óssea.","D":"Contagens de leucócitos abaixo de 500/mm³ predispõem a infecções bacterianas e fúngicas."},"answer":"C","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-71493","number":"71493","sourceNumber":"71493","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Paciente de 52 anos chegou ao pronto atendimento com sinais e sintomas de uremia.\nSua creatinina é de 8,2 mg/dl, ureia de 201\nmg/dl e cálcio de 13,5 mg/dl. Seu hemograma mostra\nhemoglobina de 8,5 g/dl, leucócitos de 6.500/microL (com diferencial normal) e contagem de\nplaquetas de 140.000/microL. Existe observação no hemograma descrevendo presença de\nrouleaux. Qual é o diagnóstico hematológico MAIS PROVÁVEL?","options":{"A":"Mieloma múltiplo.","B":"Leucemia promielocítica aguda.","C":"Síndrome mielodisplásica.","D":"Linfoma de Hodgkin."},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-60347","number":"60347","sourceNumber":"60347","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Homem de 32 anos, usuário de cocaína, encontra-se internado na enfermaria de clínica\nmédica com quadro séptico, em uso de cefepima. Foi isolado Klebsiella sp. em 3 amostras de\nhemocultura e o plantonista é acionado pela enfermagem para avaliar achado de gangrena em\nartelhos de ambos os pés. Havia também sinais de necrose hemorrágica na pele dos antebraços e\ndas mãos. Diante do quadro, é CORRETO afirmar que:","options":{"A":"A fibrinólise secundária gera diminuição dos produtos de degradação da fibrina e aumento do\nd-dímero.","B":"O consumo e o aumento de função dos fatores de coagulação são responsáveis pelo\nalargamento da atividade de protrombina e do tempo de tromboplastina parcial ativado.","C":"O depósito de fibrina intravascular causa fragmentação das hemácias e gera aparecimento de\nesquizócitos no sangue periférico.","D":"Os produtos de degradação da fibrina são potentes agentes trombofílicos e se associam à\ntrombose microvascular."},"answer":"C","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-53317","number":"53317","sourceNumber":"53317","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Paciente de 45 anos, portador de leucemia linfoide aguda em tratamento\nquimioterápico, procura o pronto atendimento\ncom quadro de febre de 39°C, tremores e prostração.\nHemograma realizado no dia anterior mostrava contagem de leucócitos de 200/mm³, contagem de\nplaquetas de 23.000/mm³ e hemoglobina de 9,1 g/dl. Em relação ao caso clínico apresentado,\ntodas as afirmações são corretas, EXCETO:","options":{"A":"A presença concomitante de plaquetopenia e anemia indica quadro de aplasia irreversível de\nmedula óssea.","B":"Contagem de leucócitos abaixo de 500/mm³ predispõe a infecções bacterianas e fúngicas.","C":"Se a neutropenia desse paciente tiver duração superior a 2 semanas, o risco de infecção fúngica\naumenta significativamente.","D":"Sinais e sintomas de infecção podem, muitas vezes, estar ausentes em neutropênicos graves."},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-55309","number":"55309","sourceNumber":"55309","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Mulher de 67 anos de idade queixa-se de dor esternal, sensação de aumento do\nvolume abdominal e astenia. Já foi hospitalizada\numa vez para colecistectomia. Iniciou há 30 dias\nuso de captopril para hipertensão arterial. Ao exame físico nota-se aumento do baço (cerca de 12\ncm abaixo do rebordo costal esquerdo), sem hepatomegalia. Não se palpam linfonodos. Não são\nvistas petéquias ou hematomas. O hemograma demonstra contagem de leucócitos de\n95.000/microL, com 15% de neutrófilos bastonados, 28% de neutrófilos segmentados, 10% de\nmetamielócitos, 5% de mielócitos, 4% de blastos, 4% de eosinófilos e 8% de basófilos. A\nhemoglobina é de 15 g/dl e a contagem de plaquetas, de 750.000/microL. Qual é o diagnóstico\nMAIS PROVÁVEL?","options":{"A":"Leucemia mieloide aguda.","B":"Leucemia mieloide crônica.","C":"Leucemia linfoide crônica.","D":"Reação leucemoide ao captopril."},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-52413","number":"52413","sourceNumber":"52413","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Paciente de 47 anos, masculino, portador de leucemia linfoide aguda, vem ao Pronto\nAtendimento com quadro de prostração e febre de 39,2°C. Realizou quimioterapia endovenosa há\nnove dias. Nega disúria, tosse ou expectoração e diarreia. Hemograma mostra contagem global de\nleucócitos de 300/microL. Um regime de tratamento empírico inicial para esse paciente deve incluir\nqual das opções abaixo?","options":{"A":"Azitromicina.","B":"Polimixina.","C":"Amicacina e claritromicina.","D":"Cefepima."},"answer":"D","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-52417","number":"52417","sourceNumber":"52417","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Criança do sexo masculino, com 2 anos de idade, apresenta hemartrose volumosa em\njoelho esquerdo secundária à queda da própria altura. O único dado relevante na história perinatal\né relato de hemorragia no coto umbilical. Exames laboratoriais: tempo de tromboplastina parcial\nativada (PTTa) prolongado. Tempo de protrombina, tempo de sangria e contagem de plaquetas\nnormais. Em relação ao caso clínico, o diagnóstico mais provável é:","options":{"A":"Deficiência congênita de fator VII.","B":"Deficiência de vitamina K.","C":"Doença de von Willebrand.","D":"Hemofilia."},"answer":"D","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-53334","number":"53334","sourceNumber":"53334","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Paciente, cinco anos de idade, com leucemia mieloide aguda, candidato a transplante\nde medula óssea, é admitido no hospital com\nquadro de febre (temperatura axilar: 39ºC). Exame\nfísico: presença de petéquias em tronco e membros superiores. Hipocorado e taquicárdico.\n\nApresentando hipotensão arterial. História prévia de reação transfusional febril. Hemograma:\nhemoglobina = 6 g/dl; plaquetas = 12.000/mm³; leucócitos = 700/mm³ (segmentados = 8%;\nlinfócitos = 80%; monócitos = 2%). Qual das condutas abaixo deve ser evitada neste paciente?","options":{"A":"A adição de vancomicina ao esquema inicial de tratamento deve ser considerada, pois o\npaciente apresenta sinais de instabilidade hemodinâmica.","B":"Administração imediata de antibióticos de largo espectro, mesmo que a avaliação inicial não\nrevele a etiologia do processo infeccioso.","C":"Aguardar o resultado de culturas ou localização de foco infeccioso para iniciar\nantibioticoterapia.","D":"Deve ser utilizado, obrigatoriamente, um esquema de antibióticos com boa cobertura para\nbactérias Gram-negativas."},"answer":"C","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-355408","number":"355408","sourceNumber":"355408","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Paciente do sexo feminino, 30 anos, consulta seu médico com um histórico de\nepistaxes frequentes desde a infância, bem como\nmenstruações prolongadas e com alto fluxo.\nSangramentos excessivos após exodontias. Ela relata que outros membros de sua família também\ntêm o mesmo histórico de sangramentos excessivos. Os exames de laboratório revelam um tempo\nde protrombina (TAP) e um Tempo de Tromboplastina Parcial Ativada (TTPA), dentro da faixa da\nnormalidade, porém uma plaquetopenia leve é vista em exame, com plaquetometria em torno de\n\n100.000. Qual é o diagnóstico mais provável para esta paciente?","options":{"A":"Hemofilia A.","B":"Trombocitose essencial.","C":"Doença de von Willebrand.","D":"Púrpura trombocitopênica idiopática (PTI)."},"answer":"C","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-361751","number":"361751","sourceNumber":"361751","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Você atende no pronto-socorro um idoso masculino de 63 anos com queixa de fadiga,\nmal-estar, perda ponderal, hiporexia, febre baixa e desconforto abdominal com saciedade precoce\nhá 6 meses. É previamente hipertenso e diabético, com bom controle das comorbidades.\n\nSolicitados exames laboratoriais, que evidenciam leucometria de 60.000 células/mm3, hemoglobina\n9,2 g/dL, plaquetometria 83.000 células/mm3,\ndemais exames laboratoriais sem alterações\nsignificativas. Exame físico evidencia regular estado geral, descorado 2+/4, desidratado +/4,\nacianótico, anictérico, temperatura 37,8°C. Abdome globoso, levemente doloroso em hemiabdome\nesquerdo, com baço palpável abaixo do rebordo costal esquerdo. Pensando-se em leucemia\nmieloide crônica, assinale a alternativa correta.","options":{"A":"A pesquisa da translocação t(9;22) por análise citongenética, ou por FISH, ou a pesquisa da\nproteína BCR-ABL por PCR é essencial para confirmação diagnóstica.","B":"A doença é causada por uma alteração somática na célula-tronco hematopoiética. Dentre os\nmarcadores de gravidade, destacam-se diagnóstico em faixas etárias mais avançadas e\nhipoviscosidade do sangue.","C":"Sintomas de leucostase, como dispneia, confusão mental e alteração do nível de consciência\nsão frequentes na fase crônica.","D":"Apesar de o principal achado ser esplenomegalia, ela não tem relação com a leucometria.\n\nEnvolvimento extramedular, como linfonodos e pele, são comuns na fase crônica."},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-369748","number":"369748","sourceNumber":"369748","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Paciente usuário de AAS e clopidogrel para insuficiência coronariana apresenta\nsangramento importante. Dentre as opções abaixo qual poderia ser usada para melhorar a\ncoagulação do paciente tendo em vista as medicações que utiliza?","options":{"A":"Complexo protrombínico","B":"Administração de plaquetas","C":"Fitomenadiona","D":"Plasma fresco congelado"},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-355378","number":"355378","sourceNumber":"355378","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Criança de 7 anos, previamente hígida, retorna de viagem durante o feriado para o sítio\nda família com petéquias em tronco e equimoses em membros inferiores iniciadas há 4 dias\nacompanhada de epistaxe nasal. Não há relato de trauma, apresenta bom estado geral, sem febre\nou outros sintomas associados. Realizado hemograma no PS: Hb: 13,0 g/dl, Ht: 37,5%, leucócitos\nglobais: 12500/mm³, segmentados: 42%, linfócitos: 48%, monócitos 10%, plaquetas 15,000/mm³.\n\nSobre o tratamento do caso em questão, pode-se afirmar que:","options":{"A":"os pais devem ser orientados sobre a melhora espontânea do quadro, não sendo necessária\npermanência no hospital.","B":"é recomendada internação em enfermaria hospitalar e parecer da cirurgia para realização de\nesplenectomia.","C":"é recomendada internação em UTI para realização de transfusão de plaquetas pelo risco de\nsangramento.","D":"é recomendada internação em enfermaria hospitalar e avaliação do hematologista para início de\ncorticoterapia."},"answer":"D","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-340709","number":"340709","sourceNumber":"340709","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"A varfarina pode ser utilizada no paciente com câncer:","options":{"A":"Na disponibilidade de outras medicações ou em situações específicas de contraindicação aos\noutros anticoagulantes, como na insuficiência renal crônica dialítica.","B":"Na indisponibilidade de outras medicações, mas não em situações específicas de\ncontraindicação aos outros anticoagulantes, como na insuficiência renal crônica dialítica.","C":"Na indisponibilidade de outras medicações ou em situações específicas de contraindicação aos\noutros anticoagulantes, como na insuficiência renal crônica dialítica.","D":"Na indisponibilidade de outras medicações ou em situações específicas de indicação aos outros\nanticoagulantes, como na insuficiência renal crônica dialítica."},"answer":"C","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-330307","number":"330307","sourceNumber":"330307","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Homem de 21 anos apresenta múltiplas sufusões pelo corpo de início há 3 dias. Nega\ntraumas, outras manifestações clínicas, comorbidades conhecidas, uso de medicamentos e de\ndrogas lícitas ou ilícitas. Não possui história familiar significativa. Ao exame físico, PA:\n110x70mmHg, FC: 68bpm, Tax: 36,5ºC. Apresenta sufusões nos membros superiores, inferiores e\ntronco. Sem outras anormalidades quaisquer (incluindo linfonodomegalias ou visceromegalias\nabdominais). Exames de laboratório: Hemoglobina: 15,3g/dL (VR 12-16g/dL); Leucócitos:\n5.840/mm³ (4000-11.000/mm³); neutrófilos: 2.580/mm³ (1500-7000/mm³); linfócitos: 1.250/mm³\n(1.000-4.000/mm³); plaquetas: 9.000/mm³ (150.000-450.000/mm³); hematoscopia do sangue\nperiférico: presença de macroplaquetas, sem outras anormalidades; creatinina: 0,7mg/dL; bilirrubina\ntotal: 0,4mg/dL (<1,2mg/dL); PCR: 1,2mg/L (<5mg/L); TSH: 1,560mUI/L (0,5-5,0mUI/L); RNI 1,1;\n\nPTTa 25/25; exame de urina sem alterações. Assinale a alternativa que apresenta um exame\ndiagnóstico CORRETAMENTE indicado na propedêutica desse caso.","options":{"A":"Mielograma.","B":"Fibrinogênio.","C":"Anticorpos anti-HIV.","D":"TC de pescoço, tórax e abdome total."},"answer":"C","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-330317","number":"330317","sourceNumber":"330317","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Em pediatria, são causas de anemia com plaquetopenia, EXCETO:","options":{"A":"Deficiência de folatos e vitamina B12.","B":"Leucemia linfocítica aguda.","C":"Leishmaniose visceral.","D":"Púrpura trombocitopênica autoimune (P.T.I) e púrpura de Henoch- Schonlein."},"answer":"D","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-330322","number":"330322","sourceNumber":"330322","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Sobre a trombocitopenia imune primária, é CORRETO afirmar que:","options":{"A":"A deficiência de vitamina D é um diagnóstico diferencial.","B":"A PTI não tem relação com infecções virais agudas em crianças.","C":"É caracterizada com plaquetopenia abaixo de 100.000/mm³.","D":"Os pacientes geralmente apresentam anemia e hepatoesplenomegalia."},"answer":"C","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-346248","number":"346248","sourceNumber":"346248","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Pré-escolar, três anos e cinco meses, sexo feminino, vem apresentando dores ósseas\ndifusas iniciadas há três meses, que não\nmelhoram com o uso de analgésicos comuns, associados\nà febre baixa intermitente, cefaleia, vômitos frequentes, anorexia, perda ponderal de quatro quilos\ne\nirritação com prejuízo de sono. A partir do resultado do hemograma, foi diagnosticado \"anemia\ndiscreta? tendo sido prescrito sulfato ferroso por seis meses. Há um mês, a mãe notou palidez que\nvem se acentuando. Exame físico: irritabilidade, fáceis de sofrimento, dificuldade para deambular\npela dor, hipocorada +/4+, adenomegalias cervicais, axilares e inguinais móveis, fibroelásticas, não\ncoalescentes, medindo de 0,5 a 1 cm de diâmetro, fígado palpável a 5 cm, do rebordo costal direito,\nbaço a 4 cm do rebordo costal esquerdo, petéquias em membros inferiores e sopro sistólico +/4+\npancardíaco, sem irradiação. A principal hipótese diagnóstica é:","options":{"A":"Neuroblastoma.","B":"Febre reumática.","C":"Leucemia linfoide aguda.","D":"Artrite idiopática juvenil.","E":"A principal hipótese diagnóstica se mantém de anemia ferropriva que já está sendo tratada."},"answer":"C","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-301021","number":"301021","sourceNumber":"301021","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Um paciente com mieloma múltiplo recém-diagnosticado, mas ainda virgem de\ntratamento, dá entrada no pronto-socorro com\no seguinte quadro: rebaixamento do nível de\nconsciência, desidratação, distensão abdominal e redução dos ruídos hidroaéreos e insuficiência\nrenal aguda. Familiar relata que o quadro teve evolução progressiva nos últimos dias, sendo que,\nno início, o paciente estava apresentando diurese muito abundante, que posteriormente se reduziu,\nassociado ao agravamento dos outros sintomas. Qual é a provável etiologia do quadro?","options":{"A":"Síndrome de lise tumoral.","B":"Metástase para o sistema nervoso central.","C":"Hipercalcemia.","D":"Síndrome de hiperviscosidade."},"answer":"C","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-301037","number":"301037","sourceNumber":"301037","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Uma criança de sete anos de idade é levada ao pronto atendimento devido ao\nsurgimento de petéquias e equimoses por todo\ncorpo. O pai, que acompanhava a criança, nega\ntraumas físicos e relata um quadro gripal há sete dias. Nega ingestão de medicamentos e, até o\npresente momento, a criança era hígida, sem história pregressa de doenças do sangue. Ao exame\nfísico, a criança estava eupneica, sem alterações cardíacas, sem viceromegalias ou\nlinfadenomegalias e com petéquias e equimoses em face, tronco e membros. Diante disso, foi\nsolicitado um hemograma, cujos resultados são: Hb = 12.5g/dl; Ht = 38%; VCM = 78; leucócitos =\n\n9.000 (N60% L30% M8% E2%); plaquetas = 80.000/mm3. Sobre esse quadro clínico, assinale a\nalternativa CORRETA.","options":{"A":"Trata-se de uma leucemia aguda, e a criança deverá ser internada em um hospital de referência\nem oncologia pediátrica para estender a\npropedêutica.","B":"Deve-se informar o pai que se trata de uma púrpura de Henoch-Schönlein, e a criança poderá\nreceber alta e ser conduzida\nambulatorialmente pelo pediatra.","C":"O quadro clínico e o exame laboratorial são condizentes com trombocitopenia imune, e o\npaciente pode ser internado para estender a propedêutica diagnóstica.","D":"Trata-se de um quadro de púrpura trombocitopênica imune, e o paciente deverá receber\ntransfusão de plaquetas com urgência como primeira conduta."},"answer":"C","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-259392","number":"259392","sourceNumber":"259392","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Homem de 25 anos, sabidamente portador de Leucemia linfoblástica Aguda, em atual\nmanejo sistêmico de tratamento com uso de quimioterápicos. Informa última sessão realizada há\ncerca de sete dias. Admitido para avaliação com relato de câimbras em membros inferiores,\nnáuseas, vômitos e diarreia de início recente. Nega febre, manifestações dermatológicas ou outras\nmanifestações sistêmicas. Exames laboratoriais: creatinina: 3,7 mg/dL, ureia 200mg/dL, Sódio:\n155meq/L, Potassio: 6,0meq/L, cloretos: 125meq/L, leucócitos totais: 100.000 cels /mm3 (90%\nblastos 5% neutrófilos, 3% macrófagos) plaquetas: 100.000 mm3 Hb:9,0g/dL Ht:28% fósforo: 7\nmg/L (VR: até 4,8mg/dL) cálcio iônico: 1,0 mg/dL (valor de referência: (até 1,2mg/dL) ácido úrico:\n12\nmg/dL TGO:45 Ui/L TGP:50 Ui/L FA:200 Ui/L GGT: 280 Ui/L HCO3 ( venoso): 18meq/L. Diante da\nmelhor hipótese diagnóstica assinale a conduta clínica inicial mais apropriada:","options":{"A":"Monitoramento contínuo, hidratação venosa, correção dos distúrbios hidroeletrolíticos, uso de\nrasburicase.","B":"Monitoramento contínuo, hidratação venosa e alcalinização urinária.","C":"Monitoramento contínuo e início imediato de terapia renal substitutiva.","D":"Monitoramento contínuo, coleta de culturas e início de protocolo para sepse em\nimunossuprimido."},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-260542","number":"260542","sourceNumber":"260542","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"No mieloma múltiplo:","options":{"A":"Sem proteinúria, não há risco para desenvolvimento de insuficiência renal aguda.","B":"Hipercalcemia, eventualmente observada, seria secundária à insuficiência renal aguda.","C":"Há predisposição a infecções por bactérias encapsuladas devido a imunodeficiência humoral\npredominante.","D":"O principal achado do hemograma é a presença de plasmócitos."},"answer":"C","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-278851","number":"278851","sourceNumber":"278851","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Das alternativas apresentadas abaixo, assinale a correta considerando-se o diagnóstico\nde neutropenia febril.","options":{"A":"Tem a mesma conotação para os pacientes em tratamento oncológico e para os pacientes\nportadores de aplasia medular medicamentosa.","B":"Precisa ser tratada o mais precocemente possível para reduzir a morbidade e a mortalidade dos\npacientes em tratamento quimioterápico.","C":"Deve ser considerada também para pacientes febris que estão fora de tratamento\nantineoplásico.","D":"É considerada um diagnóstico de exclusão, motivo pelo qual deve-se buscar exaustivamente a\ncausa da febre antes de instituir o tratamento."},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-287633","number":"287633","sourceNumber":"287633","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Paciente de 7 anos de idade, assintomático, realizou ecografia de abdome de rotina\nque evidenciou formação cística em loja\nesplênica, de aproximadamente 09 centímetros. Para\nelucidação diagnóstica, realizou também ressonância magnética que confirmou a hipótese de cisto\nesplênico marginal, sem comprometimento do hilo esplênico. Tem hemograma normal, e sorologias\nparasitárias negativas. A conduta mais adequada neste caso é:","options":{"A":"Esplenectomia total.","B":"Esplenectomia parcial.","C":"Antibioticoterapia sistêmica.","D":"Seguimento anual com ultrassom."},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":["question_bank/media/medcurso/medcurso-hemato-hem-2/287633.png"],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-260559","number":"260559","sourceNumber":"260559","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Pré-escolar apresenta há 2 dias sangramento gengival. Nega febre. Em seu exame\napresenta-se em bom estado geral, sem\nlinfadenomegalia ou hepatoesplenomegalia e notam-se\npetéquias e hematomas pelo corpo. Seu hemograma apresenta hemoglobina 12,5 g/dl, hematócrito\n\n= 36%, leucócitos 8.000/mm³ com contagem diferencial sem anormalidade para idade e plaquetas\n6.000/mm³. O diagnóstico mais provável é:","options":{"A":"Aplasia de medula.","B":"Linfoma.","C":"Púrpura trombocitopênica idiopática.","D":"Leucemia linfocítica aguda."},"answer":"C","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-260273","number":"260273","sourceNumber":"260273","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Paciente de seis anos de idade, com quadro de equimoses em tronco e membros\ninferiores há sete dias, sem história de\ntrauma, com bom estado geral, sem hepatoesplenomegalia\ne sem febre. Realizado hemograma: Hb: 12,5 g/dL, Ht 37%, leucócitos globais: 13.800/mm³,\nsegmentados: 40%, linfócitos: 50%, monócitos 10%, plaquetas 90.000/mm³. Assinale a alternativa\ncorreta com relação ao caso clínico apresentado.","options":{"A":"O início de uso de antibiótico de amplo espectro está indicado nesse caso devido à leucocitose\nevidenciada no hemograma.","B":"O agente etiológico mais provável é o vírus da dengue, e a conduta mais correta é a hidratação\noral domiciliar.","C":"O uso de corticoide é uma opção terapêutica nessa situação, visto que o caso do paciente é\nsugestivo de trombocitopenia imune.","D":"Esse paciente corre risco iminente de sangramento pela plaquetopenia e está indicada a\ntransfusão de plaquetas."},"answer":"C","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-262963","number":"262963","sourceNumber":"262963","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"A respeito das abordagens cirúrgicas do baço, assinale a alternativa incorreta.","options":{"A":"No paciente com púrpura trombocitopênica idiopática, a esplenectomia está indicada somente\nem caso de falha na terapêutica clínica.","B":"A profilaxia contra sepse pós-esplenectomia com vacinação é mais eficaz se realizada duas\nsemanas antes da abordagem cirúrgica que se\nrealizada no pós-operatório.","C":"Neoplasias malignas do baço devem sempre ser tratadas com esplenectomia total.","D":"Abscessos esplênicos requerem esplenectomia total e antibioticoterapia."},"answer":"D","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-266652","number":"266652","sourceNumber":"266652","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Leucemia é o câncer que tem origem na medula óssea, onde são produzidas as células\ndo sangue. Sobre a leucemia, assinale a\nalternativa INCORRETA:","options":{"A":"A leucemia mieloide crônica representa 75% dos casos na faixa etária pediátrica e com pico\nentre 2 e 5 anos.","B":"A anemia costuma ser mais intensa nos casos de LMA, inclusive já manifestam com insuficiência\ncardíaca ao diagnóstico.","C":"A confirmação do diagnóstico ocorre pelo mielograma, pela presença de mais de 20-30% de\nblastos de morfologia homogênea.","D":"O transplante de medula, com doador HLA compatível, é o tratamento de escolha na leucemia\nmieloide aguda após a indução de remissão inicial."},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-253903","number":"253903","sourceNumber":"253903","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Dentre as medicações abaixo, a que potencializa o efeito da warfarina:","options":{"A":"Barbitúricos","B":"Ribavirina","C":"Piroxicam","D":"Colestiramina"},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-239819","number":"239819","sourceNumber":"239819","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Paciente de 62 anos, sexo masculino, admitido na enfermaria para investigação\ndiagnóstica. Relata perda de peso involuntária de\ncerca de 18 kg nos últimos 5 meses, sensação\nde saciedade precoce, hiporexia, fadiga, astenia e febre. Ao exame abdominal percebe-se\nesplenomegalia (baço Boyd III). Exames laboratoriais: Hb: 10,5 g/dl (VR: 11.3 a 16.3); VCM: 80 fl\n(VR: 77 a 92); HCM: 28 pg (VR: 27 a 32); CHCM: 32 g/dl; RDW: 22; Global de leucócitos:\n\n590.000/mm3 (VR: 1800 a 7500); Segmentados: 34%; Bastonetes: 24%; Metamielócitos: 13%;\n\nMielócitos: 9%; Promielócitos: 5%; Blastos: 3%; Eosinófilos: 4% Basófilos: 5% Linfócitos: 2%\nMonócitos: 1%; Plaquetas: 400.000/ml (VR:\n130.000 a 370.000/ml). Diante do caso acima, assinale\no diagnóstico mais provável:","options":{"A":"Leucemia mielóide crônica.","B":"Trombocitemia essencial.","C":"Abscesso esplênico.","D":"Leucemia linfocítica crônica."},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-239821","number":"239821","sourceNumber":"239821","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Paciente de 80 anos, sexo masculino, comparece a unidade básica de saúde com\nqueixa de lombalgia, que piora ao movimento,\niniciada há cerca de 2 meses. Informa diagnóstico\nrecente de anemia. Não está em uso de medicações. Trouxe resultado de exames solicitados há\numa semana: Hemoglobina = 10,2 g/dL (VR: 11.3 a 16.3); VCM = 85 FL (VR: 77 a 92); HCM = 30\npg (VR: 27 a 32); Global de leucócitos = 6200/ml (VR = 4.000 a 10.000/ml); Neutrófilos = 50% (VR:\n45 a 75%); Linfócitos = 35 % (VR = 22 a 40%); Monócitos = 9% (VR: 3 a 10%); Eosinófilos = 5%\n\n(VR: 1 a 5%); Basófilos = 1% (VR: 0 a 2%); Plaquetas: 150.000/ml (VR: 130.000 a 370.000/ml);\n\nReticulócitos = 0,4% (VR: 0,5 a 2,17%); Ferro sérico = 80 mcg/dl (VR: 60 a 160); Ferritina = 150\n(VR: 13 a 200 ng/ml); Capacidade total de\nligação do ferro (TIBIC) = 300 mcg/dl (VR: 240 a 410);\nCreatinina = 2,6 mg/dL ( VR: 0,6-1,2 mg/dL) e uréia = 50 mg/dL (VR: 16-40 mg/dL). Albumina 3,6\ng/dL (VR: 3,5-4,7 g/dL); Cálcio total = 13,2 (VR: 8,5-10,2 mg/dL). Assinale a alternativa que contém\no diagnóstico mais provável:","options":{"A":"Hiperparatireoidismo primário.","B":"Mieloma múltiplo.","C":"Artrite reumatoide.","D":"Osteoartrose."},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-253932","number":"253932","sourceNumber":"253932","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Marque o câncer mais comum na infância.","options":{"A":"Neuroblastoma","B":"Retinoblastoma","C":"Leucemia","D":"Linfoma"},"answer":"C","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-238655","number":"238655","sourceNumber":"238655","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Considere o caso clínico a seguir. Paciente, 3 anos de idade, apresenta-se com quadro\nde febre intermitente há um mês, associado a\ndor em membros inferiores. Hemograma revela\nleucopenia com neutropenia importante e também plaquetopenia leve. Sobre esse caso, assinale a\nalternativa CORRETA.","options":{"A":"O paciente deve ser encaminhado ao reumatologista por provável diagnóstico de artrite\nidiopática juvenil.","B":"O corticoide deve ser iniciado imediatamente, independentemente do diagnóstico do paciente.","C":"Um exame indicado para esse paciente é o mielograma para avaliar presença de blastos.","D":"A idade do paciente deixa improvável algum diagnóstico reumatológico ou oncológico."},"answer":"C","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-238660","number":"238660","sourceNumber":"238660","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Considere um paciente de 3 anos de idade com quadro de febre de 39ºC há sete dias,\npalidez importante, regular estado geral, hepatoesplenomegalia. Realizado hemograma: Hb: 6,9\ng/dL, Ht 21%, leucócitos globais: 800/mm³; segmentados: 40%, linfócitos: 50%, monócitos: 10%,\nplaquetas: 120 000/mm³. A esse respeito, assinale a alternativa correta.","options":{"A":"O início de antibiótico de amplo espectro está indicado nessa situação, mesmo sem o paciente\nter um diagnóstico etiológico definitivo.","B":"O agente etiológico mais provável é viral, a conduta mais correta é hidratação oral domiciliar,\njá\nque o paciente não se apresenta hemoconcentrado.","C":"O uso de antibiótico é obrigatório nessa situação, visto que o paciente tem uma infecção\nbacteriana.","D":"Esse paciente corre risco iminente de sangramento pela plaquetopenia e está indicada\ntransfusão de hemácias e plaquetas."},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-239872","number":"239872","sourceNumber":"239872","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Relacione as alterações laboratoriais nos distúrbios de coagulação com o diagnóstico\nmais provável:\n\nCOLUNA I - Alterações dos exames:\n\n1. Plaquetopenia;\n\n2. Tempo de tromboplastina parcial ativado prolongado;\n\n3. Tempo de protrombina prolongado;\n\n4. Dímero D aumentado.\n\nCOLUNA II - Diagnóstico:\n\n( ) Hemofilia;\n\n( ) Deficiência de vitamina K;\n( ) Leucemia;\n\n( ) Coagulação intravascular disseminada.\n\nAssinale a alternativa que apresenta a sequência CORRETA.","options":{"A":"1 3 2 4.","B":"2 1 4 3.","C":"2 3 1 4.","D":"2 1 4 3."},"answer":"C","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-219416","number":"219416","sourceNumber":"219416","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Paciente 32 anos iniciou quimioterapia para tratamento de leucemia linfoblástica aguda.\nApós dois dias da primeira dose foi\nadmitido no hospital por mal-estar seguido por convulsão. Qual\no achado bioquímico mais consistente com o diagnóstico?","options":{"A":"Hipercalcemia","B":"Hiperuricemia","C":"Hipocalemia","D":"Hipomagnesemia"},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-219427","number":"219427","sourceNumber":"219427","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Paciente sexo masculino, 72 anos, com diagnóstico de IAMSST. Está em tratamento\nhospitalar. Está recebendo heparina\nnão-fracionada e monitorado para possíveis sinais e sintomas.\nQual o episódio está mais relacionado a uma reação?","options":{"A":"Epistaxe","B":"Sincope","C":"Trombose venosa","D":"Distúrbio visual"},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-203873","number":"203873","sourceNumber":"203873","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Uma criança de 3 anos é internada na enfermaria devido ao surgimento súbito de\npetéquias em abdome e membros inferiores associado à epistaxe volumosa. Foi avaliada pelo\notorrinolaringologista que realizou um tamponamento de emergência. Ao exame, a criança está\nhipocorada, hidratada, acianótica, anictérica, com petéquias e equimoses em todo corpo, abdome\nsem visceromegalias, ausência de linfadenomegalias, escala de coma de Glasgow 15; FC = 120\nbpm; FR = 28 irpm; PA = 95 x 50mmHg. Na história pregressa, o teste do pezinho foi normal e\napresentou um quadro viral há 14 dias. O pediatra que fez o primeiro atendimento solicitou um\nhemograma que estava praticamente normal, com exceção do número de plaquetas que era de\n5.000/mm³. Assinale a alternativa que apresenta a hipótese diagnóstica e a conduta MAIS\nadequada para o caso descrito.","options":{"A":"Púrpura trombocitopênica idiopática e imunoglobulina intravenosa.","B":"Púrpura de Henoch-Schöenlein e anti-inflamatório venoso.","C":"Leucemia linfoblástica aguda e metilprednisolona venosa.","D":"Leishmaniose visceral e anfotericina B lipossomal intravenosa."},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-217160","number":"217160","sourceNumber":"217160","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Paciente de 82 anos da entrada no setor de emergência com fratura de colo de fêmur.\nÉ portador de coronariopatia, cardiopatia,\nnefropatia, e usuário de AAS, Clopidogrel, carvedilol,\naldactone e sinvastatina. O ortopedista está preocupado e pede sua opinião para prevenir\nsangramento intra-operatório. Qual opção correta:","options":{"A":"Uso de plasma fresco congelado 15 ml/kg com cuidado para evitar hipervolemia, no\npré-operatório.","B":"Uso de complexo protrombínico (fatores de coagulação II, VII, IX, X), de preferência com fator\nVII\nativado, no pré-operatório.","C":"Administração de plaquetas, ocasionalmente DDAVP, ou auxílio do tromboelastograma como\nguia em caso de sangramento.","D":"Suspender AAS e clopidogrel e operar após 10 dias."},"answer":"C","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-200483","number":"200483","sourceNumber":"200483","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Um paciente de 5 anos de idade, em tratamento de leucemia, comparece ao Pronto\nAtendimento (PA) com febre, início há 24h. A mãe relata que a criança fez quimioterapia há duas\nsemanas. A criança é triada e levada imediatamente a sala de emergência. O exame físico revela\ntaquicardia, FC= 170 bpm, perfusão capilar de 4\", prostração intensa, extremidades frias, pulsos\nfinos e hipotensão arterial. Em relação ao quadro clínico descrito acima, assinale a afirmativa\nCORRETA:","options":{"A":"Deve prescrever antibióticos e orientar iniciar após coleta de culturas, mesmo que essa coleta\ndemore.","B":"Punção de dois acessos venosos periféricos calibrosos facilitam as intervenções nesse caso.","C":"Deve solicitar hemograma, proteína C reativa, aguardar resultados para definir conduta.","D":"Hipotensão é obrigatório para o diagnóstico desse quadro na criança."},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-217190","number":"217190","sourceNumber":"217190","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"A respeito do linfoma de Hodgkin, é CORRETO afirmar:","options":{"A":"Ocorre mais frequentemente em crianças abaixo de 15 anos, idosos entre 50 e 60 anos, e\nmulheres.","B":"Apenas uma minoria pode ser curada com o tratamento disponível hoje.","C":"A doença se espalha desordenadamente, acometendo aleatoriamente grupos de linfonodos.","D":"Pessoas com imunossupressão (HIV, uso de imunossupressores para rejeição) têm mais risco\nde desenvolver a doença."},"answer":"D","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-hemato-hem-2-200513","number":"200513","sourceNumber":"200513","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Uma paciente de 2 anos de idade, apresenta exantema. Ela estava bem até duas\nsemanas atrás, quando iniciou febre e sintomas\nde ITRS (Infecção do Trato Respiratório) que\nresolveram sem tratamento. Ao exame físico, ela apresenta petéquias nas extremidades superiores\ne inferiores e no tronco. Sua contagem plaquetária é 25.000/mm³. A contagem de leucócitos é\n9.000/mm³ e o nível de hemoglobina é 11mg/dL. Em relação ao quadro clínico descrito acima,\nassinale qual o melhor próximo passo na conduta:","options":{"A":"Solicitar hemocultura e iniciar terapia antimicrobiana empírica.","B":"Administrar imunoglobulina intravenosa.","C":"Prescrever uma transfusão de plaquetas.","D":"Solicitar uma revisão do esfregaço do sangue periférico."},"answer":"D","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-184575","number":"184575","sourceNumber":"184575","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Paciente 32 anos iniciou tratamento quimioterápico para leucemia linfoblástica aguda.\nDois dias após o termino da QT, foi admitida no hospital com queixa de mal estar seguida de\nconvulsão. Qual a alteração bioquímica isolada que NÃO é consistente com o diagnóstico?","options":{"A":"Hipercalcemia.","B":"Hiperuricemia.","C":"Hipercalemia.","D":"Hipermagnesemia."},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-184599","number":"184599","sourceNumber":"184599","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Em relação a reação transfusional a concentrado de hemácias, quais sinais/sintomas\nsão de maior gravidade?","options":{"A":"Crepitações bibasais.","B":"Aumento frequência respiratória.","C":"Aumento rápido na temperatura corporal.","D":"Prurido generalizado severo."},"answer":"C","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-181210","number":"181210","sourceNumber":"181210","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Em relação à avaliação de uma criança com Plaquetopenia, assinale a alternativa\nINCORRETA:","options":{"A":"A Púrpura Trombocitopênica Idiopática (PTI) recentemente diagnosticada é geralmente\nprecedida por infecções virais.","B":"Exames complementares tais como dosagem de anticorpo contra plaquetas podem auxiliar na\nconfirmação diagnostica em alguns casos, mas podem ser falsamente negativos em uma parcela\ndos pacientes pediátricos.","C":"História clínica, exame físico e exame de hemograma interpretado corretamente permitem\nrealizar o diagnótico diferencial das plaquetopenias da infância na maior parte dos casos.","D":"Assim que diagnosticado a PTI deve-se iniciar transfusão de plaquetas a cada 4 horas."},"answer":"D","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-184616","number":"184616","sourceNumber":"184616","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Mulher de 62 anos terminou há 8 dias seu primeiro ciclo de quimioterapia adjuvante\npara câncer de mama. Apresentando febre há 3\nhoras. Queixa-se também astenia, sem nenhum\noutro sintoma localizado. T 38,4 FC:110bpm PA:95/65mmHg. Sangue e urina enviadas para\ncultura. Qual o próximo passo?","options":{"A":"Libera-la para casa e comunicar se houver crescimento nas culturas","B":"Libera-la para casa com antibiótico oral","C":"Observação 24 horas com fluidos EV","D":"Iniciar antibiótico de largo espectro"},"answer":"D","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-181211","number":"181211","sourceNumber":"181211","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"São causas de Trombocitopenia no período neonatal, EXCETO:","options":{"A":"Sepse","B":"Leucemia Congênita","C":"Enterocolite Necrotizante","D":"Plaquetopenia Aloimune"},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-181212","number":"181212","sourceNumber":"181212","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Na Púrpura Trombocitopênica Idiopática (PTI) é frequente a presença de:","options":{"A":"Eosinofilia","B":"Anemia Macrocítica","C":"Macroplaquetas","D":"Neutropenia"},"answer":"C","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-181028","number":"181028","sourceNumber":"181028","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Com relação à Trombocitopenia Imune Primária (PTI) marque a alternativa CORRETA:","options":{"A":"Além do hemograma, o aspirado de medula óssea (mielograma) deve ser realizado em todos os\npacientes com PTI para excluir outros diagnósticos.","B":"A presença de sintomas sistêmicos, como anorexia, dores articulares ou perda de peso é\ncomum na PTI.","C":"A trombocitopenia na PTI geralmente se segue a uma doença viral aguda em crianças\npreviamente hígidas.","D":"Todas as crianças com contagem de plaquetas < 30.000/mm3 mesmo que sem sangramento\ndevem receber transfusão de plaquetas pelo\nrisco aumentado de hemorragia grave."},"answer":"C","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-179218","number":"179218","sourceNumber":"179218","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"São consequências características da síndrome de Lise Tumoral, EXCETO:","options":{"A":"Hiperuricemia.","B":"Hipercalemia.","C":"Hipercalcemia.","D":"Hiperfosfatemia."},"answer":"C","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-181350","number":"181350","sourceNumber":"181350","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Analise as afirmativas a seguir sobre leucemias, linfomas e tumores da infância,\nassinalando com V as verdadeiras e com F as\nfalsas. ( ) O diagnóstico diferencial das leucemias\nquando só existe pancitopenia deve ser feito com anemia aplásica e mielofibrose; ( ) Um valioso\nmarcador tumoral nos casos de hepatoblastoma da infância é o antígeno carcinoembrionário (CEA)\nque pode ser utilizado para diagnóstico e monitoramento dos tumores; ( ) Nos casos de linfoma de\nHodgkin, com o uso de regimes terapêuticos atuais, pacientes com fatores prognósticos e doença\nem estágio inicial apresentam uma sobrevida global maior do que 95% em 5 anos; ( ) O tumor de\nWilms em estágio IV caracteriza-se por tumor em ambos os rins. Assinale a sequência CORRETA.","options":{"A":"V F V F","B":"F V F V","C":"V F F V","D":"V V F F"},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-179116","number":"179116","sourceNumber":"179116","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Paciente, sexo masculino, 40 anos, empresário, procura assistência médica por queixas\nde astenia, adinamia e epistaxe, além de\nequimoses após pequenos traumas nos últimos 3 meses,\nsendo observado quadro febril na última semana. Ao exame físico, observamos mucosas\nhipocoradas (+2/4), fígado palpável (hepatimetria de 15 cm) e um baço palpável (4 cm do rebordo\ncostal esquerdo). Na mucosa oral percebe-se uma discreta hipertrofia na mucosa gengival. Foi\nrealizado um hemograma que revelou: hemoglobina = 8 g/dl, plaquetas = 50.000/mm³ e leucócitos\n\n= 20.000/mm³ com identificação de 10% de blastos em sangue periférico. Prosseguindo a\ninvestigação, realizou-se um mielograma que evidenciou a presença de 30% de blastos. Sobre o\ndiagnóstico do paciente acima é CORRETO afirmar:","options":{"A":"Na citogenética das células neoplásicas, a presença da translocação (8;21) reforça o diagnóstico\nde leucemia linfoide do subtipo L2.","B":"A presença da hiperplasia gengival encontrada no paciente reforça o diagnóstico das leucemias\nde linhagem linfoides agudas.","C":"Na morfologia dos blastos a presença no citoplasma de filamentos eosinofílicos ? os bastonetes\nde Auer ? definem a linhagem mieloide.","D":"Na imunofenotipagem, a positividade para CD 10, 19 e 20 definem a linhagem mieloide."},"answer":"C","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-184643","number":"184643","sourceNumber":"184643","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"A leucemia representa um grupo de neoplasias malignas derivadas das células\nhematopoiéticas. Esta doença inicia sempre na\nmedula-óssea, local onde as células sanguíneas\nsão produzidas, e posteriormente invadem o sangue periférico, podendo atingir vários órgãos do\npaciente afetado. A leucemia é a doença maligna mais comum na infância, correspondendo\naproximadamente a 30% dos casos de câncer em crianças. Um tipo de Leucemia representa cerca\nde 85% dos casos de leucemias em crianças, sendo a faixa etária de maior frequência entre 2 e 5\nanos. Trata-se da:","options":{"A":"Leucemia Linfocítica Aguda (LLA).","B":"Leucemia Mielocítica Aguda (LMA).","C":"Leucemia Linfocítica Crônica (LLC).","D":"Leucemia Mielocítica Crônica (LMC)."},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-182002","number":"182002","sourceNumber":"182002","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Qual a causa mais frequente de linfoadenomegalia na infância?","options":{"A":"Hiperplasia policlonal reacional.","B":"Tuberculose.","C":"Linfoma de Hodgkin.","D":"Doença da arranhadura do gato."},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-160190","number":"160190","sourceNumber":"160190","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Paciente sexo feminino, 59 anos, portadora de linfoma não-Hodgkin estádio IV\n(acometimento ósseo e esplênico), em\ntratamento quimioterápico com R-CHOP, último ciclo há 10\ndias. Procura o pronto atendimento por orientação de seu médico assistente por ter apresentado\nem casa Tax :38oC. Paciente assintomática exceto por queixa de aparecimento de úlcera dolorosa\nem palato. Estável hemodinamicamente. Seu hemograma evidenciou 498 leucócitos. Qual a\nconduta mais adequada?","options":{"A":"Internação hospitalar, solicitar culturas e iniciar antibioticoterapia precocemente de largo\nespectro, usar monoterapia.","B":"Internação hospitalar, solicitar culturas e iniciar antibioticoterapia precocemente de largo\nespectro, usar combinação de antibióticos.","C":"Internação hospitalar, solicitar culturas e iniciar antibioticoterapia precocemente de largo\nespectro, usar combinação de antibióticos. Avaliar cobertura para anaeróbios.","D":"Inicio precoce de antibiótico com tratamento domiciliar com antibioticoterapia combinada:\nciprofloxacina + amoxicilina/clavulanato."},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-160214","number":"160214","sourceNumber":"160214","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Em relação as doenças linfoproliferativas relacionadas ao vírus da imunodeficiência\nhumana (HIV), é correto afirmar que:","options":{"A":"O linfoma de Hodkgin relacionado ao HIV se apresenta mais comumente na população com\nSIDA e CD4 abaixo de 50. O uso da terapia antirretroviral combinada não alterou a incidência\ndessa entidade","B":"O Linfoma não Hodgkin de efusão está relacionada ao vírus EBV e é a segunda neoplasia mais\ncomum na população com SIDA, perdendo apenas para o Sarcoma de Kaposi.","C":"O tratamento das doenças linfoproliferativas relacionadas ao HIV deve ser com doses reduzidas\ne a terapia antirretroviral combinada deve\nser, na maioria das vezes, descontinuada, devido ao\nrisco maior de citopenias.","D":"O Linfoma de Hodgkin não é uma doença definidora de SIDA, geralmente está relacionado ao\nEBV e se apresenta na maioria das vezes em\nestágio avançado e com sintomas B."},"answer":"D","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-157990","number":"157990","sourceNumber":"157990","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"A associação de anemia, hipercalcemia, insuficiência renal e fraturas patológicas são\ncaracterísticas de:","options":{"A":"Deficiência de vitamina D.","B":"Mieloma múltiplo.","C":"Linfoma de Hodgkin.","D":"Melanoma."},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-159448","number":"159448","sourceNumber":"159448","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Com relação às reações transfusionais, assinale a alternativa CORRETA:","options":{"A":"A sepse ocasionada pela contaminação bacteriana tem como etiologia bacteriana mais\nfrequente os germes de pele, como o S. aureus e S. epidermidis.","B":"As reações transfusionais podem ser classificadas como agudas, quando ocorrem no período de\naté 2 horas da transfusão, ou crônicas, quando ocorrem após 48 horas da transfusão.","C":"A TRALI apresenta início insidioso de hipoxemia e insuficiência respiratória durante ou até 48\nhoras após a transfusão.","D":"A reação febril não hemolítica ocorre com a frequência de 1 a 10 eventos a cada 50 transfusões,\nsendo mais frequente com o uso de\nconcentrado de hemácias."},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-157958","number":"157958","sourceNumber":"157958","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Em relação aos antiagregantes plaquetários, como a aspirina e o clopidogrel, é correto\nafirmar que:","options":{"A":"São úteis na prevenção de trombose arterial e venosa profunda.","B":"São úteis apenas na trombose venosa profunda.","C":"São úteis apenas na trombose arterial.","D":"Podem ser utilizados com segurança em associação com dicumarínicos."},"answer":"C","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-158255","number":"158255","sourceNumber":"158255","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Paciente que será submetido a cirurgia eletiva informa que é portador de doença\nhematológica que faz com que seu sangue coagule muito, tendo diversas internações por\nTrombose Venosa Profunda (TVP). Dentre as opções abaixo, qual é a causa mais comum de\nTrombose Venosa Profunda nos pacientes a serem submetidos a cirurgia?","options":{"A":"Fator V de Leiden.","B":"Síndrome do Anticorpo antifosfolípideo e deficiência de antitrombina III.","C":"Deficiência de proteína C.","D":"Deficiência de proteína S."},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-158232","number":"158232","sourceNumber":"158232","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Uma senhora de 65 anos comparece ao pronto atendimento por causa de sufusões nos\nmembros superiores não relacionadas a trauma. Sem quaisquer outras queixas atuais ou prévias. É\nhipertensa e faz uso regular de anlodipino 10 mg ao dia há 5 anos, estando bem controlada; sem\noutras comorbidades conhecidas. Ao exame, PA era de 126/74 mmHg e não havia outra alteração\nalém das lesões cutâneas relatadas. O hemograma revelou Hg 14 g/dL, leucócitos 7450/?L com\ndiferencial normal e plaquetas 6680/?L. Os testes sorológicos para HIV, vírus das hepatites B e C\nresultaram negativos. O exame do sangue periférico por hematoscopia não revelou anormalidades.\nConsiderando o caso descrito, assinale a alternativa que apresenta a conduta MAIS adequada\nnesse caso.","options":{"A":"Deve-se iniciar tratamento com glicocorticoide.","B":"Deve-se realizar transfusão de plaquetas.","C":"Deve-se utilizar a imunoglobulina intravenosa como primeira escolha.","D":"Em caso de refratariedade, o rituximabe seria o tratamento de segunda linha mais indicado\nnesse caso."},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-158041","number":"158041","sourceNumber":"158041","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Pré-escolar, 4 anos de idade, apresentou resfriado comum há 08 dias. Há 24 horas o\npai notou \"manchas vermelhas pequenas\" no\ntronco e na face. A diurese está normal. Não há\nhistória de uso de drogas, imunizações recentes ou distúrbios hematológicos na família. No exame\na criança está ativa, eupneica, hidratada, sem sangramento nas mucosas, hepatoesplenomegalia\nou linfoadenopatia. O único dado positivo é a presença de petéquias no tronco e na face. Solicitado\nhemograma que envidenciou: HB = 12,0 g/dl (11,0 a 14,5); HT = 34 ml eritro/dl (33,0 a 43,0);\nleucograma = 8.000 (diferencial normal); plaquetas = 80.000/mm³ (150.000 a 450.000). Qual a\nprincipal hipótese diagnóstica?","options":{"A":"Doença de von Willebrand.","B":"Púrpura trombocitopênica imunológica.","C":"Púrpura de Henoch-Schönlein.","D":"Leucemia linfoide aguda."},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-136689","number":"136689","sourceNumber":"136689","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"A associação de anemia, hipercalcemia, insufiência renal e fraturas patológicas são\ncaracterísticas de:","options":{"A":"Deficiência de vitamina D.","B":"Mieloma múltiplo.","C":"Linfoma de Hodgkin.","D":"Carcinoma papilífero da tiróide."},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-129284","number":"129284","sourceNumber":"129284","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Criança de 4 anos de idade, sexo feminino, é levada a uma consulta por apresentar\nquadro de prostração, febre, intermitente,\ndor em membros inferiores há 6 semanas. O seu\nexame físico mostrou palidez, petéquias, linfadenopatia e hepatoesplenomegalia. Hemograma\ncompleto revelou Hb 8g/dl, global de leucócitos 15.000mm3 com 95% de linfócitos e plaquetas\nde 40.000mm3.Considerando o caso descrito, assinale a alternativa que apresenta a PRINCIPAL\nhipótese diagnóstica deste paciente.","options":{"A":"Púrpura trombocitopênica autoimune.","B":"Leucemia linfoblástica aguda.","C":"Púrpura de Henoch Sholein.","D":"Mononucleose infecciosa."},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-135600","number":"135600","sourceNumber":"135600","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Sobre a Leucemia Linfoide Aguda (LLA), marque V para as sentenças verdadeiras e F\npara as falsas: ( ) Na suspeita de doença reumatológica, é recomendado somente iniciar\ncorticosteroides após a coleta de mielograma; ( ) A dor óssea é muito frequente, geralmente ocorre\nem membros, principalmente superiores, e pode tornar-se muito intensa; ( ) A dor óssea pode\nocorrer em qualquer horário do dia e é de difícil controle com analgésicos habituais.","options":{"A":"V, V, V.","B":"V, F, V.","C":"F, V, F.","D":"F, F, V."},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-109882","number":"109882","sourceNumber":"109882","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Paciente de 20 anos, em tratamento para linfoma de Hodgkin, recebeu quimioterapia\nem altas doses há 10 dias. Apresenta-se ao\npronto-socorro com febre de 38,5ºC há 2 horas, sem\noutras queixas e sem outras alterações ao exame físico. O hemograma revela Hb: 7,5 g/dl, Ht:\n20%, leucócitos totais: 300/mm³, neutrófilos: 50/mm³, plaquetas: 50.000/mm³. A conduta mais\nadequada no caso é:","options":{"A":"Observação clínica e tratamento com antitérmicos, dada a ausência de sintomas clínicos e\nestado geral preservado.","B":"Internação hospitalar, coleta de hemocultura e início imediato de antibioticoterapia com\ncefalosporina de 4ª geração.","C":"Internação, coleta de hemocultura e início imediato de antibioticoterapia de largo espectro com\ncarbapenêmico, vancomicina e antifúngico.","D":"Coleta de hemocultura e alta para tratamento ambulatorial com combinação de amoxicilina +\nclavulanato e ciprofloxacino."},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-103077","number":"103077","sourceNumber":"103077","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Lactente, 3 anos, é levado à consulta por apresentar febre alta, anorexia e uma massa\nna região submandibular direita, de cerca de\n4 cm, dolorosa, quente e hiperemiada. O quadro teve\ninício há 4 dias (sic). Considerando o caso descrito, assinale a alternativa INCORRETA:","options":{"A":"Deve ser realizada uma biópsia excisional ou uma punção por agulha do possível linfonodo\ndescrito.","B":"O hemograma pode mostrar uma leucocitose com neutrofilia, porém não significa\nnecessariamente que deva ser solicitado.","C":"Deve ser realizado o ultrassom da região cervical, em caso de dúvida no diagnóstico,\nconfirmando que se trata de um linfonodo nessa cadeia.","D":"O uso de antibióticos, como, por exemplo, de uma cefalosporina de primeira geração, é uma boa\nconduta, devido à grande possibilidade de ser uma linfadenite inespecífica."},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-79289","number":"79289","sourceNumber":"79289","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Nas afirmativas abaixo, marque ?V? para as verdadeiras e ?F? para as falsas e, a\nseguir, marque a alternativa que contém a\nsequência de respostas CORRETA. ( ) Colite fulminante\n(forma grave de colite por clostridium) pode ser causa de megacólon tóxico e perfuração intestinal.\nSuspeita clínica quando dor abdominal difusa, diarreia, distensão abdominal, febre, hipovolemia,\nacidose lática e leucocitose. ( ) Hipertrigliceridemia é a 3ª causa mais prevalente de pancreatite\naguda, após álcool e cálculos biliares. O risco de pancreatite inicia-se quando a trigliceridemia\nsupera em torno de 500 mg/dl e torna-se muito aumentado se trigliceridemia maior que 1000 mg/dl.\nO foco do tratamento é reduzir para menos de 500 mg/dl. ( ) Diabetes mellitus malcontrolado,\nalcoolismo, obesidade, gestação, pancreatite prévia e histórico de dislipidemia sugerem diagnóstico\nde pancreatite secundária à hipertrigliceridemia. Clinicamente, a apresentação da pancreatite é\nsimilar às de outras causas. ( ) A mielodisplasia é risco para anemia, infecção e sangramento, bem\ncomo progressão para leucemia mieloide aguda, geralmente refrataria ao tratamento. A maioria dos\npacientes morrem por consequência da insuficiência da medula óssea e não pela transformação\nleucêmica. ( ) Abuso de álcool poderá comprometer a hematopoiese e gerar pancitopenia. A\nanemia, frequentemente macrocítica, correlaciona-se à desnutrição e deficiência de folato.\n\nTrombocitopenia e, principalmente, leucopenia, correlacionam-se mais com hiperesplenismo.","options":{"A":"V, F, F, V, V.","B":"F, F, F, F, F.","C":"V, V, V, V, V.","D":"V, V, V, F, F."},"answer":"C","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-79296","number":"79296","sourceNumber":"79296","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Marque a alternativa INCORRETA:","options":{"A":"Tomografia computadorizada não é requerida no primeiro dia para diagnóstico de pancreatite\naguda. É exame importante em período\nposterior, principalmente na pesquisa de necrose\npancreática.","B":"Fator estimulador de colônia de granulócitos tem bom efeito no tratamento de neutropenia,\ndemonstrando impacto na sobrevida na maioria das situações clínicas.","C":"Hipertireoidismo subclínico está associado a risco aumentado de fibrilação atrial.","D":"Hipotireoidismo subclínico pode ser assintomático ou oligossintomático e pode estar associado a\nmaior risco cardiovascular."},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-86059","number":"86059","sourceNumber":"86059","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Sobre lise tumoral é correto afirmar, exceto:","options":{"A":"Laboratorialmente é caracterizada pelas seguintes anormalidades, hipercalemia, hiperuricemia,\nhipercalcemia e hiperfosfatemia.","B":"Tumores mais comuns são doença linfoproliferativas, tumores sólidos com maior\nquimiossensibilidade.","C":"Ocorre tipicamente 12 a 72 hs após aplicação da quimioterapia, agente biológico, corticoide ou\nradioterapia.","D":"A prevenção baseia-se em hiper-Hidratação, diurético de alça, alopurinol e Rasburicase."},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-87971","number":"87971","sourceNumber":"87971","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Uma mulher de 60 anos procura o Clínico Geral com relato de epistaxes de repetição e\ndor lombar. Ela vem observando epistaxes intermitentes há 6 semanas. A epistaxe é um problema\nrecente em sua vida. Ela vem tendo dor na região toracolombar nos últimos 3 meses, mas nega ter\nsofrido qualquer traumatismo antes de seu surgimento. A paciente também observou uma grande\nequimose e um hematoma na coxa esquerda, que apareceram após um traumatismo mínimo. A\npaciente sempre foi uma mulher saudável e ativa, e não tem internações anteriores. Entretanto, nos\núltimos 4 meses vem se sentindo progressivamente mais cansada e há 2 meses não consegue\nmais fazer suas atividades domésticas. Ultimamente, começou a ter problemas de constipação,\nanorexia, e admite uma perda de peso de 5 quilos nas últimas 3 a 5 semanas, tendo chegado a 50\nquilos de peso. O exame revela uma temperatura de 37°C, pulso 90, pressão arterial 130/70 mmHg\ne 18 incursões respiratórias por minuto. A paciente tem um aspecto de doente crônico, mas está\natenta e bem orientada. As conjuntivas, a mucosa oral e as palmas das mãos estão pálidas. Os\nexames laboratoriais iniciais foram: Hb: 9,0 g/dl, Htc: 27%; contagem de reticulócitos de 3%;\nleucometria de 3000 /mm3 com diferencial normal; contagem de plaquetas de 27.000/mm3. O\nesfregaço sanguíneo revelou hemácias de morfologia normal, porém com significativa formação de\nrouleaux. EAS: urina clara, amarela, com densidade de 1010, ausência de glicose ou proteína;\nausência de células ou bactérias no sedimento. A radiografia de tórax mostrou uma lesão lítica na\nclavícula esquerda, osteopenia difusa e fraturas compressivas em várias vértebras torácicas. As\nradiografias laterais da coluna revelaram fraturas compressivas de T-11 e T-12. Os resultados do\nlaboratório mostram: VHS: 120 mm/h; creatinina: 4,2 mg/dl; proteínas totais: 9,3 g/dl; albumina: 2,7\ng/dl, globulinas: 6,6 g/dl; cálcio: 11,2 mg/dl; LDH: 600 U/L; A análise quantitativa das\nimunoglobulinas demonstra: IgG: 5.300 mg/dl, IgA: 47 mg/dl, IgM: 23 mg/dl. A análise de urina de\n24 horas demonstra 1,4 g de proteínas identificadas como cadeias leves kapa de imunoglobulinas.\nMielograma e biópsia de medula óssea: observado o aumento acentuado de plasmócitos (37% de\nplasmócitos). Baseado na descrição do caso e nos exames laboratoriais qual o diagnóstico:","options":{"A":"Leucemia Mieloide Crônica.","B":"Mieloma Múltiplo.","C":"Linfoma.","D":"Policitemia Vera."},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-89142","number":"89142","sourceNumber":"89142","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Paciente de 12 anos, sexo masculino, cor branca, com diagnóstico de LLA (Leucemia\nLinfoide Aguda). O hemograma revelou anemia, plaquetopenia e leucocitose (32.000 leuc/mm³).\nEm relação a esse quadro, qual dos fatores sugere pior prognóstico?","options":{"A":"Idade de 12 anos.","B":"Sexo masculino.","C":"Raça branca.","D":"Bicitopenia no hemograma."},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-44502","number":"44502","sourceNumber":"44502","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"A respeito do Mieloma Múltiplo, pode-se afirmar, EXCETO:","options":{"A":"É uma gamopatia policlonal.","B":"O mielograma revela plasmocitose.","C":"A cintilografia óssea é método de investigação da extensão do MM.","D":"Ocorre, especialmente, na sexta década de vida."},"answer":"A","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-48575","number":"48575","sourceNumber":"48575","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Paciente de 8 anos de idade, portador de linfoma não Hodgkin, em quimioterapia há 6\nmeses, chega ao pronto-socorro com história de febre de 38ºC desde a noite anterior. Recebeu o\núltimo ciclo de quimioterapia há 9 dias. Ao exame físico, bom estado geral, descorado ++/4+,\nhidratado, eupneico, FC = 118 bpm, sem detecção de focos infecciosos. Assinale a alternativa\nCORRETA em relação à conduta:","options":{"A":"Colher hemograma completo, solicitar exames em busca de foco infeccioso e, se neutropênico\nsem foco, observar por 24 a 48 horas, repetindo\no hemograma e exame físico nesta ocasião.","B":"Colher hemograma completo, solicitar exames em busca de foco infeccioso e, se neutropênico\nsem foco, prescrever antibiótico via oral, com\nobjetivo de cobertura de Gram-negativos.","C":"Orientar a família quanto à curva térmica rigorosa, devendo retornar ao serviço imediatamente,\ncaso apareça algum sintoma novo ou a febre\npersista.","D":"Internar a criança imediatamente e, mesmo na ausência de neutropenia iniciar esquema de\ncobertura com antibiótico de amplo espectro, antifúngico e antiviral devido ao longo tempo de\nquimioterapia e imunossupressão.","E":"Colher hemograma completo, solicitar exames em busca de foco infeccioso e, se neutropênico\nsem foco, iniciar cobertura antibiótica de amplo\nespectro e hidratação endovenosa."},"answer":"E","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-347375","number":"347375","sourceNumber":"347375","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Uma paciente com 30 anos, branca, procura serviço de emergência devido a\nsangramento gengival e ao aparecimento de pontos\navermelhados nos membros inferiores há 15\ndias, com piora progressiva das lesões e fadiga. Nega febre, uso de medicamentos e ingesta de\nbebidas à base de quinino. Foram solicitados exames que mostraram: Ao exame físico, notou-se a\npresença de lesões na pele, com petéquias no dorso do pé e no tornozelo (sola dos pés sem\nlesões) e hemorragia bolhosa na mucosa bucal. Com base nas informações descritas, a principal\nhipótese diagnóstica é","options":{"A":"síndrome hemolítico-urêmica (SHU).","B":"púrpura trombocitopênica trombótica.","C":"trombocitopenia induzida por fármaco.","D":"púrpura trombocitopênica imunológica grave."},"answer":"D","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":["question_bank/media/medcurso/medcurso-hemato-hem-2/347375.png"],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-347380","number":"347380","sourceNumber":"347380","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Uma paciente com 40 anos, branca, encaminhada da unidade básica de saúde, é\natendida para investigação de trombose venosa profunda (TVP). Conta que apresentou um\nsegundo episódio de TVP do membro inferior esquerdo há 30 dias. Informa que faz uso de\nanticoncepcional oral desde os 18 anos e que a primeira TVP ocorreu aos 36 anos, quando foi\ntratada com varfarina por 6 meses, sem intercorrências. Conta que teve 3 gestações, a primeira\ndelas, aos 22 anos, resultou em um aborto espontâneo, as outras 2 foram a termo. Ela informa\nainda que sua mãe também já apresentou TVP. Relata também que atualmente vem fazendo uso\nde rivaroxabana. Para investigação de TVP na paciente nesse momento, deve-se solicitar","options":{"A":"anticorpos anti-beta-2 glicoproteína 1 IgG e IgM.","B":"anticorpos anticardiolipina IgG e IgM.","C":"proteína C e proteína S livre.","D":"PCR para fator V Leiden."},"answer":"D","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-349111","number":"349111","sourceNumber":"349111","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Uma menina de 6 anos em tratamento para leucemia linfoide aguda, é levada a uma\nunidade de pronto-atendimento infantil devido a pico febril de 38,5°C, sem outros sintomas\nassociados. Ela utiliza um cateter de longa permanência para a administração de quimioterapia,\nrealizada há uma semana. Seu exame físico não revela alterações. Diante do quadro clínico\napresentado, assinale a opção correta em relação à propedêutica.","options":{"A":"A paciente deve ser tratada com antibióticos de largo espectro, sendo indicada a troca imediata\ndo cateter de longa permanência.","B":"A paciente dispensa a propedêutica complementar, por se tratar de um primeiro pico febril e por\nnão haver alterações no exame físico que indiquem foco infeccioso.","C":"A paciente apresenta alto risco para neutropenia febril e, por isso, deve realizar hemograma,\nhemocultura de sangue periférico e de cateter central e provas inflamatórias.","D":"A paciente deve realizar hemograma completo e, caso o resultado indique neutrófilos < 1\n000/mm³, a investigação deve prosseguir com hemocultura, com provas inflamatórias e com\nhemocultura de cateter central."},"answer":"C","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-349093","number":"349093","sourceNumber":"349093","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Um homem de 68 anos retorna do ambulatório de referência devido a dores em coluna\ntorácica e em lombar, de intensidade progressivamente maior nos últimos 3 meses. Os exames\nrealizados apresentaram os seguintes resultados (vide imagem): A radiografia de coluna vertebral\nmostrou lesões osteolíticas e fraturas vertebrais em T11, T12, L1 e L2. Nas últimas 2 semanas, o\npaciente apresenta-se excessivamente sonolento. Considerando essas informações, a hipótese\ndiagnóstica e o exame mais adequado para confirmá-la são, respectivamente,","options":{"A":"anemia falciforme; eletroforese de hemoglobina.","B":"linfoma; biópsia de linfonodos abdominais.","C":"hiperparatireoidismo; paratormônio (PTH).","D":"mieloma múltiplo; mielograma."},"answer":"D","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":["question_bank/media/medcurso/medcurso-hemato-hem-2/349093.png"],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-347447","number":"347447","sourceNumber":"347447","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Um menino com 13 anos, previamente saudável, foi avaliado no ambulatório de\npneumologia, por causa de uma história de 20 dias de febre (> ou = 38°C), mal-estar, sudorese\nnoturna, profusa e tosse seca, que não foram modificados pelo tratamento prévio com amoxicilina.\nAo exame físico, foram observados no paciente múltiplos linfonodos de consistência endurecida,\nfixos, indolores, em cadeia cervical e supraclavicular esquerda, com diâmetro entre 2 a 5 cm cada\num. Foi realizada radiografia de tórax, que mostrou infiltrados pulmonares bilaterais, arredondados,\ne adenopatia hilar bilateral. Diante do caso descrito, assinale a opção que apresenta,\nrespectivamente, a principal hipótese diagnóstica e a conduta correta para a sua confirmação.","options":{"A":"Mononucleose; solicitar biópsia aspirativa de gânglio e sorologias específicas.","B":"Tuberculose; solicitar hemograma, hemocultura e tomografia computadorizada de alta resolução\nde corpo inteiro.","C":"Pneumonia comunitária; solicitar hemograma, hemocultura e tomografia computadorizada por\nemissão de pósitrons de tórax.","D":"Linfoma de Hodgkin; solicitar biópsia excisional de gânglio e tomografia computadorizada por\nemissão de pósitrons de corpo inteiro."},"answer":"D","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-318525","number":"318525","sourceNumber":"318525","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Um menino com 5 anos de idade, acompanhado da mãe, é atendido em unidade de\nsaúde. A mãe relata o aparecimento\nabrupto de manchas arroxeadas indolores nos membros\ninferiores da criança há 2 dias, sem outras queixas. Há 1 mês, conta que o filho apresentou quadro\nde resfriado comum, para o qual fez uso somente de soro fisiológico para lavagem nasal. Nega uso\nrecente de medicamentos ou antecedentes familiares relevantes. Ao exame clínico, o menino\napresenta regular estado geral, corado, hidratado, anictérico, acianótico, afebril e eupneico; baço\npalpável ao nível de rebordo costal esquerdo, presença de petéquias e equimoses indolores em\nmembros inferiores. Exame de Fundo de Olho sem sinais de sangramento. Sem evidências de\noutros sangramentos ou outros achados clínicos relevantes. Os exames laboratoriais iniciais\nevidenciaram hemoglobina de 12,3 g/dL (valor de referência [VR]: 12,6 g/dL); hematócrito de 38%\n(VR: 37%); contagem de 5.700 leucócitos/mm³ (VR: 5.000-15.000/mm³), com 37% de\nsegmentados, 44% de linfócitos, 1% de monócitos e contagem de plaquetas de 64.000/mm³ (VR:\n150.000-450.000/mm³). Coagulograma com um tempo de tromboplastina de 12,5 segundos (VR:\n10-14 segundos), 100% de atividade de protrombina e um tempo de tromboplastina ativada de 31\nsegundos (VR: 25-36 segundos). Considerando a principal hipótese diagnóstica para esse caso,\nqual deve ser a conduta terapêutica inicial?","options":{"A":"Terapia com corticosteroide.","B":"Internação para esplenectomia.","C":"Observação clínica ambulatorial.","D":"Administração de imunoglobulina."},"answer":"C","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-319929","number":"319929","sourceNumber":"319929","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Homem de 55 anos está, há 2 meses, com quadro de linfadenopatia cervical e axilar de\naumento progressivo, associada a febre recorrente, com temperatura axilar superior a 38°C,\nsudorese noturna e perda de peso de 6 kg desde o início das manifestações. Nega doenças\npreexistentes e uso de medicamentos, mas informa tabagismo há 35 anos, com carga tabágica de\n50 anos/maço. No exame, apresentava linfadenomegalia cervical anterior e posterior\nbilateralmente, axilares bilaterais, com gânglios de 2,5 a 4 cm de diâmetro, consistência endurecida\ne fixos. Sua temperatura axilar no momento é de 38,5°C. Radiografia de tórax mostra massa\nmediastinal de cerca de 8 cm de diâmetro. Já foram solicitados hemograma, proteína C reativa,\ntomografia computadorizada de tórax com contraste. Em relação ao caso clínico apresentado, qual\né o diagnóstico provável e qual exame complementar deve ser solicitado ainda?","options":{"A":"Citomegalovírus; sorologias.","B":"Linfoma; biópsia de gânglio cervical.","C":"Mononucleose infecciosa; sorologias.","D":"Metástase de carcinoma cervical, provavelmente tireoide; biópsia de gânglio cervical."},"answer":"D","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-2-355217","number":"355217","sourceNumber":"355217","collectionBlock":"medcurso:medcurso-hemato-hem-2","collectionLabel":"Medcurso · HEM 2","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 2","subtopic":"","stem":"Paciente sexo masculino, 80 anos, admitido em hospital devido à síndrome\nconsumptiva, dor no corpo, astenia e mal-estar\ngeneralizado. Aos exames laboratoriais, notam-se\ncálcio total 15 mg/dL, hemoglobina 8 g/dL, proteína total 9,8 g/dL, globulina 7,3 g/dL, albumina 2,5\ng/dL e creatinina de 2 mg/dL. Com base nos dados expostos, a melhor hipótese diagnóstica e o\nexame a ser realizado são, respectivamente,","options":{"A":"linfoma e biópsia de linfonodo.","B":"mieloma múltiplo e mielograma.","C":"hiperparatireoidismo primário e dosagem de paratormônio.","D":"sarcoidose e dosagem da ECA.","E":"amiloidose e biópsia de rim."},"answer":"B","source":"Hemato/HEM 2/HEM 2.txt","sourceLabel":"Medcurso · HEM 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 2","Medcurso"],"answerSource":"explicit","commentDeferred":true}]};
